local config = {
  ui_story_5084_50840100_1_dialog_content = "여긴... 무덤인가?",
  ui_story_5084_50840100_2_dialog_content = "「왈라키아여, 네 운명은 이미 드러났다. 그러나 네 마음속에는 망설임이 있는 것 같군.」",
  ui_story_5084_50840100_3_dialog_content = "힘에는 대가가 따른다는 건 알고 있어.\n사로잡힌 죄수가 되어, 불안에 떨며 살아가게 되겠지.",
  ui_story_5084_50840100_4_dialog_content = "난 내 부모처럼 강대하면서도 고통스럽고, 왈라키아의 피를 마지막 한 방울까지\n흘려보낸 끝에야 비로소 안식을 얻을 수 있었던 신세가 되고 싶진 않아.",
  ui_story_5084_50840100_5_dialog_content = "「너는 왈라키아의 신도가 아니다. 우리는 같다. 오직 진리의 주인만을 신봉하지.」",
  ui_story_5084_50840100_6_dialog_content = "「너는 이 세계를 다니며 자신의 영역을 넓혔다. 너는 진리의 신도다.」",
  ui_story_5084_50840100_7_dialog_content = "「진리의 주인이 강림하길 바라면서, 어째서 희생을 두려워하는 것이냐.」",
  ui_story_5084_50840100_8_dialog_content = "내가 뭘 하길 원해?",
  ui_story_5084_50840100_9_dialog_content = "「네가 나의 힘과 몸을 되찾아 준다면, 그 대가로 너의 힘을 뽑아내어\n네가 하루빨리 눈을 감을 수 있게 해 주겠다.」",
  ui_story_5084_50840100_10_dialog_content = "「나는 위험한 것들을 맛보는 것을 좋아한다.」",
  ui_story_5084_50840100_11_dialog_content = "「그 안에는 진리의 맛이 숨어 있기 때문이지.」",
  ui_story_5084_50840100_12_dialog_content = "빅토리아 님, 무엇이 보이셨습니까?",
  ui_story_5084_50840100_13_dialog_content = "핏빛 성전과 계약을 맺었을 때의 일이었어. 그때 성전은 이 반지의 미래를 보여주지 않았지.",
  ui_story_5084_50840100_14_dialog_content = "하지만 이 반지는 이렇게 내 손으로 돌아왔어...\n아직 보이진 않지만, 오래된 힘이 날 부르는 게 느껴져.",
  ui_story_5084_50840100_15_dialog_content = "반지를 잡은 순간 느꼈던 익숙한 따끔거림도...",
  ui_story_5084_50840100_16_dialog_content = "그 반지와 무슨 관계가 있으신 겁니까?",
  ui_story_5084_50840100_17_dialog_content = "이건 역대 진리의 결사 지도자의 소유물이었어. 왈라키아 선조의 유물이고.",
  ui_story_5084_50840100_18_dialog_content = "그렇다면 주인에게 돌아온 셈이니, 기쁜 일이 아니겠습니까?",
  ui_story_5084_50840100_19_dialog_content = "중요한 건 반지 자체가 아니라 이게 나타난 시점이야.",
  ui_story_5084_50840100_20_dialog_content = "성명제가 다가오는 이 순간, 이미 오랫동안 행방을 알 수 없던 반지가\n갑자기 내 손으로 돌아왔어.",
  ui_story_5084_50840100_21_dialog_content = "......!",
  ui_story_5084_50840100_22_dialog_content = "빅토리아 님!",
  ui_story_5084_50840100_23_dialog_content = "흐하하하... 왈라키아...",
  ui_story_5084_50840100_24_dialog_content = "네놈이! 으윽...!",
  ui_story_5084_50840100_25_dialog_content = "크아아아아악──!",
  ui_story_5084_50840100_26_dialog_content = "빅토리아 님!",
  ui_story_5084_50840100_27_dialog_content = "방금 그건...",
  ui_story_5084_50840100_28_dialog_content = "과거에 벌어진 사건 같으면서도... 「미래」의 예언 같아...",
  ui_story_5084_50840100_29_dialog_content = "<color=#e8d9bb>휘리릭──</color>",
  ui_story_5084_50840100_30_dialog_content = "「초대받은 변혁자.」",
  ui_story_5084_50840100_31_dialog_content = "「무덤은 방문을 기다린다.」",
  ui_story_5084_50840100_32_dialog_content = "「진리에 대한 이해는 검증이 필요한 법.」",
  ui_story_5084_50840100_33_dialog_content = "「성전은 옛 달과 만나고.」",
  ui_story_5084_50840100_34_dialog_content = "「그것은 이미 찾아온 시간이다.」",
  ui_story_5084_50840100_35_dialog_content = "......",
  ui_story_5084_50840100_36_dialog_content = "빅토리아 님, 이번 계시는 왠지 조금 모호해 보이는군요.",
  ui_story_5084_50840100_37_dialog_content = "반지에 대한 과거의 예언과 함께 생각해 보면, 이 계시는 아주 명확해.",
  ui_story_5084_50840100_38_dialog_content = "「때가 되매, 성명제에서 예기치 못한 만남이 있으리라.」",
  ui_story_5084_50840100_39_dialog_content = "「진리에 대한 이해를 검증하고자 한다면, 밤하늘 무덤의 수호자를 찾아가라.」",
  ui_story_5084_50840100_40_dialog_content = "「이번 행동에는 아이테르를 데려가야 한다.」",
  ui_story_5084_50840100_41_dialog_content = "핏빛 성전이 구절을 도치해서 예언한 건 처음이야.",
  ui_story_5084_50840100_42_dialog_content = "아무래도 이 사라진 지 오래였던 반지가 주는 계시는...\n아직 목도하지 못한 시일과 이어지게 될지도 모르겠네.",
  ui_story_5084_50840100_43_dialog_content = "그렇게 말씀하시니 저도 이해했습니다.",
  ui_story_5084_50840100_44_dialog_content = "그 「신선한 피」는 네가 데리고 와 줘.",
  ui_story_5084_50840100_45_dialog_content = "알겠습니다, 빅토리아 님.",
  ui_story_5084_50840100_46_dialog_content = "오는 동안 설명을 듣긴 했지만, 그래도 역시 모르겠어.\n진리의 결사의 축제 행사에 왜 날 데리고 가는 건데?",
  ui_story_5084_50840100_47_dialog_content = "진리의 주인과 빅토리아 님의 지시다.",
  ui_story_5084_50840100_48_dialog_content = "휴, 너희 진리의 결사는 진짜...",
  ui_story_5084_50840100_49_dialog_content = "그나저나 움브라톤에서 꽤 멀리 온 것 같은데, 여긴 어디야?",
  ui_story_5084_50840100_50_dialog_content = "으악──!",
  ui_story_5084_50840100_51_dialog_content = "<color=#e8d9bb>콰당──!</color>",
  ui_story_5084_50840100_52_dialog_content = "이 새까만 거... 왜 움직이는 거야?!",
  ui_story_5084_50840100_53_dialog_content = "누가 깨우러 왔나 했더니, 흰둥이였네.",
  ui_story_5084_50840100_54_dialog_content = "...스칼렛?",
  ui_story_5084_50840100_55_dialog_content = "다리에 걸린 건 네가 조종한 덩굴이었어?",
  ui_story_5084_50840100_56_dialog_content = "남을 밟았으면 사과해야지. 오히려 나한테 묻는 거야?",
  ui_story_5084_50840100_57_dialog_content = "미, 미안... 근데 네가 왜 여기 있어?",
  ui_story_5084_50840100_58_dialog_content = "그것도 내가 할 말인데, 다들 여기 무슨 볼일 있어?",
  ui_story_5084_50840100_59_dialog_content = "모두 제 잘못입니다. 이미 오늘 아침부터 알고 있었습니다.\n오늘 제가 용서받을 수 없는 잘못을 저지를 거란 사실을 말입니다.",
  ui_story_5084_50840100_60_dialog_content = "스칼렛 양이 허락해 주신다면, 이곳에서 참회하고 싶습니다...",
  ui_story_5084_50840100_61_dialog_content = "모두 모였습니다, 빅토리아 님.",
  ui_story_5084_50840100_62_dialog_content = "빅토리아 님...",
  ui_story_5084_50840100_63_dialog_content = "전에 넌 아직 때가 되지 않았다고 했었지.\n밤하늘 무덤에 숨겨진 비밀은 나조차 엿볼 수 없다고도 했었고.",
  ui_story_5084_50840100_64_dialog_content = "그런데 지금 핏빛 성전이 여길 방문하라는 계시를 줬어.",
  ui_story_5084_50840100_65_dialog_content = "이번엔 어떤 유물을 손에 넣으셨는지 알 수 있을까요.",
  ui_story_5084_50840100_66_dialog_content = "이거야.",
  ui_story_5084_50840100_67_dialog_content = "계시의 내용이 그렇다면, 확실히 밤하늘 무덤에서 진상을 확인할 권리가 있으시네요.",
  ui_story_5084_50840100_68_dialog_content = "밤하늘 무덤은 어떤 곳이야?",
  ui_story_5084_50840100_69_dialog_content = "속된 말로 하면 죽은 사람이 묻혀 있는 곳이야.",
  ui_story_5084_50840100_70_dialog_content = "...뭐어?! 파우스트는... 곧 다가올 진리의 결사의 축제를 준비하러 왔다고 그랬는데!",
  ui_story_5084_50840100_71_dialog_content = "「곧 다가올」 것을 준비하려면 여긴 반드시 와야 할 곳이야.",
  ui_story_5084_50840100_72_dialog_content = "긴장할 거 없어. 안에는 백야성의 모든 재물을 모은 것보다 더 값진 것들이 있다고 하거든.",
  ui_story_5084_50840100_73_dialog_content = "수많은 사람들이 무덤의 비밀을 캐내려 했지만, 결국 안에서 목숨을 잃었어.\n그렇게 생각하면 넌 오히려 운이 좋은 거야.",
  ui_story_5084_50840100_74_dialog_content = "아무리 보물이 있다고 해도 그렇지! 보물... 음, 진지하게 생각해 볼 만한 것 같아...",
  ui_story_5084_50840100_75_dialog_content = "그 전에, 밤하늘 무덤에 들어가려는 자에게 말해줄 조언이 세 가지 있어.",
  ui_story_5084_50840100_76_dialog_content = "첫째, 피는 「파리아」가 진입자를 식별하는 유일한 표식이야.\n피의 계약을 맺은 자만이 무덤에 들어갈 수 있어.",
  ui_story_5084_50840100_77_dialog_content = "그리고 「파리아」가 열어놓은 또 다른 문은 계약자의 인도를 따르게 돼 있어.",
  ui_story_5084_50840100_78_dialog_content = "이게 바로 「파리아」야.",
  ui_story_5084_50840100_79_dialog_content = "둘째, 소지품도 마찬가지로 그것들을 이끄는 존재가 있어.\n그것들은 시간의 소유가 되고, 시간의 향방에 따라 자신이 귀속될 장소로 향하게 돼.",
  ui_story_5084_50840100_80_dialog_content = "셋째, 「운명은 이미 새겨졌다. 의심하지 말고, 증오하지 말며, 개변하지 말지어다.」",
  ui_story_5084_50840100_81_dialog_content = "흰둥이 넌 물어보고 싶은 게 많아 보이는데?",
  ui_story_5084_50840100_82_option_content = "피의 맹세?",
  ui_story_5084_50840100_83_dialog_content = "피를 흘려야 된다는 뜻이야?",
  ui_story_5084_50840100_84_dialog_content = "위대하신 주여, 절 버리지 않으신다면, 제 더러운 피를 모두 가져가 주시옵소서...",
  ui_story_5084_50840100_85_option_content = "운명을 의심하지 말라고?",
  ui_story_5084_50840100_86_dialog_content = "설마... 소설에 나오는 「타임슬립」 같은 거야?",
  ui_story_5084_50840100_87_dialog_content = "조금 전까지도 불안해하더니 순식간에 기대하는 표정이 됐네.",
  ui_story_5084_50840100_88_dialog_content = "파리아, 준비.",
  ui_story_5084_50840100_89_dialog_content = "자, 잠깐만! 근데... 아이테르의 피도 괜찮은 거야?",
  ui_story_5084_50840100_90_dialog_content = "에잇──!",
  ui_story_5084_50840100_91_dialog_content = "<size=45>으아악!</size>",
  ui_story_5084_50840100_92_dialog_content = "파리아가 열린다고 스칼렛 언니가 말한 거 못 들었어?",
  ui_story_5084_50840100_93_dialog_content = "빅토리아 님, 저랑 「베이비」도 데려가 주세요! 말 잘 들을게요!",
  ui_story_5084_50840100_94_dialog_content = "네가 혼자 여기 온 거, 레노어는 알고 있니?",
  ui_story_5084_50840100_95_dialog_content = "물론 알죠. 언니는 「메이는 즐겁게 놀아야 합니다」라고 했어요.",
  ui_story_5084_50840100_96_dialog_content = "여기 베이비의 실도 많이 모았어요! 어떤 상처든지 꿰맬 수 있어요!",
  ui_story_5084_50840100_97_dialog_content = "PlayerName, 얼른 이리 와. 지금부터는 내가 널 돌봐줄게.",
  ui_story_5084_50840100_98_dialog_content = "야옹~",
  ui_story_5084_50840100_99_dialog_content = "...너랑은 좀 떨어져 있는 편이 더 안전할 것 같은데?!",
  ui_story_5084_50840100_100_dialog_content = "다들 준비는 된 모양이네. 파리아, 시동!",
  ui_story_5084_50840100_101_dialog_content = "진리의 주인이시여, 절 수수께끼의 끝으로 인도하소서.",
  ui_story_5084_50840100_102_dialog_content = "진리의 주인이시여, 부디 저희들의 여정을 지켜주소서.",
  ui_story_5084_50840100_103_dialog_content = "진리의 주인이시여, 제 죄를 심판하소서.",
  ui_story_5084_50840100_104_dialog_content = "진리의 주인님, 메이를 재밌는 곳으로 인도해 주세요.",
  ui_story_5084_50840100_105_dialog_content = "메, 메이! 그렇게 내 옷 잡아당겨 봤자...",
  ui_story_5084_50840100_106_dialog_content = "으악...!",
  ui_story_5084_50840100_107_dialog_content = "스칼렛... 스칼렛...!",
  ui_story_5084_50840100_108_dialog_content = "살려줘...",
  ui_story_5084_50840100_109_dialog_content = "흰둥아, 왜 눈 감고 괴로운 척하는 거야?",
  ui_story_5084_50840100_110_dialog_content = "눈 떠. 여긴 아무 위험도 없으니까.",
  ui_story_5084_50840100_111_dialog_content = "...근데 아까 그 빽빽한 덩굴에 긁혀서 간지럽고 무섭단 말이야.",
  ui_story_5084_50840100_112_dialog_content = "너 설마 진리를 탐구하고 싶지 않은 거야?\n아, 잊고 있었네. 넌 아직 진리의 결사 멤버가 아니었지.",
  ui_story_5084_50840100_113_dialog_content = "...스칼렛 너 진짜 남의 일은 하나도 신경 안 쓰는구나.",
  ui_story_5084_50840100_114_dialog_content = "그나저나 다들 진짜 순식간에 사라져 버렸잖아?",
  ui_story_5084_50840100_115_dialog_content = "그것보다 네가 아직 여기에 있다는 게 더 문제야.",
  ui_story_5084_50840100_116_dialog_content = "너도 아마 들어본 적 있겠지.\n진리에 다가가려면 평소의 사고에서 벗어나 감각을 통해 사방을 탐색해야만 해.",
  ui_story_5084_50840100_117_dialog_content = "넌 아이테르니까 그건 잘하겠지.",
  ui_story_5084_50840100_118_dialog_content = "나는 어디에 있으며, 누구이고, 어디로 가는가... 그런 거 말이야.",
  ui_story_5084_50840100_119_dialog_content = "되게 심오하네... 난 그냥 파우스트가 쉽게 참가할 수 없는 축제가 있다고 해서 온 건데.",
  ui_story_5084_50840100_120_dialog_content = "그럼 축제만 생각해. 만약 아직도 무서우면, 덩굴 속에서 촛대를 찾아봐.",
  ui_story_5084_50840100_121_dialog_content = "촛대...?",
  ui_story_5084_50840100_122_dialog_content = "어라... 진짜 있잖아...?",
  ui_story_5084_50840100_123_dialog_content = "그게 널 이끌어 줄 거야.\n대신 노는 데 정신 팔려 있지 말고, 촛불이 꺼지기 전에 잊지 말고 돌아와.",
  ui_story_5084_50840100_124_dialog_content = "응... 근데... 돌아오라니? 어떻게? 어디로?",
  ui_story_5084_50840100_125_dialog_content = "...스칼렛?",
  ui_story_5084_50840100_126_dialog_content = "스칼렛!",
  ui_story_5084_50840201_1_dialog_content = "(스칼렛한테 촛대를 받아서 다행이야... 여긴 너무 어둡잖아...)",
  ui_story_5084_50840201_2_dialog_content = "(어디로 가야 사람들을 찾을 수 있을까...)",
  ui_story_5084_50840201_3_dialog_content = "(...여긴?)",
  ui_story_5084_50840201_4_dialog_content = "<color=#e8d9bb>밤의 장막 위에는 피의 달이 새겨져 있었다.\n낡은 시계 소리가 울리자, 우뚝 솟은 시계탑이 피의 달을 향해 빠르게 뻗어갔다.</color>",
  ui_story_5084_50840201_5_dialog_content = "<color=#e8d9bb>그것은 신도들이 밟은 돌멩이 하나하나, 정교한 무늬가 새겨진 문틀과 벽을 비추었다.</color>",
  ui_story_5084_50840201_6_dialog_content = "<color=#e8d9bb>그것은 진리의 전당 속 참회에 귀를 기울이고, 피의 일족의 영광과 비밀에 대해 말했다...</color>",
  ui_story_5084_50840201_7_dialog_content = "<color=#e8d9bb>똑똑──</color>",
  ui_story_5084_50840201_8_dialog_content = "(이 바닥 진짜였잖아? 벽도 진짜고... 신기하네!)",
  ui_story_5084_50840201_9_dialog_content = "(설마 진실의 관 때처럼 여기 온 사람들 전부 지금 무슨 일이 발생한 건지\n모르는 건 아니겠지...)",
  ui_story_5084_50840201_10_dialog_content = "아, 피의 달이 나타났군. 3년에 한 번 있는 성명제 행진도 이제 곧 시작되겠지.",
  ui_story_5084_50840201_11_dialog_content = "기도할 내용은 이미 준비해 두었습니다.\n행진 때 온 마음과 뜻으로 진리의 주인께 들려 드릴 겁니다.",
  ui_story_5084_50840201_12_dialog_content = "행진에서 하는 것만으로는 소용없다. 「계시를 받을 자」로 뽑혀야지.\n자신을 제물로 바쳐야 진리의 주인께서 기도를 듣고 답해주실 거다.",
  ui_story_5084_50840201_13_dialog_content = "(왈라지 마을... 여기가 진리의 결사의 성대한 의식이 진행되는 곳?\n성명제... 행진...?)",
  ui_story_5084_50840201_14_dialog_content = "(난 여기 어떻게 온 거지? 다른 사람들은 다들 어디 간 거지...?)",
  ui_story_5084_50840201_15_dialog_content = "첫째는 독서, 학습, 교류야.\n진리의 결사엔 똑똑한 언니, 오빠들이 많아서 평생 배워도 다 못 배울 지식을 가르쳐 줘.",
  ui_story_5084_50840201_16_dialog_content = "둘째는 식사, 집회, 진리의 주인님을 향한 찬미야.",
  ui_story_5084_50840201_17_dialog_content = "매일 같이 식사 모임을 하면, 사람들이 흔히 말하는 「진리란 무엇인가」라는 문제도\n분명히 깨달을 수 있을 거야.",
  ui_story_5084_50840201_18_dialog_content = "셋째는 발굴, 탐험이야.\n천부적인 재능이 있으면 모두한테 칭찬받는 보물을 캐낼 수 있을 거야.",
  ui_story_5084_50840201_19_dialog_content = "그치만 단순히 탐험을 좋아하는 거라고 해도, 진리의 결사에 들어오는 건 좋은 선택이야.\n예전의 나처럼 말이야.",
  ui_story_5084_50840201_20_dialog_content = "진리의 결사에 가입한 뒤로는 「베이비」의 털도 덜 빠지기 시작했다구.",
  ui_story_5084_50840201_21_dialog_content = "게다가 금방 빅토리아 님한테 인정을 받아서 중요한 일도 자주 혼자 맡게 됐어.",
  ui_story_5084_50840201_22_dialog_content = "어때? 진리의 결사에 가입하고 싶어지지?",
  ui_story_5084_50840201_23_dialog_content = "야옹~",
  ui_story_5084_50840201_24_dialog_content = "거 되게 자신감이 넘치네...",
  ui_story_5084_50840201_25_dialog_content = "꼬마야, 옷부터 제대로 좀 입고 다시 올래?",
  ui_story_5084_50840201_26_dialog_content = "그 빅토리아 님이라는 사람, 왈라키아 가문의 따님 말하는 거지?\n정말로 너 같은 꼬마애한테 일을 맡긴단 말이야...?",
  ui_story_5084_50840201_27_dialog_content = "게다가 거기 당신, 왈라지 마을은 처음이지?",
  ui_story_5084_50840201_28_dialog_content = "그럼 내가 진리의 결사의 기원이나 교의, 무덤에 잠들어 있는 비밀을\n가르쳐 줄 수도 있는데...",
  ui_story_5084_50840201_29_dialog_content = "어? 당신들 진짜 진리의 결사 선배야...?\n그치만 내가 아는 사람들이랑은 다른 거 같은데...",
  ui_story_5084_50840201_30_dialog_content = "메이...!",
  ui_story_5084_50840201_31_dialog_content = "PlayerName? 왜 잡아당기고 그래?\n내가 방금 저 두 사람 거의 가입시킬 뻔했단 말이야.",
  ui_story_5084_50840201_32_dialog_content = "저 사람들이 그럴 생각은 전혀 없어 보인다는 건 일단 둘째 치고...",
  ui_story_5084_50840201_33_dialog_content = "여기 사람들이 계속 행진이나 성명제 얘기하는 거 못 들었어?\n우린 지금 빅토리아 씨의 고향, 왈라지 마을에 와 있는 거라고!",
  ui_story_5084_50840201_34_dialog_content = "빅토리아 님의 고향...? 왠지 전에 들었던 것 같아. 근데?",
  ui_story_5084_50840201_35_dialog_content = "하나도 안 놀랐어? 다른 사람은 어디 갔는지 안 궁금해?",
  ui_story_5084_50840201_36_dialog_content = "아하하, 이해했어. 다들 축제에 참가하려고 옷 갈아입으러 간 거겠네!",
  ui_story_5084_50840201_37_dialog_content = "저 사람들한테 옷 어디서 산 건지 물어보고 우리도 사러 가자!",
  ui_story_5084_50840201_38_dialog_content = "하아? 왜 넌 그렇게 신난 거야?!\n근데 여긴 왠지 상점보단 음산한 재봉소 같은 게 나올 것 같은 곳인데...",
  ui_story_5084_50840201_39_dialog_content = "어라... 메이?",
  ui_story_5084_50840201_40_dialog_content = "들어 봐! 행진 대열이 오고 있어! 미아가 안 되게 얼른 내 손 잡아.",
  ui_story_5084_50840201_41_dialog_content = "저 관엔 왈라키아의 선조가 들어 있대. 진리의 주인님한테 선택된 사람이라구!",
  ui_story_5084_50840201_42_dialog_content = "<color=#e8d9bb>핏빛의 달이 지켜보는 가운데, 화려한 의상을 사람들 한 무리가\n오랜 역사가 담긴 고귀한 관을 메고 서서히 행진했다.</color>",
  ui_story_5084_50840201_43_dialog_content = "<color=#e8d9bb>관에 누워 있는 왈라키아의 「선조」라고 불리는 존재는 신성한 책을 품에 안고,\n피의 달과 함께 진리를 전파하고 있었다.</color>",
  ui_story_5084_50840201_44_dialog_content = "<color=#e8d9bb>신도들은 경외하며 그 뒤를 따랐고, 눈을 깜빡이는 것조차 두려워하며 관을 응시했다.</color>",
  ui_story_5084_50840201_45_dialog_content = "<color=#e8d9bb>그들은 마을의 모든 거리를 지나, 진리의 전당의 웅장한 정문 앞까지 다다랐다.</color>",
  ui_story_5084_50840201_46_dialog_content = "<color=#e8d9bb>쿵──</color>",
  ui_story_5084_50840201_47_dialog_content = "행진 의식의 종료와 함께 진리가 찾아왔도다.",
  ui_story_5084_50840201_48_dialog_content = "신도들은 주께 다가갔고, 주를 향한 봉헌을 완수하였노라.",
  ui_story_5084_50840201_49_dialog_content = "진리의 주인께 감사드립니다!",
  ui_story_5084_50840201_50_dialog_content = "진리의 주인께 일생을 바치겠습니다!",
  ui_story_5084_50840201_51_dialog_content = "이제...",
  ui_story_5084_50840201_52_dialog_content = "신도 가운데 한 자가 있어 신성한 부름을 받으매,\n저 무한한 계시로 충만한 공허의 관에 발을 들여 진리의 소리를 들으리라.",
  ui_story_5084_50840201_53_dialog_content = "그대의 통찰력은 범속을 초월하여, 어둑한 땅에서 역사의 수수께끼를 살펴 알리니. ",
  ui_story_5084_50840201_54_dialog_content = "그대는 수행자일 뿐 아니라 온 진리의 결사가 지닌 지혜의 구현이요. ",
  ui_story_5084_50840201_55_dialog_content = "그대가 겪은 모든 경험이 진리의 결사를 미래로 인도하리라. ",
  ui_story_5084_50840201_56_dialog_content = "그대는 허무의 강에 몸을 담글 것이요, 시공의 경계가 그 곁에서 뒤섞이고 풀릴지어다.",
  ui_story_5084_50840201_57_dialog_content = "오직 진리의 주인께서 강림하사 그대의 자아를 씻어야만,\n비로소 탈바꿈을 이루어 가장 순수한 본질만 남으리라.",
  ui_story_5084_50840201_58_dialog_content = "진리, 경청, 계시, 각성.",
  ui_story_5084_50840201_59_dialog_content = "때가 이르면 그대는 신성한 존재와의 공명을 이룰 것이다.",
  ui_story_5084_50840201_60_dialog_content = "빌헬름 님, 부디 절 봐 주십시오!",
  ui_story_5084_50840201_61_dialog_content = "더 많은 진리를 듣고 싶습니다...!",
  ui_story_5084_50840201_62_dialog_content = "더 많은 진리를 듣고 싶어요!",
  ui_story_5084_50840201_63_dialog_content = "...! 쉿!",
  ui_story_5084_50840201_64_dialog_content = "겨우 숨어들었는데 조용히 좀 해...",
  ui_story_5084_50840201_65_dialog_content = "그치만 난 진리의 결사의 간부가 되고 싶다구. 그러려면 진리의 이야기를 더 많이 들어야 해!\n지금이 절호의 기회잖아! 「베이비」, 가자!",
  ui_story_5084_50840201_66_dialog_content = "「운명은 이미 새겨졌다. 의심하지 말고, 증오하지 말며, 개변하지 말지어다.」",
  ui_story_5084_50840201_67_dialog_content = "냐앙...?",
  ui_story_5084_50840201_68_dialog_content = "스칼렛이 당부했던 말, 벌써 잊어버린 거니? 메이.",
  ui_story_5084_50840201_69_dialog_content = "...어라... 빅토리아 님?!",
  ui_story_5084_50840201_70_dialog_content = "엥? 그 복장은 뭔데?",
  ui_story_5084_50840201_71_dialog_content = "나야말로 묻고 싶네. 너흰 그런 모습으로 어떻게 여기 들어왔니?",
  ui_story_5084_50840201_72_dialog_content = "메이한테 붙잡혀서, 그 뒤엔 계속 신도들을 따라 밀치락달치락하며 들어왔어.",
  ui_story_5084_50840201_73_dialog_content = "그럼 여기가 어딘지도 이미 알고 있겠지?",
  ui_story_5084_50840201_74_dialog_content = "신도들 이야기를 듣고 알았어. 여긴 빅토리아 씨 고향... 왈라지 마을이지?\n근데 이 느낌, 우리 설마...",
  ui_story_5084_50840201_75_dialog_content = "여긴 과거의 시간이야.",
  ui_story_5084_50840201_76_dialog_content = "과거?",
  ui_story_5084_50840201_77_dialog_content = "이 당시의 난 아직 진리의 결사에 들어가지 않았고,\n그저 진리를 알기 위해 세계를 누비고 있었어.",
  ui_story_5084_50840201_78_dialog_content = "지금은 1915년이야. 이번 성명제가 끝나면, 저 진리의 결사의 지도자는 실종될 거야.",
  ui_story_5084_50840201_79_dialog_content = "...저 사람이? 어디로 가는데?",
  ui_story_5084_50840201_80_dialog_content = "진리의 주인은 저 반지를 통해 날 여기로 인도하셨어. 역시 스칼렛이 말한 대로네.\n물건은 시간에 속하고, 시간은 그것들을 제자리로 데려오는 거야.",
  ui_story_5084_50840201_81_dialog_content = "지금 핏빛 성전은 선조의 품으로 돌아갔고, 반지는 지도자의 손에 돌아갔어.",
  ui_story_5084_50840201_82_dialog_content = "왈라키아의 피의 저주는 세월이 얼마나 흘러도 여전히 떨쳐낼 수 없는 거야.",
  ui_story_5084_50840201_83_dialog_content = "그대는 계시를 받고, 저 시간을 넘어서는 강의 의문을 메워야만 한다.",
  ui_story_5084_50840201_84_dialog_content = "그대는 진리에 귀를 기울이고, 세상에 대한 이해를 더 넓혀야 한다.",
  ui_story_5084_50840201_85_dialog_content = "나는 진리의 결사의 지도자 빌헬름 왈라키아의 이름으로,\n진리의 주인의 인도에 따라 성명제의 계시를 받을 자를 공표하노라.",
  ui_story_5084_50840201_86_dialog_content = "빅토리아 왈라키아.",
  ui_story_5084_50840201_87_dialog_content = "흐음...?",
  ui_story_5084_50840201_88_dialog_content = "빅토리아 왈라키아, 그녀가 왜 여기에...",
  ui_story_5084_50840201_89_dialog_content = "후훗, 재미있네.",
  ui_story_5084_50840201_90_dialog_content = "......",
  ui_story_5084_50840201_91_dialog_content = "빅토리아 아가씨? 아가씨도 오셨다!",
  ui_story_5084_50840201_92_dialog_content = "왈라키아 가문의 외동딸...",
  ui_story_5084_50840201_93_dialog_content = "하지만 가주들은 저분을 인정하지 않고 있다던데...",
  ui_story_5084_50840201_94_dialog_content = "......",
  ui_story_5084_50840301_1_dialog_content = "<size=30>...빅토리아 님이야!</size>",
  ui_story_5084_50840301_2_dialog_content = "너 뭘 신난 거야?! 그러다간 과거 사람들한테 주목당한다고!",
  ui_story_5084_50840301_3_dialog_content = "우리가 여기 온 규칙을 깨면 어떡하려고 그래?",
  ui_story_5084_50840301_4_dialog_content = "마음의 인도에 따르렴. 계시는 틀리지 않을 거야.\n이미 인도를 받은 사람이 있다면 또 모를까.",
  ui_story_5084_50840301_5_dialog_content = "진리의 신도들이여, 다음 피의 달을 기대하라.\n진리의 주인은 영원히 그대들을 지켜보며, 그대들이 다가오길 바라고 계신다.",
  ui_story_5084_50840301_6_dialog_content = "진리의 축복 있으라.",
  ui_story_5084_50840301_7_dialog_content = "진리의 축복 있으라.",
  ui_story_5084_50840301_8_dialog_content = "우리도 저 사람들이랑 같이 나가야 하나?",
  ui_story_5084_50840301_9_dialog_content = "마음의 인도에 따라 조용히 지켜보자.",
  ui_story_5084_50840301_10_dialog_content = "어떠한가.",
  ui_story_5084_50840301_11_dialog_content = "난 진리의 결사 멤버도 아닌걸. 하늘의 계시를 듣는 명예는 내게 어울리지 않아.",
  ui_story_5084_50840301_12_dialog_content = "허나 넌 진리의 전당에 발을 들이는 명예를 얻었을 때는 오히려 이의를 제기하지 않았지.",
  ui_story_5084_50840301_13_dialog_content = "진리를 추구하고, 조직을 결성한 것은 언젠가 진리의 결사에 들어올\n그날을 위한 준비가 아니었나?",
  ui_story_5084_50840301_14_dialog_content = "당신과는 전부 상관없는 일이야.",
  ui_story_5084_50840301_15_dialog_content = "넌 아직 나의 물음에 답하지 않았다. 진리란 대체 무엇이냐.",
  ui_story_5084_50840301_16_dialog_content = "......",
  ui_story_5084_50840301_17_dialog_content = "<color=#e8d9bb>콰르르릉──!</color>",
  ui_story_5084_50840301_18_dialog_content = "그보다... 하늘의 계시라고?\n빅토리아 왈라키아, 조숙한 네게 꼭 물어보고 싶군. 넌 진리를 뭐라고 생각하지?",
  ui_story_5084_50840301_19_dialog_content = "진리는... 지식이야.",
  ui_story_5084_50840301_20_dialog_content = "훗, 빅토리아 왈라키아. 우리는 같은 혈통을 지녔지만, 두뇌, 힘, 능력... 심지어 용모까지,\n그 무엇이든 내가 너보다 뛰어나다.",
  ui_story_5084_50840301_21_dialog_content = "그럼에도 불구하고, 이 반지가 네 것이라고 생각하는 이유는 무엇이냐.",
  ui_story_5084_50840301_22_dialog_content = "나야말로 진정한 왈라키아! 진리의 결사의 지도자다!",
  ui_story_5084_50840301_23_dialog_content = "넌... 우선 자신이 왈라키아의 이름에 걸맞은 자인지부터 힘써 증명해라.\n날 망신시키지 마라.",
  ui_story_5084_50840301_24_dialog_content = "......",
  ui_story_5084_50840301_25_dialog_content = "<color=#e8d9bb>콰르르릉──!</color>",
  ui_story_5084_50840301_26_dialog_content = "책 속에서 뜻을 알 수 없는 문장을 골라내고, 공명하는 환영에서 답을 찾는다...",
  ui_story_5084_50840301_27_dialog_content = "그게 네가 줄곧 답을 찾아온 방법 아니던가?",
  ui_story_5084_50840301_28_dialog_content = "아까는 또 뭘 보았고, 무슨 생각을 했지?",
  ui_story_5084_50840301_29_dialog_content = "의문? 두려움? 거절? 왈라키아의 힘을 두고 넌 선택할 자격이 없다.\n힘이 자신에게 걸맞은 자를 고르는 것이지.",
  ui_story_5084_50840301_30_dialog_content = "......",
  ui_story_5084_50840301_31_dialog_content = "(저 사람, 빅토리아 씨 가문에 전해 내려오는 반지를 끼고 있어...)",
  ui_story_5084_50840301_32_dialog_content = "빌헬름, 빅토리아가 왈라지 마을을 떠났다고 전에 네가 그랬었지...",
  ui_story_5084_50840301_33_dialog_content = "하하, 맞아.",
  ui_story_5084_50840301_34_dialog_content = "왈라키아, 이토록 총명하고 뛰어난 아가씨를 두고도 그렇게 엄격해야만 하는 건가?",
  ui_story_5084_50840301_35_dialog_content = "빅토리아 양, 오랜만이로군.",
  ui_story_5084_50840301_36_dialog_content = "그렇네.",
  ui_story_5084_50840301_37_dialog_content = "포르피리오, 그녀를 선택한 것은 진리의 주인의 인도다.\n그러나 나와 왈라키아에겐 어쩔 수 없는 일일 뿐이지.",
  ui_story_5084_50840301_38_dialog_content = "하하하하, 누굴 탓할 생각은 아니었다. 탓한다면 우리가 같은 「피의 일족」이면서도\n서로 다른 기로에 서 있음을 탓해야겠지.",
  ui_story_5084_50840301_39_dialog_content = "진리의 주인께서 또 강림하실 것 같나?\n그분께 선택받은 후계자가 자격이 부족하거나, 신앙이 부족한 것은 아닌가?",
  ui_story_5084_50840301_40_dialog_content = "그것은 우리 열두 가주의 책임이지, 모든 걸 너희 왈라키아의 탓으로 돌릴 순 없다.",
  ui_story_5084_50840301_41_dialog_content = "하하하하, 참으로 아름다우면서도 치명적인 책망이로군, 포르피리오.",
  ui_story_5084_50840301_42_dialog_content = "좋다. 계시를 어겨서는 안 되겠지.\n그렇다면... 진리의 주인이 그녀에게 무엇을 전하려 하시는지를 보는 수밖에...",
  ui_story_5084_50840301_43_dialog_content = "가주들이여!",
  ui_story_5084_50840301_44_dialog_content = "이번 성명제의 계시를 받을 자에 대해 이의는 없겠지?",
  ui_story_5084_50840301_45_dialog_content = "......",
  ui_story_5084_50840301_46_dialog_content = "없다...",
  ui_story_5084_50840301_47_dialog_content = "이의가 있다고 한들 뭐 어떻겠나.",
  ui_story_5084_50840301_48_dialog_content = "흥.",
  ui_story_5084_50840301_49_dialog_content = "얼른 시작하자. 진리의 주인께서 기다리다 지치시겠어.",
  ui_story_5084_50840301_50_dialog_content = "긴장할 필요 없다, 빅토리아 왈라키아.",
  ui_story_5084_50840301_51_dialog_content = "내가 저 신성한 전당으로 너를 안내하고, 관 속으로 보내주마.",
  ui_story_5084_50840301_52_dialog_content = "마음을 가라앉히고 사고를 정리해라. 진리에 대한 네 깨달음을 주께 보여드릴 준비를 하도록.",
  ui_story_5084_50840301_53_dialog_content = "......",
  ui_story_5084_50840301_54_dialog_content = "(아까 거리에서 신도들이 「자신을 제물로 바친다」고 말했었잖아... 이 의식은 대체...)",
  ui_story_5084_50840301_55_dialog_content = "(이 가주들, 뭔가 위험한 느낌이 들어...)",
  ui_story_5084_50840301_56_dialog_content = "(만약 빅토리아 씨가 정말로 「제물」이 되면 어떡하지?!)",
  ui_story_5084_50840301_57_dialog_content = "(안 되겠어, 빅토리아 씨가 관에 들어가기 전에 물어봐야지...)",
  ui_story_5084_50840301_58_option_content = "(감응 연결!)",
  ui_story_5084_50840301_59_dialog_content = "드디어 따라잡았구나.",
  ui_story_5084_50840301_60_dialog_content = "이거 무슨 문제라도 생기는 거 아냐...?\n진짜로 그 사람 따라 관에 들어가서 「제물」이 될 거야?!",
  ui_story_5084_50840301_61_dialog_content = "응.",
  ui_story_5084_50840301_62_dialog_content = "그...그럼 나랑 메이는 어떡하라고?!",
  ui_story_5084_50840301_63_dialog_content = "스칼렛이 한 말, 기억하니?",
  ui_story_5084_50840301_64_dialog_content = "당연하지! 운명은 이미 새겨졌다... 어... 의심하지 마라?",
  ui_story_5084_50840301_65_dialog_content = "의심하지 말라고...?",
  ui_story_5084_50840301_66_dialog_content = "이해한 모양이구나.",
  ui_story_5084_50840301_67_dialog_content = "아이테르, 여기 온 순간부터 넌 이미 무리에서 뒤처진 거야.",
  ui_story_5084_50840301_68_dialog_content = "의심하지 말라고 하면서, 네 머릿속에 가득 찬 의문은 금방이라도 쏟아져 나올 것 같네.",
  ui_story_5084_50840301_69_dialog_content = "이런 상황에서 의문을 안 가지는 게 쉬운 일이냐고...",
  ui_story_5084_50840301_70_dialog_content = "직감을 따라가렴. 나와 함께 지켜보는 거야.",
  ui_story_5084_50840301_71_dialog_content = "빅토리아 씨!",
  ui_story_5084_50840301_72_dialog_content = "그렇다면...",
  ui_story_5084_50840301_73_dialog_content = "<color=#e8d9bb>휘이이잉──!</color>",
  ui_story_5084_50840301_74_dialog_content = "관으로 들어가라!",
  ui_story_5084_50840301_75_dialog_content = "......",
  ui_story_5084_50840301_76_dialog_content = "바람...? 빅토리아 님이 진짜로 관 속에 들어가셨어!",
  ui_story_5084_50840301_77_option_content = "(감응 연결!)",
  ui_story_5084_50840301_78_dialog_content = "(...뭔가가 감응을 막고 있어...)",
  ui_story_5084_50840301_79_dialog_content = "하하...",
  ui_story_5084_50840301_80_dialog_content = "하하... 하하하하...",
  ui_story_5084_50840301_81_dialog_content = "하하하하... 하하하하하...",
  ui_story_5084_50840301_82_dialog_content = "(저 웃음소리... 저 사람 대체 뭘 하는 거야...?)",
  ui_story_5084_50840301_83_dialog_content = "하하하하하하하하...",
  ui_story_5084_50840301_84_dialog_content = "(어째서 지도자인 빌헬름 저 사람까지...)",
  ui_story_5084_50840301_85_dialog_content = "<color=#e8d9bb>휘이이잉──!</color>",
  ui_story_5084_50840301_86_dialog_content = "PlayerName?",
  ui_story_5084_50840301_87_dialog_content = "메이, 괜찮아! 나 여기 있어!",
  ui_story_5084_50840301_88_dialog_content = "...뭐야?!",
  ui_story_5084_50840301_89_dialog_content = "회오리바람 때문에 촛불이 꺼지더니... 전당이 아무것도 안 보이게 됐어!",
  ui_story_5084_50840301_90_dialog_content = "저 사람들 웃음소리, 너무 의심스러워... 다 같이 뭘 꾸미고 있는 건가?",
  ui_story_5084_50840301_91_dialog_content = "그리고 빌헬름 씨가 빅토리아 씨한테 한 말들...",
  ui_story_5084_50840301_92_dialog_content = "빅토리아 씨, 괜찮은 건가?! 저 사람들 대체 왜 웃는 거냐고...\n여, 역시 뭔가 잘못됐어!",
  ui_story_5084_50840301_93_option_content = "(강제 감응!)",
  ui_story_5084_50840301_94_dialog_content = "(이번엔 겨우... 조금 보이는 정도네... 대체 왜 이러는 거지...?)",
  ui_story_5084_50840301_95_dialog_content = "그동안 진리의 결사를 이끄는 것도 힘들었겠지? 빌헬름 왈라키아.",
  ui_story_5084_50840301_96_dialog_content = "넌 신도가 관에 들어가는 것이 어떤 의미인지를 알면서도 <color=#FFB400>애스턴 왈라키아</color>의 딸을 선택했다.\n속 한번 참으로 새카맣군.",
  ui_story_5084_50840301_97_dialog_content = "그는 진리의 결사의 전임 지도자이자 나의 형이다.\n형의 자녀를 돌보는 것도 당연히 내 책임이 아닌가.",
  ui_story_5084_50840301_98_dialog_content = "(저 사람이 빅토리아 씨의... 숙부님이라고?)",
  ui_story_5084_50840301_99_dialog_content = "허울 좋은 말은 이제 질렸다, 왈라키아.",
  ui_story_5084_50840301_100_dialog_content = "이미 알고 있다. 넌 다른 방법을 찾지 못했지.",
  ui_story_5084_50840301_101_dialog_content = "네 조카를 함께 맛볼 테냐? 아니면 너도 네 조카와 함께...",
  ui_story_5084_50840301_102_dialog_content = "잠깐──",
  ui_story_5084_50840301_103_dialog_content = "빌헬름, 넌 대체 뭘 하려는 거냐. 나한테 그런 말을 하더니, 이게 그 결과란 말이냐?",
  ui_story_5084_50840301_104_dialog_content = "그렇다, 그리고 너도 이미 선택을 내렸잖나, 클라비스.",
  ui_story_5084_50840301_105_dialog_content = "......",
  ui_story_5084_50840301_106_dialog_content = "<color=#e8d9bb>휘이이잉──!</color>",
  ui_story_5084_50840301_107_dialog_content = "(이런... 이 바람... 왠지 처음부터 계속 방해할 작정이었나 본데...)",
  ui_story_5084_50840301_108_dialog_content = "(클라비스, 빌헬름, 빅토리아 씨... 다들 대체 뭘 꾸미고 있는 거야?)",
  ui_story_5084_50840301_109_dialog_content = "으앗, 그렇게 세게 잡지 마, PlayerName! 이러면 금방 또 팔을 꿰매야 한다구...",
  ui_story_5084_50840301_110_dialog_content = "미, 미안...",
  ui_story_5084_50840301_111_dialog_content = "지금 정도 힘은 딱 좋아.",
  ui_story_5084_50840301_112_dialog_content = "으으... 방법을... 방법을 생각하자... 근데 지금 이 상황은 대체 뭐냐고...",
  ui_story_5084_50840301_113_dialog_content = "빅토리아 씨랑 그 빌헬름이란 사람, 대체 무슨 사연이 있는 거지?\n왜 그 사람은 빅토리아 씨를 제물로 선택한 거냐고...",
  ui_story_5084_50840301_114_dialog_content = "PlayerName, 어떻게 할지 생각했어? 촛불이 흔들리기 시작했어...\n봐, 주변의 모습이 변하고 있는 거 같아.",
  ui_story_5084_50840401_1_dialog_content = "<color=#e8d9bb>뚜벅, 뚜벅...</color>",
  ui_story_5084_50840401_2_dialog_content = "저 소리...!",
  ui_story_5084_50840401_3_dialog_content = "냐앙?",
  ui_story_5084_50840401_4_dialog_content = "응, 베이비, 괜찮아. 메이가 있잖아.",
  ui_story_5084_50840401_5_dialog_content = "너희가 계속 아무 말도 없어서 나 혼자인 줄 알았다고...",
  ui_story_5084_50840401_6_dialog_content = "왠지 또 다른 곳으로 오게 된 것 같은데... 냄새가 좋네, 옷 냄새인가...?",
  ui_story_5084_50840401_7_dialog_content = "어라?",
  ui_story_5084_50840401_8_dialog_content = "<color=#e8d9bb>덜컹──</color>",
  ui_story_5084_50840401_9_dialog_content = "누가 왔어!",
  ui_story_5084_50840401_10_dialog_content = "으읍... 내 입 막지... 웁!",
  ui_story_5084_50840401_11_dialog_content = "...흥, 이 옷은 어제 입었으니까 이미 역사의 뒤안길로 가 버렸어.",
  ui_story_5084_50840401_12_dialog_content = "이 옷감은 꼭 사포 같아. 난 예술가지 목수가 아니라고...",
  ui_story_5084_50840401_13_dialog_content = "이건... 색감에 창의성이 부족해... 예술가가 어떻게 이런 평범한 색을 수용할 수 있겠어?",
  ui_story_5084_50840401_14_dialog_content = "칫, 이게 다 뭐야? 하여튼 아동복 수준하고는... 난 진작 어른 옷 입을 나이가 됐다고!",
  ui_story_5084_50840401_15_dialog_content = "아, 진짜! 내가 왜 아버지 말을 들어야 하는 거야?!",
  ui_story_5084_50840401_16_dialog_content = "그 두 손님은 이 카론 님이 격식을 차리게 만들 자격도 없는 녀석들이잖아!",
  ui_story_5084_50840401_17_dialog_content = "<color=#e8d9bb>쾅!</color>",
  ui_story_5084_50840401_18_dialog_content = "......?",
  ui_story_5084_50840401_19_dialog_content = "...카, 카론 씨──?!",
  ui_story_5084_50840401_20_dialog_content = "게다가... 우리가 안 보이나 본데?",
  ui_story_5084_50840401_21_dialog_content = "후아아──! PlayerName! 이제야 놓아주다니... 근데 너 저 사람 알아?",
  ui_story_5084_50840401_22_dialog_content = "자칭 예술가... 저 헤어스타일... 그리고 저 표정... 당연히 알지!",
  ui_story_5084_50840401_23_dialog_content = "저 사람 방금 우리 바로 앞에 서 있었던 거 맞지?",
  ui_story_5084_50840401_24_dialog_content = "응, 옷 고르고 있었어. 으음... 그 좋은 냄새가 나는 옷은 확실히 독특했어.\n메이는 그런 거 못 만들었을 거야...",
  ui_story_5084_50840401_25_dialog_content = "카론 씨 옷장... 이 시기의 카론 씨는 대충 봐도 한 열 살 정도 돼 보였어...",
  ui_story_5084_50840401_26_dialog_content = "뭐... 그 사람도 나이가 복잡한 사람이니까, 아무튼 여기도 과거인 거겠지.",
  ui_story_5084_50840401_27_dialog_content = "아까 그 성명제... 빅토리아 씨는 1915년이라고 했어. 그럼...",
  ui_story_5084_50840401_28_dialog_content = "아니, 그것보다 이 촛불 대체 뭐야? 촛불이 흔들리면 공간이 바뀐다니...\n그리고 이번에도 또 메이 너랑 같이 여기로 왔어.",
  ui_story_5084_50840401_29_dialog_content = "PlayerName 바보, 그거야 네가 한 손으로 촛불을 들고,\n다른 손으로 나랑 「베이비」를 잡고 있었으니까 그렇지.",
  ui_story_5084_50840401_30_dialog_content = "스칼렛 언니는 대단한 물건을 잔뜩 가지고 있어.\n네가 마법을 안 믿는다면 딱히 말해줄 건 없겠지만 말이야.",
  ui_story_5084_50840401_31_dialog_content = "...넌 이런 일이 벌어지고 있는데도 전혀 이상하단 생각이 안 들어?",
  ui_story_5084_50840401_32_dialog_content = "이상해서 재밌다는 생각? 아니면 무섭다는 생각?",
  ui_story_5084_50840401_33_dialog_content = "에헤헷, 메이는 둘 다 좋아!",
  ui_story_5084_50840401_34_dialog_content = "저 카론 씨는 우리 모습도 안 보이고 소리도 못 들은 것 같았어.\n그것도 촛불 때문일까...?",
  ui_story_5084_50840401_35_dialog_content = "진리의 전당에 숨어든 것도 그래...\n우리 모습을 본 건 미래에서 같이 온 빅토리아 씨뿐이었던 거야.",
  ui_story_5084_50840401_36_dialog_content = "그럼 이 촛불... 소설 같은 데서 몸을 숨겨주는 마법 아이템인 거잖아!",
  ui_story_5084_50840401_37_dialog_content = "아하하, 그렇네!",
  ui_story_5084_50840401_38_dialog_content = "관에 들어간 빅토리아 씨는 어떻게 됐을까? 게다가 나일즈와 파우스트도 어디로 갔을까...",
  ui_story_5084_50840401_39_dialog_content = "우리가 여기 온 게 정말로 마음의 인도를 따라서인 걸까...?",
  ui_story_5084_50840401_40_dialog_content = "넌 아까 무슨 생각 했는데?",
  ui_story_5084_50840401_41_dialog_content = "촛불이 흔들릴 때? 그러니까...",
  ui_story_5084_50840401_42_dialog_content = "「클라비스, 빌헬름, 빅토리아 씨... 다들 대체 뭘 꾸미고 있는 거야?」라고...",
  ui_story_5084_50840401_43_dialog_content = "...그럼 만약 아까 카론 씨가 말했던 아버지, 그리고 두 명의 손님이 그 세 사람이라면...",
  ui_story_5084_50840401_44_dialog_content = "촛불이 우릴 이끌어줄 거라고 스칼렛이 그랬잖아? 그게 이런 뜻이었던 거야!",
  ui_story_5084_50840401_45_dialog_content = "<color=#e8d9bb>덜컹──</color>",
  ui_story_5084_50840401_46_dialog_content = "내가 이렇게까지 하는 건 어디까지나 예술엔 편견이 없어야 하기 때문이야.\n저건 내가 아끼는 양말이니까, 이번 한 번만 그 녀석들을 위해 신어줘야지.",
  ui_story_5084_50840401_47_dialog_content = "(옷 고르는 데 저렇게 진심인 사람이 진짜로 있었구나...)",
  ui_story_5084_50840401_48_dialog_content = "「카론 님은 늘 어디서 그렇게 매력적인 양말을 사시나요?」",
  ui_story_5084_50840401_49_dialog_content = "「카론 님은 지금까지 제가 본 사람 중에 가장 안목 있는 분입니다...」",
  ui_story_5084_50840401_50_dialog_content = "훗, 이런 게 바로 어른의 세계인가. 고민거리가 정말 끝도 없네...",
  ui_story_5084_50840401_51_dialog_content = "<color=#e8d9bb>쾅!</color>",
  ui_story_5084_50840401_52_dialog_content = "......",
  ui_story_5084_50840401_53_dialog_content = "어...음... 카론 씨는 어릴 때부터 참 특이했구나...",
  ui_story_5084_50840401_54_dialog_content = "가자, 메이. 우리도 따라가 보자! 나한테서 떨어지지 말고.",
  ui_story_5084_50840401_55_dialog_content = "알겠어!",
  ui_story_5084_50840401_56_dialog_content = "오랜만이군, 클라비스.",
  ui_story_5084_50840401_57_dialog_content = "클라비스 삼촌.",
  ui_story_5084_50840401_58_dialog_content = "빅토리아 님이야! 비──",
  ui_story_5084_50840401_59_dialog_content = "이 거리라면 진작에 우릴 발견했을걸.\n우리한테 반응을 안 하는 걸 보면, 저건 아마 과거의 빅토리아 씨일 거야.",
  ui_story_5084_50840401_60_dialog_content = "뭐, 지금 저 모습도 우리가 아는 빅토리아 씨랑 똑같이 생기긴 했지만...",
  ui_story_5084_50840401_61_dialog_content = "바보, 빅토리아 님은 고귀한 혈족이시니까, 각성하신 뒤로는 나이를 먹지 않게 되셨다구.",
  ui_story_5084_50840401_62_dialog_content = "아, 참! PlayerName, 과거의 사람들한테 우리 모습이 안 보이는 거면, 우리 지금 왜 숨은 거야?",
  ui_story_5084_50840401_63_dialog_content = "어?! 그러게... 음... 그동안 본 사람들이나 상황이 좀 무서워서 그랬나?",
  ui_story_5084_50840401_64_dialog_content = "하하... 너희 숙질 사이가 함께 찾아오다니, 참 별일이군.",
  ui_story_5084_50840401_65_dialog_content = "흥...",
  ui_story_5084_50840401_66_dialog_content = "카론은?",
  ui_story_5084_50840401_67_dialog_content = "너도 알잖냐. 손님만 오면 단장하느라 바쁘다고...",
  ui_story_5084_50840401_68_dialog_content = "......",
  ui_story_5084_50840401_69_dialog_content = "어머, 카론 님, 양말이 참 안목이 있으시네요.",
  ui_story_5084_50840401_70_dialog_content = "...! 아무리 그렇게 말해도...",
  ui_story_5084_50840401_71_dialog_content = "인사는 하였느냐?",
  ui_story_5084_50840401_72_dialog_content = "...빌헬름 삼촌, 안녕하세요.",
  ui_story_5084_50840401_73_dialog_content = "그리고 이쪽은 네 삼촌의 조카딸 빅토리아다. 네게는 사촌누나뻘이 되지.",
  ui_story_5084_50840401_74_dialog_content = "안녕, 먼 친척.",
  ui_story_5084_50840401_75_dialog_content = "...안녕, 누나.",
  ui_story_5084_50840401_76_dialog_content = "카론, 빅토리아를 데려가서 간식을 좀 먹고 있거라.",
  ui_story_5084_50840401_77_dialog_content = "...네.",
  ui_story_5084_50840401_78_dialog_content = "왈라지 마을의 일은 좀 정리가 됐나? 옛 마을에 올 시간을 다 내고 말이야.",
  ui_story_5084_50840401_79_dialog_content = "오는 길에 고생 좀 했지. 뭐, 널 보러 오는 일인데 내가 멀다고 어디 안 올 사람이던가.",
  ui_story_5084_50840401_80_dialog_content = "......",
  ui_story_5084_50840401_81_dialog_content = "......",
  ui_story_5084_50840401_82_dialog_content = "언제까지 계속 쳐다볼 거니?",
  ui_story_5084_50840401_83_dialog_content = "넌 그 음침한 녀석들이랑 한패야?",
  ui_story_5084_50840401_84_dialog_content = "어느 음침한 녀석들?",
  ui_story_5084_50840401_85_dialog_content = "빌헬름 왈라키아처럼 그 결사 녀석들 말이야.",
  ui_story_5084_50840401_86_dialog_content = "난 진리의 결사 멤버가 아냐.\n하지만 지도자의 이름을 함부로 부르다니, 넌 참 예의가 없구나.",
  ui_story_5084_50840401_87_dialog_content = "저 사람들이랑 친한 녀석들은 다 악당들이야. 이건 예술가의 직감이라고.\n난 아버지가 시켰으니까 억지로 당신들을 만나준 것뿐이야.",
  ui_story_5084_50840401_88_dialog_content = "아버지 친구를 그렇게 싫어하면서, 멋은 잘도 냈네.",
  ui_story_5084_50840401_89_dialog_content = "...! 이건 예술을 위해서야!",
  ui_story_5084_50840401_90_dialog_content = "호오? 네가 예술을 알아? 그럼 예술이란 뭔데?",
  ui_story_5084_50840401_91_dialog_content = "너도 알겠지만 우린 언젠가 죽잖아? 근데 죽지 않는 게 있어. 그게 뭔지 알아?",
  ui_story_5084_50840401_92_dialog_content = "바로 예술이야!",
  ui_story_5084_50840401_93_dialog_content = "예술은 지옥에서 금단의 꽃을 피우고,\n삼도천에 길을 내서 영원히 움직이는 열차를 만들 수 있어.",
  ui_story_5084_50840401_94_dialog_content = "그리고 난 그 열차의 차장이 될 거야.\n영혼을 나르는 뱃사공이 돼서 예술로서 영생할 거라고.",
  ui_story_5084_50840401_95_dialog_content = "영생이라... 후훗, 아무래도 난 네 승객이 될 운명인 모양이네.",
  ui_story_5084_50840401_96_dialog_content = "당연하지! 아, 아니지... 아직은 안 돼.\n그 음침한 녀석들이 내 걸작을 모욕한 뒤로는...",
  ui_story_5084_50840401_97_dialog_content = "저렇게 다 큰 애가 소변기에 이상한 애착을 보이다니...",
  ui_story_5084_50840401_98_dialog_content = "...술 취한 인간처럼 방향도 못 찾고, 여기서 신나게 놀고 있군.",
  ui_story_5084_50840401_99_dialog_content = "그래서 난 결정했어. 내 열차엔 내 예술을 이해하는 사람만 태울 거라고...",
  ui_story_5084_50840401_100_dialog_content = "오래 살면 언행이 거칠어지고, 제일 문제인 건 안목이 없어진다는 거야.\n난 그런 녀석들 상대 안 해.",
  ui_story_5084_50840401_101_dialog_content = "꽤 자신만만하네.",
  ui_story_5084_50840401_102_dialog_content = "당연하지. 옛 마을에서 나만큼 안목 있는 사람은 못 봤으니까.",
  ui_story_5084_50840401_103_dialog_content = "앞으로 난 내 연극 결사, 음악 결사, 철도 모형 결사, 예술 결사를 만들 거야...",
  ui_story_5084_50840401_104_dialog_content = "내가 특별히 말해주는 건데, 난 저 녀석들이 추구하는 진리를 진작에 깨달았어.\n예술이야말로 진리야.",
  ui_story_5084_50840401_105_dialog_content = "어때? 넌 아직 들어가고 싶은 조직이 없나본데, 이 카론 님의 심사에 도전해 볼 배짱은 있어?",
  ui_story_5084_50840401_106_dialog_content = "후훗, 재미있네. 어떤 심사인데?",
  ui_story_5084_50840401_107_dialog_content = "간단해. 내 기차가 여길 지나갈 때 감각을 살려서 내 예술 세계로 들어오는 거야!\n그리고 너도 예술에 대한 네 각오를 표현하면 돼.",
  ui_story_5084_50840401_108_dialog_content = "응, 해 봐.",
  ui_story_5084_50840401_109_dialog_content = "그럼 잠깐 기다리고 있어. 원래 외부인 앞에서는 보여주지 말라고 아버지가 그러셨거든.",
  ui_story_5084_50840401_110_dialog_content = "이따가 내가 열차장의 퍼포먼스랑 진정한 예술이 뭔지 보여줄 테니까!",
  ui_story_5084_50840401_111_dialog_content = "<color=#e8d9bb>잠시 후...</color>",
  ui_story_5084_50840401_112_dialog_content = "들어라! 세계의 종말을 앞둔 외침이 레일에 울려 퍼지고 있다! 빠아앙──!",
  ui_story_5084_50840401_113_dialog_content = "목도하라! 이것이 바로 말세를 앞두고 영원으로 향하는 종말열차다! ",
  ui_story_5084_50840401_114_dialog_content = "영원을 갈망하는 예술가들을 태우고, 빛나는 하늘 끝을 통과하리니! ",
  ui_story_5084_50840401_115_dialog_content = "사슬은 이미 끊어져, 다시는 그 몸을 속박하지 않으리라!\n오직 무한한 바퀴만을 남긴 채, 영원히 쉬지 않고 앞을 향해 달려 나간다!",
  ui_story_5084_50840401_116_dialog_content = "기관차는 높이 솟아 창궁을 향하노니!\n나 카론 차장의 인도 아래, 우리는 저주받은 심연에서 도망칠 것이다!",
  ui_story_5084_50840401_117_dialog_content = "나는 지옥의 문을 여는 명령을 내리고, 신세계의 서광을 맞이하리라!",
  ui_story_5084_50840401_118_dialog_content = "우와... 나 왠지 진짜로 어둠 속을 달리는 열차가 보인 거 같아...",
  ui_story_5084_50840401_119_dialog_content = "역시 카론 씨라니까... 있는 곳이 곧 무대가 되는 건가...",
  ui_story_5084_50840401_120_dialog_content = "투둥 투둥! 들어라! 나의 입에서 튀어 오르는 구세계와 신세계의 교향곡을!\n두려워하지 말지어다!",
  ui_story_5084_50840401_121_dialog_content = "계속, 끝없이 계속, 신세계의 문이 열릴 때까지 달린다! 그곳은 불후의 낙원이로다!",
  ui_story_5084_50840401_122_dialog_content = "......",
  ui_story_5084_50840401_123_dialog_content = "다음은 누나 차례야!",
  ui_story_5084_50840401_124_dialog_content = "후훗, 퍼포먼스에 재능이 있긴 하지만, 신세계의 출구는 그저 환상일 뿐이야!",
  ui_story_5084_50840401_125_dialog_content = "네가 갈망하는 그 신세계의 문은 눈에 보이지 않는 보루가 되어,\n갑자기 네 눈앞에 쏟아질 거란다!",
  ui_story_5084_50840401_126_dialog_content = "열차의 레일에는 불이 붙고, 적황색의 거대한 물체는 네 환상을 불태우겠지.",
  ui_story_5084_50840401_127_dialog_content = "죽음, 그것이야말로 진리! 반드시 종결의 서곡을 바쳐야만 해!\n영생은 끝을 알 수 없는 공포이자 무한한 공황!",
  ui_story_5084_50840401_128_dialog_content = "두려움은 널 짓이겨 벌레로 만들고, 영생이라는 우리에 가두어\n영원토록 출구를 찾을 수 없게 할 거야.",
  ui_story_5084_50840401_129_dialog_content = "그 거대한 물체에 사로잡힌 넌 그저 몸부림치는 꼭두각시고,\n아무리 발악해도 저항할 힘조차 없어!",
  ui_story_5084_50840401_130_dialog_content = "고개를 들어!",
  ui_story_5084_50840401_131_dialog_content = "무한한 조종, 그것이 바로 신세계의 진상이야!",
  ui_story_5084_50840401_132_dialog_content = "......!",
  ui_story_5084_50840401_133_dialog_content = "진상이 보이지 않는 자들의 터무니없는 말 속에서 네 광기는 그저 오락일 뿐!",
  ui_story_5084_50840401_134_dialog_content = "두려움을 일으키는 것이야말로 진정한 예술이야!",
  ui_story_5084_50840401_135_dialog_content = "...으아아아아앙!",
  ui_story_5084_50840401_136_dialog_content = "...누, 누나 나빴어──!",
  ui_story_5084_50840401_137_dialog_content = "어때? 영생의 예술도 이것보단 덜 자극적이지 않니?",
  ui_story_5084_50840401_138_dialog_content = "아하하하하하...!",
  ui_story_5084_50840401_139_dialog_content = "...으아아아앙!",
  ui_story_5084_50840401_140_dialog_content = "빨리 내 기차를... 멈춰! 빨리! 멈추라고!",
  ui_story_5084_50840401_141_dialog_content = "아하하하하하하하...",
  ui_story_5084_50840401_142_dialog_content = "빅토리아 님한테 저런 재미있는 사촌 동생이 있으셨을 줄은 몰랐어.",
  ui_story_5084_50840401_143_dialog_content = "하? 그것보다 빅토리아 씨가 저렇게 카론 씨를 놀리고 있는 거에 더 놀라야 되는 거 아냐?!",
  ui_story_5084_50840401_144_dialog_content = "어쩐지 카론 씨가 친척 얘기를 할 때 별로 좋게 말하질 않는다 했어...\n저게 무슨 예술이냐고...!",
  ui_story_5084_50840401_145_dialog_content = "그래도 그건 안 된다, 빌헬름...",
  ui_story_5084_50840401_146_dialog_content = "대체 뭘 두려워하고 있는 거냐, 클라비스. 상황이 점점 잘못되고 있다는 걸 모르겠나?",
  ui_story_5084_50840401_147_dialog_content = "포르피리오와 그 가주들은 왈라키아 혈족에서 분가한 뒤로 더는 계율을 지키지 않게 되었다...",
  ui_story_5084_50840401_148_dialog_content = "네가 그래봤자 아무도 구할 수 없다.",
  ui_story_5084_50840401_149_dialog_content = "허나 지금 진리의 결사는 너와 나, 그리고 마을 사람들에겐 재앙이나 다름없다.\n혈족의 계율은 언제나 감옥일 뿐이었단 말이다!",
  ui_story_5084_50840401_150_dialog_content = "피를 갈망하는 건 피의 일족의 본성... 너나 나나 마찬가지지.\n다만 우린 운이 좋았을 뿐이야.",
  ui_story_5084_50840401_151_dialog_content = "...? 일족, 혈통... 언제부터 너까지 그런 말을 하기 시작했지?",
  ui_story_5084_50840401_152_dialog_content = "그런 식으로 말하지 마라, 빌헬름. 난 그저 사실을 부정하고 싶지 않을 뿐이니까...",
  ui_story_5084_50840401_153_dialog_content = "그 <color=#FFB400>열쇠</color>는 널 해치게 될 거다.",
  ui_story_5084_50840401_154_dialog_content = "죽음을 앞둔 형님이 일부러 그걸 <color=#FFB400>덩굴인간</color> 손에서 되찾아서 네게 준 건...\n누가 봐도 그게 나한테 전해지도록 하기 위해서다.",
  ui_story_5084_50840401_155_dialog_content = "...네가 <color=#FFB400>덩굴인간</color> 손에서 억지로 빼앗는 걸 막기 위해서일 수도 있겠지.",
  ui_story_5084_50840401_156_dialog_content = "아무리 정도에서 벗어나 있다고 해도, 넌 후계자로서 이미 여러 해 동안\n진리의 결사를 관리해 왔다.",
  ui_story_5084_50840401_157_dialog_content = "그리고 그건 모두 오랜 예언에 새겨져 있었지.",
  ui_story_5084_50840401_158_dialog_content = "운명을 거스를 수 없다는 건 네가 나보다 더 잘 알고 있을 텐데.",
  ui_story_5084_50840401_159_dialog_content = "아니, 그렇지 않아!",
  ui_story_5084_50840401_160_dialog_content = "난 진리의 주인을 믿을 뿐, 왈라키아의 존망은 나와 무관하다!\n적어도 난 운명 같은 건 믿지 않는다...",
  ui_story_5084_50840401_161_dialog_content = "설령 그 운명이 내게 닥칠지언정, 그걸 내가 반드시 받아들이진 않을 테니 말이야.",
  ui_story_5084_50840401_162_dialog_content = "난 지금까지 늘 마음의 인도만 따라왔고, 그것이야말로 진리다.",
  ui_story_5084_50840401_163_dialog_content = "그럼 빅토리아는 어쩔 셈이지? 형님이 네게 했던 당부는...",
  ui_story_5084_50840401_164_dialog_content = "클라비스, 형님 얘기는 이제 됐어.",
  ui_story_5084_50840401_165_dialog_content = "빅토리아는 나 이상으로 이 힘을 하찮게 여기고, 왈라지 마을의 모든 것에 무심하다.\n저 아이는 스스로 자신을 지킬 수 있다.",
  ui_story_5084_50840401_166_dialog_content = "하하... 어쩌면 이것도 내 형님에게 주어지는 징벌일지도 모르지.",
  ui_story_5084_50840401_167_dialog_content = "빌헬름...",
  ui_story_5084_50840401_168_dialog_content = "뭐, 그렇다면... 네 가족을 잘 지키길 바라마.",
  ui_story_5084_50840401_169_dialog_content = "...으아아아앙!",
  ui_story_5084_50840401_170_dialog_content = "......",
  ui_story_5084_50840401_171_dialog_content = "빅토리아 왈라키아, 갈 시간이다.",
  ui_story_5084_50840401_172_dialog_content = "......",
  ui_story_5084_50840401_173_dialog_content = "벌써 간다고? 우린 아직 아무것도 못 알아냈는데...\n어떡하지? 쫓아갈까...? 그래! 어떻게든...",
  ui_story_5084_50840401_174_dialog_content = "효과가 있어! 촛불이 또 흔들려! 빨리──",
  ui_story_5084_50840401_175_dialog_content = "울지 마라...",
  ui_story_5084_50840401_176_dialog_content = "미쳤어... 미친 여자...!",
  ui_story_5084_50840401_177_dialog_content = "네 그 잡동사니나 빨리 치워라, 당장!",
  ui_story_5084_50840401_178_dialog_content = "...흑흑... 훌쩍...",
  ui_story_5084_50840501_1_dialog_content = "이제 알겠어. 촛불이 흔들렸을 때, 난 빌헬름 씨가 대체 무슨 속셈일까 생각하고 있었어.",
  ui_story_5084_50840501_2_dialog_content = "그럼 여긴... 설마 빌헬름 님 집은 아니겠지?",
  ui_story_5084_50840501_3_dialog_content = "빌헬름 님이야!",
  ui_story_5084_50840501_4_dialog_content = "반지를 잡고 우울한 얼굴을 하고 있어...",
  ui_story_5084_50840501_5_dialog_content = "그래도 마음속으로 무슨 생각을 하고 있는지 우린 알 수 없어.",
  ui_story_5084_50840501_6_dialog_content = "명성이 자자한 아이테르님, 엿듣는 데 성공하면 꼭 알려줘!",
  ui_story_5084_50840501_7_dialog_content = "누, 누가 감응 능력을 써서 엿듣기라도 한대?",
  ui_story_5084_50840501_8_dialog_content = "안 그러면 무슨 생각을 하시는지 어떻게 알아?",
  ui_story_5084_50840501_9_dialog_content = "......",
  ui_story_5084_50840501_10_dialog_content = "우물쭈물하지 마. 어른이면 빨리 결단을 내려!",
  ui_story_5084_50840501_11_dialog_content = "...알았어. 그냥 감응만 하는 거라면 스칼렛이 말한 규칙을 어기는 것도 아닐 테니까...",
  ui_story_5084_50840501_12_option_content = "(감응 연결──)",
  ui_story_5084_50840501_13_dialog_content = "유물 속에 담긴 속삭임은... 오직 그것을 착용하고 나서야 알게 되지.\n한순간에 천 번 죽임을 당하고, 만 번 갉아 먹히는 그 고통...",
  ui_story_5084_50840501_14_dialog_content = "왈라키아... 피의 일족은... 정녕 활로가 없는 것인가...",
  ui_story_5084_50840501_15_dialog_content = "오로리안으로 태어났음에도 해가 들지 않는 어두운 마을에 칩거하며,\n우리는 계승을 통해 힘을 얻었다.",
  ui_story_5084_50840501_16_dialog_content = "혈족 선조의 인도를 따라 피신하고, 도망쳐, 죽음만도 못한 일생을 보내왔지...",
  ui_story_5084_50840501_17_dialog_content = "대체 뭐가 선조의 뜻이고 힘의 계승이란 말이냐...\n왈라키아는 통치를 유지하기 위해 후손들의 생사조차 아랑곳하지 않았을 뿐이다.",
  ui_story_5084_50840501_18_dialog_content = "비록 왈라키아 일족이 이미 피를 대신할 음식을 찾았다곤 하나,\n결국 혈족은 그 한없이 깊은 죄악의 힘에서 벗어날 수 없다.",
  ui_story_5084_50840501_19_dialog_content = "(피를 대신해...? 빅토리아 씨가 종종 말하던 생명의 감로란 게... 설마 정말로...)",
  ui_story_5084_50840501_20_dialog_content = "이 두려운 반지는...",
  ui_story_5084_50840501_21_dialog_content = "제길...",
  ui_story_5084_50840501_22_dialog_content = "최근 들어 피에 대한 가주들의 갈망은 점점 더 극단적으로 치닫고 있다...",
  ui_story_5084_50840501_23_dialog_content = "휴... 클라비스, 너와 말다툼을 한 그날로부터 벌써 3년이 지났다.\n지금 넌 대체 뭘 하고 있는 거냐.",
  ui_story_5084_50840501_24_dialog_content = "(빅토리아 씨랑 빌헬름 씨가 카론 씨의 아버지를 방문한 게 3년 전...?\n그럼 지금은 몇 년인 거지?)",
  ui_story_5084_50840501_25_dialog_content = "<color=#e8d9bb>덜컹──</color>",
  ui_story_5084_50840501_26_dialog_content = "......",
  ui_story_5084_50840501_27_dialog_content = "이 시대의 빅토리아 씨...?",
  ui_story_5084_50840501_28_dialog_content = "저 분위기... 확실히 과거의 빅토리아 씨야.",
  ui_story_5084_50840501_29_dialog_content = "또 옛날 빅토리아 님이신 거구나! 그럼 방금 넌 뭘 엿들었어?",
  ui_story_5084_50840501_30_dialog_content = "빅토리아 씨가 들어왔을 때 빌헬름 씨가 반지를 재빨리 중지에 꼈어.\n그랬더니 뭔가가 감응을 방해하는 느낌이 들었어...",
  ui_story_5084_50840501_31_dialog_content = "그래서 감응이 끝난 거야?",
  ui_story_5084_50840501_32_dialog_content = "응... 저 반지는 빌헬름 씨의 정신에 엄청난 타격을 주는 것 같아.\n뭐, 일단 둘이 무슨 말을 하는지부터 들어보자.",
  ui_story_5084_50840501_33_dialog_content = "으윽...",
  ui_story_5084_50840501_34_dialog_content = "돌아왔네... 당신 이번엔 석 달이나 나가 있었어. 어떻게 된 거야?",
  ui_story_5084_50840501_35_dialog_content = "...너와는 무관한 일이다.",
  ui_story_5084_50840501_36_dialog_content = "그 눈빛은 뭐야...? 원한, 알 수 없는 감정...",
  ui_story_5084_50840501_37_dialog_content = "빌헬름 왈라키아, 밖에서 무슨 일이 있었던 거지?",
  ui_story_5084_50840501_38_dialog_content = "누가 내 방에 들어와도 된다고 했나.",
  ui_story_5084_50840501_39_dialog_content = "당신은 진리의 결사의 지도자야. 그런데도 일은 제쳐두고 밖으로만 나가고...\n게다가 집에 있는 시간도 갈수록 줄어들고 있잖아.",
  ui_story_5084_50840501_40_dialog_content = "몇 번이나 말했을 텐데, 너와는 무관하다. 지금 당장 나가라.",
  ui_story_5084_50840501_41_dialog_content = "그래, 당신은 늘 그렇게 나와의 대화를 거부했지. 하지만 오늘 밤은 성명제 날이야.\n난 대화를 한다면 오늘이 마지막 기회라고 생각했는데.",
  ui_story_5084_50840501_42_dialog_content = "진리에 대해서, 그리고 우리에 대해서...",
  ui_story_5084_50840501_43_dialog_content = "꺼져! 당장 내 앞에서 꺼지란 말이다!",
  ui_story_5084_50840501_44_dialog_content = "......",
  ui_story_5084_50840501_45_dialog_content = "빌헬름 님 너무 무서워... 근데 왜 갑자기 저러시는 걸까...?",
  ui_story_5084_50840501_46_dialog_content = "...으윽... <size=45>크아악...!</size>",
  ui_story_5084_50840501_47_dialog_content = "빌헬름 님이 이상해... 얼른 어떻게 좀 해 봐!",
  ui_story_5084_50840501_48_dialog_content = "설마 저 반지 때문인가...?",
  ui_story_5084_50840501_49_option_content = "(감응 연결──)",
  ui_story_5084_50840501_50_dialog_content = "흐하하하하하하! 그녀의 손가락을 씹어버려라! 목을 비틀어 끊어라!",
  ui_story_5084_50840501_51_dialog_content = "닥쳐...",
  ui_story_5084_50840501_52_dialog_content = "자기 자리를 보전하기 위해, 진정한 지도자 앞에서 자신을 미치게 만드는 반지를 끼다니.",
  ui_story_5084_50840501_53_dialog_content = "네가 죽이고 싶은 건 그녀인가? 아니면 자기 자신인가?",
  ui_story_5084_50840501_54_dialog_content = "하하... 고통 같은 건 이미 진작에 네놈에게 조련당해 무감각해졌다...",
  ui_story_5084_50840501_55_dialog_content = "왈라키아 일족은 네 손에 망할 것이다.",
  ui_story_5084_50840501_56_dialog_content = "훗... 날 파멸로 이끌 생각이라면, 진리의 결사도 함께다...",
  ui_story_5084_50840501_57_dialog_content = "그녀는 자신만의 조직을 만들고 왈라키아의 혈통을 배제할 것이다.\n진리의 결사는 새로운 방식으로 존재하게 되겠지.",
  ui_story_5084_50840501_58_dialog_content = "그녀는 왈라키아에 종결을 가져올 자다.",
  ui_story_5084_50840501_59_dialog_content = "나도 그 안에 포함되나?",
  ui_story_5084_50840501_60_dialog_content = "너는 그들에게 죽임을 당해야만 살아남을 수 있다...",
  ui_story_5084_50840501_61_dialog_content = "대체 뭔 소리를 하는 건지 모르겠군.",
  ui_story_5084_50840501_62_dialog_content = "확실히 말해주지. 죽어라!",
  ui_story_5084_50840501_63_dialog_content = "(엄청 무서운 목소리야! 빌헬름 씨를 정신적으로 몰아붙이려는 것 같아...)",
  ui_story_5084_50840501_64_dialog_content = "(설마 유물이 힘의 근원이고, 그걸 몸에 지니면 엄청난 고통을 주는 건가?)",
  ui_story_5084_50840501_65_dialog_content = "(그렇게 보면 진리의 결사의 인상엔 딱 맞긴 한데...)",
  ui_story_5084_50840501_66_dialog_content = "(이 목소리는 어디서 들려오는 거지? 반지의 첫 소유자? 왈라키아의 선조? 아니면...)",
  ui_story_5084_50840501_67_dialog_content = "<size=45>크윽... 크아아아아!</size>",
  ui_story_5084_50840501_68_dialog_content = "어디 또 운명을 거슬러 보아라...",
  ui_story_5084_50840501_69_dialog_content = "꺼...져!",
  ui_story_5084_50840501_70_dialog_content = "분수도 모르는군.",
  ui_story_5084_50840501_71_dialog_content = "내... 몸에서... <size=45>나가!</size>",
  ui_story_5084_50840501_72_dialog_content = "주여...! 진리의 길은 대체 어디에 있단 말입니까!",
  ui_story_5084_50840501_73_dialog_content = "(빌헬름 씨, 저러다 실신하겠어!)",
  ui_story_5084_50840501_74_dialog_content = "(저 목소리... 의식 속에서 괴물을 구현했어. 그럼 나도 뭔가 할 수 있을지도 몰라!)",
  ui_story_5084_50840502_1_dialog_content = "호오? 뭔가 새로운 힘을 익힌 모양이지...?",
  ui_story_5084_50840502_2_dialog_content = "온화하고... 비밀스러운...",
  ui_story_5084_50840502_3_dialog_content = "......",
  ui_story_5084_50840502_4_dialog_content = "(이런! 설마 들킨 건가...?)",
  ui_story_5084_50840502_5_dialog_content = "상으로 네가 흥미를 느낄 만한 것을 보여주지.",
  ui_story_5084_50840502_6_dialog_content = "진리가 그를 축복하길.",
  ui_story_5084_50840502_7_dialog_content = "...드디어 또 큰일을 하나 끝냈군.",
  ui_story_5084_50840502_8_dialog_content = "신도의 피... 정말 오랜만에 느끼는 감미로운 맛이야...",
  ui_story_5084_50840502_9_dialog_content = "그 안에서 어떤 진리를 깨달았지?",
  ui_story_5084_50840502_10_dialog_content = "내 깨달음은... 오직 감격뿐이다.",
  ui_story_5084_50840502_11_dialog_content = "오직 피의 달만이 피에 대한 혈족의 욕망을 충족시킬 수 있다.",
  ui_story_5084_50840502_12_dialog_content = "신자들은 숭고한 주문을 외우며 춤을 추다가 스스로를 해치고, 앞다투어 제물이 된다.\n오직 저들이 이해할 수 없는 주에게 닿기 위해서 말이야.",
  ui_story_5084_50840502_13_dialog_content = "백 년을 하루같이... 함께 성취하며...",
  ui_story_5084_50840502_14_dialog_content = "하지만 이 달콤함이 여기서 그치다니...",
  ui_story_5084_50840502_15_dialog_content = "성명제의 밤에 왜 독실한 신도들을 더 늘리지 않는 거지?",
  ui_story_5084_50840502_16_dialog_content = "그것이 신자의 피를 입에 댄 후 네가 얻은 깨달음인가?",
  ui_story_5084_50840502_17_dialog_content = "다 그렇지는 않겠지.",
  ui_story_5084_50840502_18_dialog_content = "주께서 그들의 몸에 흐르실 때, 우리는 그 피를 마신다.\n깨달은 진리를 후세에 전하기 위하여.",
  ui_story_5084_50840502_19_dialog_content = "그것이 우리들이 가주로서 신도들과 맺은 계약이다.",
  ui_story_5084_50840502_20_dialog_content = "거기서 진리를 헤아리지 못한다면, 희생자가 아무리 많은들 소용없다.",
  ui_story_5084_50840502_21_dialog_content = "당신은 깨달음을 얻었나?",
  ui_story_5084_50840502_22_dialog_content = "물론이지.",
  ui_story_5084_50840502_23_dialog_content = "가주들이여, 이것은 우리 피의 일족의 계율이자 비밀이다.",
  ui_story_5084_50840502_24_dialog_content = "모두 가주의 지위를 직시하고, 그 살인귀의 전철을 밟지 않기를 바란다.",
  ui_story_5084_50840502_25_dialog_content = "진리의 축복 있으라.",
  ui_story_5084_50840502_26_dialog_content = "진리의 축복 있으라.",
  ui_story_5084_50840502_27_dialog_content = "이건 내가 혈통에 각성했을 때 진작 보았던 것들이다.",
  ui_story_5084_50840502_28_dialog_content = "성명제의 오랜 의식에서 선조들은 어린 양의 피를 모두 마시고,\n황홀경 속에서 신의 계시를 듣지.",
  ui_story_5084_50840502_29_dialog_content = "잠깐만...! 성명제의 계시를 받을 자는 결국 가주들한테 잡아먹히는 거였어?!",
  ui_story_5084_50840502_30_dialog_content = "그래서 거길 나올 때 그 사람들이 다 같이 웃었던 거야?!",
  ui_story_5084_50840502_31_dialog_content = "빅토리아 씨가 제물이 돼서 저런 꼴을 당한 거냐고!",
  ui_story_5084_50840502_32_dialog_content = "...누구냐?",
  ui_story_5084_50840502_33_dialog_content = "호오? 네 방에 손님이 있는 모양이군.",
  ui_story_5084_50840502_34_dialog_content = "......",
  ui_story_5084_50840502_35_dialog_content = "PlayerName... 뭐 한 거야? 빌헬름 님이 우릴 눈치채신 거 아냐?",
  ui_story_5084_50840502_36_dialog_content = "미안... 방금 너무 흥분해서...",
  ui_story_5084_50840502_37_dialog_content = "근데 빌헬름 씨의 의식 속에서 무서운 걸 봤단 말이야...",
  ui_story_5084_50840502_38_dialog_content = "빅토리아 씨가 걱정돼. 다시 봐야겠어!",
  ui_story_5084_50840502_39_option_content = "(감응 연결──)",
  ui_story_5084_50840502_40_dialog_content = "그럼 이건 어떻지?",
  ui_story_5084_50840502_41_dialog_content = "조카딸을 제물로 바쳐도 넌 여전히 주의 계시를 받을 수 없었다. 그래서 미쳐버린 거냐?",
  ui_story_5084_50840502_42_dialog_content = "뭐, 됐다. 너와 이 재미없는 놀이를 하는 것도 이젠 지겹다.",
  ui_story_5084_50840502_43_dialog_content = "빌헬름! 핏빛 성전은 이미 내 손안에 있다! 진리를 아는 건 나다!",
  ui_story_5084_50840502_44_dialog_content = "...! 이건 예언이냐...? 성명제... 오늘 밤...?!",
  ui_story_5084_50840502_45_dialog_content = "(교회에서 본 그 가주야! 오늘 밤 성명제에서 빅토리아 씨가 제물이 된다고...?\n그럼 지금이 1915년이란 소리잖아!)",
  ui_story_5084_50840502_46_dialog_content = "믿지 못하겠나?",
  ui_story_5084_50840502_47_dialog_content = "...이것이 이 빌헬름 왈라키아의 최후인가?",
  ui_story_5084_50840502_48_dialog_content = "넌 아직 왈라키아가 가진 힘을 완전히 이해하지 못했다.\n그럼에도 자신의 처지를 이유로 피의 일족을 사형에 처했다.",
  ui_story_5084_50840502_49_dialog_content = "젊은 세대는 늘 계율이나 교의를 하찮게 여기는 법이지.",
  ui_story_5084_50840502_50_dialog_content = "그러나 진리의 결사의 지도자는 네가 아닌 것은 확실하다.",
  ui_story_5084_50840502_51_dialog_content = "흐흐... 하하하하...",
  ui_story_5084_50840502_52_dialog_content = "진리? 황당하군...",
  ui_story_5084_50840502_53_dialog_content = "형님의 고귀한 손에 오래 잡혀 있었더니, 성격까지 형님을 닮게 된 거냐?",
  ui_story_5084_50840502_54_dialog_content = "형님은 내게 저주를 남겼다. 한편으로는 날 가주로 세워놓고,\n정작 빅토리아가 지도자가 되는 것을 본 후 스스로 물러나라니...",
  ui_story_5084_50840502_55_dialog_content = "미래의 허상을 보여주고 상대를 왜곡해서 조종하는 것이 교사자의 목적이지.",
  ui_story_5084_50840502_56_dialog_content = "그건 누구보다 내가 잘 알고 있다...",
  ui_story_5084_50840502_57_dialog_content = "이미 한 번 잘못을 범했던 내가 같은 전철을 밟을 것 같나?",
  ui_story_5084_50840502_58_dialog_content = "그래서 빅토리아를 죽일 생각은 전혀 없다는 거냐?",
  ui_story_5084_50840502_59_dialog_content = "없다.",
  ui_story_5084_50840502_60_dialog_content = "망설이고 있군.",
  ui_story_5084_50840502_61_dialog_content = "그녀를 죽이려는 것은 저 가주들이다. 나는 왈라키아 일족의 차남, 죽어도 여한은 전혀 없다.\n다만 저들은 빅토리아가 강대해지는 것이 두려울 뿐이다.",
  ui_story_5084_50840502_62_dialog_content = "만약 예언이 진실이라면...",
  ui_story_5084_50840502_63_dialog_content = "빅토리아는 혈통 각성에 좀 더 시간이 걸린다. 게다가 내가 전하는 진리도 들으려 하지 않는다.",
  ui_story_5084_50840502_64_dialog_content = "만약 내가 죽는다면, 저 벌레 놈들은 그녀를 내버려두지 않겠지...",
  ui_story_5084_50840502_65_dialog_content = "빅토리아... 빅토리아...",
  ui_story_5084_50840502_66_dialog_content = "(어? 이 사람은 빅토리아 씨를 걱정하는 거였어?)",
  ui_story_5084_50840502_67_dialog_content = "아니지... 난 진리의 결사의 지도자고... 계시를 받을 자는 내가 공표한다! 하지만...",
  ui_story_5084_50840502_68_dialog_content = "그녀는 아까 오늘 밤 성명제에 참가하지 않겠다고 했다...\n그렇다면 어딜 가서 그녀를 찾아야...",
  ui_story_5084_50840502_69_dialog_content = "마침 교회에 나타났잖아! 이러다간 진짜로 제물이 돼버리겠어!",
  ui_story_5084_50840502_70_dialog_content = "대체 누가 여기에...",
  ui_story_5084_50840502_71_dialog_content = "(이, 이런...!)",
  ui_story_5084_50840502_72_dialog_content = "훗, 남겨둔 수가 있었나 보군.",
  ui_story_5084_50840502_73_dialog_content = "PlayerName! 너 또 뭐 한 거야...?",
  ui_story_5084_50840502_74_dialog_content = "...망했네... 빅토리아 씨를 제물로 바친다고 하니까 나도 모르게 그만...",
  ui_story_5084_50840502_75_dialog_content = "빅토리아 님을 제물로 바치는 게... 오늘 밤이야? 그럼 아까 본 거랑 같은 거 아냐?!",
  ui_story_5084_50840502_76_dialog_content = "빌헬름 씨는 빅토리아 씨를 많이 걱정하는 것 같았어.\n하지만 저 사람이 빅토리아 씨한테 뭘 할 생각인지 확인해야 해...",
  ui_story_5084_50840502_77_dialog_content = "설마... 이 서재에 <color=#FFB400>애스턴 왈라키아</color>의 유품이 또 남아 있는 건가?",
  ui_story_5084_50840502_78_dialog_content = "아니면... 주님께서...?",
  ui_story_5084_50840502_79_dialog_content = "주여... 방금 빅토리아를 제물로 바치라고 하신 게... 정말이십니까?",
  ui_story_5084_50840502_80_dialog_content = "주님?",
  ui_story_5084_50840502_81_dialog_content = "말해라, 방금 누구와 이야기를 하고 있었지?",
  ui_story_5084_50840502_82_dialog_content = "주님이시다...!",
  ui_story_5084_50840502_83_dialog_content = "...크아악! <size=45>이 빌어먹을 반지가!</size>",
  ui_story_5084_50840502_84_dialog_content = "날 죽여라... 날 풀어달란 말이다!",
  ui_story_5084_50840502_85_dialog_content = "어디 네 비틀어진 모습을 보여 봐라.",
  ui_story_5084_50840502_86_dialog_content = "으...으아아아악!",
  ui_story_5084_50840502_87_dialog_content = "...으하하하하하! 진리의 결사의 지도자는 나다! 나란 말이다!",
  ui_story_5084_50840502_88_dialog_content = "(반지의 힘이 또 빌헬름 씨를 공격하고 있어! 어떡하지...)",
  ui_story_5084_50840502_89_dialog_content = "못난 놈, 이미 말했을 텐데, 넌 죽어야만 살아남을 수 있다.",
  ui_story_5084_50840502_90_dialog_content = "죽는 건 상관없다... 하지만 빅토리아는... 어떻게 하란 말이냐!",
  ui_story_5084_50840502_91_dialog_content = "...주여...",
  ui_story_5084_50840502_92_dialog_content = "빅토리아는 이제 어떻게 하란 말입니까...!",
  ui_story_5084_50840502_93_dialog_content = "완전히 정신이 나갔어... 저러다가 죽겠어!",
  ui_story_5084_50840502_94_dialog_content = "PlayerName 너 감응 중엔 과거 사람들한테 뭔가 전할 수 있는 거 아냐?\n한번 해 보는 건 어때?",
  ui_story_5084_50840502_95_dialog_content = "근데 함부로 말을 걸어서 과거에 영향을 미쳤다간 어떻게 될지 몰라...",
  ui_story_5084_50840502_96_dialog_content = "메이, 너도 똑같이 진리의 주인을 믿잖아?\n넌 어떤 말을 들으면 마음이 평온해지고 괴로움과 의문이 사라지는 것 같아?",
  ui_story_5084_50840502_97_dialog_content = "당연히 「진리의 축복 있으라」, 그리고 「모든 것은 인도를 따르라」지.",
  ui_story_5084_50840502_98_dialog_content = "그거면 돼...? 그럼 한번 해 볼게...",
  ui_story_5084_50840502_99_option_content = "(감응 연결──)",
  ui_story_5084_50840502_100_dialog_content = "진리의 축복 있으라.",
  ui_story_5084_50840502_101_dialog_content = "......",
  ui_story_5084_50840502_102_dialog_content = "진리의 축복 있으라.",
  ui_story_5084_50840502_103_dialog_content = "진리의... 축복 있으라...",
  ui_story_5084_50840502_104_dialog_content = "당신은... 대체 누구십니까...?",
  ui_story_5084_50840502_105_dialog_content = "(성공한 것 같아. 절대 말실수하면 안 돼...)",
  ui_story_5084_50840502_106_dialog_content = "죄송하지만 전 이제 더는 제 마음을 조종하는 「신」을 믿을 수 없습니다...\n제 마음속 진리는 자명합니다...",
  ui_story_5084_50840502_107_dialog_content = "진리의 결사는... 적어도 빅토리아의 미래는... 이대로는 안 됩니다.",
  ui_story_5084_50840502_108_dialog_content = "당신도 진리의 주인을 믿는다면, 절 이해하실 것입니다...",
  ui_story_5084_50840502_109_dialog_content = "당신이 지금 여기에 나타난 것은 분명히 제게 뭔가 전하기 위해서겠지요...",
  ui_story_5084_50840502_110_dialog_content = "...모든 것은 인도를 따르라.",
  ui_story_5084_50840502_111_dialog_content = "...제게 현실을 받아들이고, 가주들에게 잡아먹힐 날만 기다리란 말씀이십니까...?",
  ui_story_5084_50840502_112_dialog_content = "그리고 빅토리아에게 계속 이 혈족의 저주를 이어가서, 저 흡혈귀에게 죽게 하란 겁니까?",
  ui_story_5084_50840502_113_dialog_content = "(뭐, 뭐야... 어째 더 안 좋게 흘러가고 있는 것 같은데...)",
  ui_story_5084_50840502_114_dialog_content = "...아니, 절대 그럴 순 없습니다!",
  ui_story_5084_50840502_115_dialog_content = "제가 여기까지 올 수 있었던 건 일족의 배척을 받은 후, 제가 신봉하는 진리의 수행에\n홀로 힘써 왔기 때문입니다. 진리란 그런 게 아닙니다!",
  ui_story_5084_50840502_116_dialog_content = "전부 그 무의미한 계시를 믿은 탓에, 진리의 결사는 이 지경으로 타락한 거란 말입니다...",
  ui_story_5084_50840502_117_dialog_content = "전 반드시... 저주를 풀 겁니다...",
  ui_story_5084_50840502_118_dialog_content = "어떻게든... 방법을 찾아야 해...",
  ui_story_5084_50840502_119_dialog_content = "...그래... 아직 지도자의 기운에 물들지 않은 성물은... <color=#FFB400>그것</color>뿐이다...",
  ui_story_5084_50840502_120_dialog_content = "피의 달... 등나무 덩굴이 사람의 모습으로 변할 때...\n수호의 일족은 무덤의 주인이 오기를 기다린다...",
  ui_story_5084_50840502_121_dialog_content = "하지만 선조의 관을 운반하는 게 아니라면... 오직 <color=#FFB400>열쇠</color>가 있어야만 한다...\n아니면 모든 가주가 모여야만, 내가 무덤에 들어갈 수 있겠지...",
  ui_story_5084_50840502_122_dialog_content = "...빌헬름, 빌헬름! 대체 뭘 하고 있는 거냐! 잡아먹힐 처지가 되어서도\n여전히 그런 규칙을 고집하다니... 그러니 저들에게 농락당하는 게 아니냐...!",
  ui_story_5084_50840502_123_dialog_content = "...클라비스가 내게 열쇠를 빌려주지 않더라도,\n「덩굴인간」은 대대로 왈라키아를 섬겨 왔다...",
  ui_story_5084_50840502_124_dialog_content = "내가 얻은 이 계시를 알면... 분명히 내게 문을 열어 줄 것이다.",
  ui_story_5084_50840502_125_dialog_content = "...반드시 행진이 시작되기 전까지 무덤에 들어가야 한다.",
  ui_story_5084_50840502_126_dialog_content = "<color=#e8d9bb>휘이잉──!</color>",
  ui_story_5084_50840502_127_dialog_content = "메이! 꽉 잡아!",
  ui_story_5084_50840502_128_dialog_content = "이번엔 어디로 가는 거야?",
  ui_story_5084_50840502_129_dialog_content = "왈라키아의 무덤이야!",
  ui_story_5084_50840601_1_dialog_content = "<color=#e8d9bb>왈라지 마을, 재봉소 입구</color>",
  ui_story_5084_50840601_2_dialog_content = "손재주 있는 부인에게 진리의 축복 있으라.",
  ui_story_5084_50840601_3_dialog_content = "후한 손님에게 진리의 축복 있으라.\n그토록 거룩해 보이시니, 분명히 올해의 계시를 받을 자가 될 거예요.",
  ui_story_5084_50840601_4_dialog_content = "감사합니다. 그럼 먼저 가 보겠습니다. 오늘 밤 의식에서 만납시다, 늦으시면 안 됩니다.",
  ui_story_5084_50840601_5_dialog_content = "네, 의식 때 봐요.",
  ui_story_5084_50840601_6_dialog_content = "...내가 어떻게... 여기에...?",
  ui_story_5084_50840601_7_dialog_content = "손님도 축제의 로브를 받으러 오셨나요?",
  ui_story_5084_50840601_8_dialog_content = "축제의 로브...?",
  ui_story_5084_50840601_9_dialog_content = "아, 다른 가게 손님이신 모양이군요.",
  ui_story_5084_50840601_10_dialog_content = "다만 우리 재봉소는 마을에서 제일가는 노포랍니다.\n성명제의 로브 주문도 가장 많이 받고 있지요.",
  ui_story_5084_50840601_11_dialog_content = "외진 마을에 사는 여러 신도들이 축제의 밤에 우리 재봉소에 로브를 사러 오곤 해요.",
  ui_story_5084_50840601_12_dialog_content = "괜찮으시다면, 우리 가게에서 로브를 하나 사시는 건 어떠신가요? 가격은 잘 맞춰드릴게요.",
  ui_story_5084_50840601_13_dialog_content = "......",
  ui_story_5084_50840601_14_dialog_content = "손님, 보세요. 피의 달이 곧 모습을 드러낼 거예요.",
  ui_story_5084_50840601_15_dialog_content = "...피의 달... 그럼 오늘 밤 성명제가 있겠군요...",
  ui_story_5084_50840601_16_dialog_content = "멘토님께선 축제에서 절 계시를 받을 자로 뽑겠다고 하셨습니다.\n그래서 전 깨끗한 옷을 한 벌 사려던 중이었습니다.",
  ui_story_5084_50840601_17_dialog_content = "...계시를 받을 자라고요?! 제가 잘못 들은 건 아니겠죠...?",
  ui_story_5084_50840601_18_dialog_content = "그걸 선언하는 건 빌헬름 왈라키아 님일 텐데요. 어떻게 그분께 선택되신 거죠?",
  ui_story_5084_50840601_19_dialog_content = "네, 그분이 바로 제 멘토님입니다. 우린 무덤에서 만났습니다.",
  ui_story_5084_50840601_20_dialog_content = "왈라키아의 무덤 말인가요...?!\n그러셨군요... 혹시 어떻게 진리를 깨달으셨는지 들려주실 수 있겠습니까?",
  ui_story_5084_50840601_21_dialog_content = "...전 늘 참회하고 있습니다. 하지만 사람들은 모두 절 피했습니다...\n오직 멘토님만 제외하고 말입니다.",
  ui_story_5084_50840601_22_dialog_content = "참회... 성명제... 피의 달... 왠지 알 것 같네요...",
  ui_story_5084_50840601_23_dialog_content = "계시를 받을 분이 여기 오신 건... 제게 이런 진리를 전하기 위해서였군요...",
  ui_story_5084_50840601_24_dialog_content = "전 성명제를 명목으로 신도들에게 돈을 받아 왔습니다...\n그래서 진리에 접근할 수 없었던 것이군요...",
  ui_story_5084_50840601_25_dialog_content = "계시를 주셔서 감사합니다...",
  ui_story_5084_50840601_26_dialog_content = "여기서 잠시 쉬고 가지 않으시겠습니까?\n제가 저희 어머니, 그리고 제 딸과 함께 가장 빠르게 로브를 만들어 드리겠습니다!",
  ui_story_5084_50840601_27_dialog_content = "그, 그러실 필요까진 없습니다만...\n전 그저 우연히 지나가다가 멘토님이 계신 곳을 물어보러 왔을 뿐입니다.",
  ui_story_5084_50840601_28_dialog_content = "우연이 아닙니다. 여기 오신 것은 진리의 인도인 겁니다!\n제 제안이 너무 갑작스럽겠지만, 아무쪼록 양해해 주시길 바랍니다...",
  ui_story_5084_50840601_29_dialog_content = "아니, 정말 그럴 필요는...",
  ui_story_5084_50840601_30_dialog_content = "엄마? 뭐 해?! 우리 손님이 한참 기다렸어!",
  ui_story_5084_50840601_31_dialog_content = "가서 그 손님한테 돈 안 받는다고 말씀드려. 로브는 공짜로 주겠다고 해!",
  ui_story_5084_50840601_32_dialog_content = "하?",
  ui_story_5084_50840601_33_dialog_content = "그리고 지금부터 우린 계시를 받을 손님께 로브를 만들어 드려야 해!",
  ui_story_5084_50840601_34_dialog_content = "지금?",
  ui_story_5084_50840601_35_dialog_content = "그래.",
  ui_story_5084_50840601_36_dialog_content = "할머니가 화낼 텐데...",
  ui_story_5084_50840601_37_dialog_content = "내 말대로 해. 할머니한테는 내가 말할 테니까.",
  ui_story_5084_50840601_38_dialog_content = "응...",
  ui_story_5084_50840601_39_dialog_content = "...주여! 저는 또 잘못을 저질렀습니다...",
  ui_story_5084_50840601_40_dialog_content = "전... 그래도 돈이 조금은 있으니까... 저들의 적은 수입에 도움을 주고 싶었습니다...",
  ui_story_5084_50840601_41_dialog_content = "하지만 재봉소 모녀의 성의를 저버릴 수도 없습니다... 어찌하면 좋겠나이까...",
  ui_story_5084_50840601_42_dialog_content = "빌헬름.",
  ui_story_5084_50840601_43_dialog_content = "누가 감히 내 이름을 함부로 부르고 앞을 막는 것이냐?\n비켜라, 나는 지금부터 성명제의 의식을 거행해야 한다.",
  ui_story_5084_50840601_44_dialog_content = "진리의 깊은 뜻을 잊고 현실에 눈이 가려졌구나.",
  ui_story_5084_50840601_45_dialog_content = "너는 그 책임을 감당하지 못한다. 내가 대신 책임져 주마...",
  ui_story_5084_50840601_46_dialog_content = "어느 가주가 보낸 졸개냐? 덤벼라!",
  ui_story_5084_50840601_47_dialog_content = "<color=#e8d9bb>촛불이 다시 켜지자, 주변에 또 새로운 광경이 펼쳐졌다.\n무척이나 오래되어 보이는 한 무덤이 눈앞에 자리 잡고 있었다.</color>",
  ui_story_5084_50840601_48_dialog_content = "<color=#e8d9bb>음산한 바람이 정면에서 불어와 등나무 덩굴에 오랫동안 쌓여 있던 먼지를 날려버렸다.</color>",
  ui_story_5084_50840601_49_dialog_content = "<color=#e8d9bb>그 순간, 갑자기 등나무 덩굴이 꿈틀거리기 시작했다.\n덩굴은 스스로 계속 퍼지더니, 품속에 가두고 있던 사람을 풀어주었다...</color>",
  ui_story_5084_50840601_50_dialog_content = "우리 도착했어... 저 사람...",
  ui_story_5084_50840601_51_dialog_content = "(...내가 어떻게 여기에...?)",
  ui_story_5084_50840601_52_dialog_content = "(설마 아까 마주친 「그자」의 소행인가? 모종의 비술로 날 이곳으로 보내고...\n자신이 대신 의식에 참여한 건가...?)",
  ui_story_5084_50840601_53_dialog_content = "피의 달이 가려졌군... 지금이 언제인 거냐. 설마 성명제가 지나가 버린 건 아니겠지?",
  ui_story_5084_50840601_54_dialog_content = "당신은 영광스러운 계시를 받았습니다.",
  ui_story_5084_50840601_55_dialog_content = "<color=#e8d9bb>무덤 입구의 등나무 덩굴은 뒤엉켜 사람의 모습을 이루었다.\n그 얼굴은 앙상했고, 눈빛은 어스름했다.</color>",
  ui_story_5084_50840601_56_dialog_content = "선조의 무덤은 이미 열려 있습니다.",
  ui_story_5084_50840601_57_dialog_content = "...왜지?",
  ui_story_5084_50840601_58_dialog_content = "<color=#FFB400>열쇠</color>는 여기에 있습니다... 「그 불꽃」의 존재가 느껴지는군요.",
  ui_story_5084_50840601_59_dialog_content = "불꽃? 여기서 유일하게 타고 있는 건... 우리 촛대뿐이잖아?",
  ui_story_5084_50840601_60_dialog_content = "설마... 나 때문인 건가? 내 목소리가 빌헬름 씨를 여기로 이끌고 이 문을 연 거야?",
  ui_story_5084_50840601_61_dialog_content = "내가 대체... 뭘 바꿔버린 거지?",
  ui_story_5084_50840601_62_dialog_content = "잠깐, 나는 아무것도...",
  ui_story_5084_50840601_63_dialog_content = "<color=#e8d9bb>빌헬름이 말을 끝나기도 전에, 덩굴인간의 형태는 다시 흩어졌고,\n푸른 이끼가 덮인 땅으로 돌아가 침묵의 문지기로 모습을 바꾸었다.</color>",
  ui_story_5084_50840601_64_dialog_content = "(무덤의 문이 열리고, 무덤지기가 들어가는 것을 허락했다...)",
  ui_story_5084_50840601_65_dialog_content = "(나는 아무것도 하지 않았거늘, 설마 이것이 바로 진리의 뜻이란 말인가.)",
  ui_story_5084_50840601_66_dialog_content = "(운명이 날 이곳으로 이끌었다. 주께서는 내가 당신께서 내리신 사명을 완수하길 바라신다.)",
  ui_story_5084_50840601_67_dialog_content = "(반드시 들어가야만 한다.)",
  ui_story_5084_50840601_68_dialog_content = "뭘 하려는 거지...? 메이, 따라가자!",
  ui_story_5084_50840601_69_dialog_content = "(왈라키아의 선조여, 정녕 계시가 존재한다면 부디 조금 더 명확하게 보여 주소서...)",
  ui_story_5084_50840601_70_dialog_content = "(...선조의 관이 없어졌다! 행진이 끝나면 관은 이곳으로 돌아와야 마땅한데...)",
  ui_story_5084_50840601_71_dialog_content = "(감히 왈라키아의 안식처를 모독하는 자가... 아니지...)",
  ui_story_5084_50840601_72_dialog_content = "(아무것도 없다... 선조의 관, 게다가 핏빛 성전조차 보이지 않는다...)",
  ui_story_5084_50840601_73_dialog_content = "(가주들이 벌써 움직인 건가?)",
  ui_story_5084_50840601_74_dialog_content = "(빅토리아가 위험하다...!)",
  ui_story_5084_50840601_75_dialog_content = "「서리밤의 신사」여! 마을의 교회로 가자!",
  ui_story_5084_50840601_76_dialog_content = "우와, 엄청 멋있는 검은 말이네...가 아니지! 얼른 쫓아가자!",
  ui_story_5084_50840601_77_dialog_content = "(사도? 어째서 사도가 여길 떠돈단 말이냐!)",
  ui_story_5084_50840601_78_dialog_content = "(신도의 시신...? 역시 마을에서 큰일이 벌어졌군...!)",
  ui_story_5084_50840601_79_dialog_content = "더러움으로 얼룩진 열등한 존재가 감히 이 땅에 발을 들이고 신도를 해치다니!",
  ui_story_5084_50840601_80_dialog_content = "이성을 잃은 어리석은 존재여, 너희의 주인이 너흴 풀어준 모양이로구나.",
  ui_story_5084_50840601_81_dialog_content = "그렇다면 내가 너희를 정화해 주마!",
  ui_story_5084_50840602_1_dialog_content = "오오, 우리의 지도자... 빌헬름 왈라키아 님... 정말 매력이 넘치시는 분이야...",
  ui_story_5084_50840602_2_dialog_content = "저분의 계시 덕분에 난 진리의 문 너머를 엿볼 수 있었지.",
  ui_story_5084_50840602_3_dialog_content = "(신도들은 저 괴물들의 횡포를 전혀 눈치채지 못한 모양이군...)",
  ui_story_5084_50840602_4_dialog_content = "(성명제의 의식은 이미 끝났다. 가주들은 아직 교회에 있을 것이다...)",
  ui_story_5084_50840602_5_dialog_content = "겨, 겨우 따라잡았어... 휴...휴우...",
  ui_story_5084_50840602_6_dialog_content = "메이, 저기 좀 봐! 전에 네가 전도하려뎐 그 사람들이잖아! 그럼 시간이 연결된 거야!",
  ui_story_5084_50840602_7_dialog_content = "그때의 우리도 분명히 안에 있을 거야!",
  ui_story_5084_50840602_8_dialog_content = "신자들이 모두 돌아가기에 의식이 끝난 줄 알았는데, 여기서 기다려 주실 줄은 몰랐습니다.",
  ui_story_5084_50840602_9_dialog_content = "나일즈! 네가 왜 여기 있어?!",
  ui_story_5084_50840602_10_dialog_content = "그 옷은 또 뭐야...?",
  ui_story_5084_50840602_11_dialog_content = "마음씨 좋은 재봉사가 절 위해 만들어 준 것입니다. 전 정말 감격했습니다.",
  ui_story_5084_50840602_12_dialog_content = "멘토님, 절 이곳에 초대해 주셔서 감사합니다.",
  ui_story_5084_50840602_13_dialog_content = "넌...",
  ui_story_5084_50840602_14_dialog_content = "어? 나일즈? 그게 대체 무슨 소리야?",
  ui_story_5084_50840602_15_dialog_content = "어차피 나일즈 씨 이야기는 평소에도 이해가 안 되는데 뭐...",
  ui_story_5084_50840602_16_dialog_content = "저는 이번 의식의 제물이 될 수 있어 정말 기쁩니다.",
  ui_story_5084_50840602_17_dialog_content = "무슨 말을 하는 건지 모르겠군. 먼저 실례하지.",
  ui_story_5084_50840602_18_dialog_content = "포르피리오, 핏빛 성전은 어디 있지?",
  ui_story_5084_50840602_19_dialog_content = "오히려 내가 묻고 싶군. 방금 그 회오리바람은 뭐냐. 빅토리아는 또 어디 갔냔 말이다!",
  ui_story_5084_50840602_20_dialog_content = "빅토리아?",
  ui_story_5084_50840602_21_dialog_content = "조카딸을 제물로 바쳐도 넌 여전히 주의 계시를 받을 수 없었다. 그래서 미쳐버린 거냐?",
  ui_story_5084_50840602_22_dialog_content = "뭐, 됐다. 너와 이 재미없는 놀이를 하는 것도 이젠 지겹다.",
  ui_story_5084_50840602_23_dialog_content = "빌헬름! 핏빛 성전은 이미 내 손안에 있다! 진리를 아는 건 나다!",
  ui_story_5084_50840602_24_dialog_content = "하지만... 올해 의식은 이미 끝났다. 난 우리가 아직 대화할 여지가 있다고 생각하는데.",
  ui_story_5084_50840602_25_dialog_content = "...예언 속에서 보았던 모습이로군... 하하하... 대화? 날 없앨 생각이겠지!",
  ui_story_5084_50840602_26_dialog_content = "연극은 집어치워라. 넌 네 시종을 시켜서 무고한 신도를 해쳤지.\n하지만 놈들은 이미 내가 정화했다!",
  ui_story_5084_50840602_27_dialog_content = "그렇다면...",
  ui_story_5084_50840602_28_dialog_content = "우리에게 굴복할 생각은 없는 모양이군...\n난 아직 성언을 더 들어야 하니, 대신 수고해 주게.",
  ui_story_5084_50840602_29_dialog_content = "될 것 같으냐!",
  ui_story_5084_50840602_30_dialog_content = "소용없다, 빌헬름. 성전은 내 손 안에 있고, 운명은 이미 나의 편이다...",
  ui_story_5084_50840602_31_dialog_content = "일할 시간이다, 「살무사」.",
  ui_story_5084_50840602_32_dialog_content = "멘토님에게 뭘 할 생각입니까? 계시를 받을 사람은 저입니다.",
  ui_story_5084_50840602_33_dialog_content = "어디서 온 외지인이냐.",
  ui_story_5084_50840602_34_dialog_content = "빌헬름 같은 놈도 추종자가 있었군. 먼저 죽이자고.",
  ui_story_5084_50840602_35_dialog_content = "진리의 결사의 가주라는 자들이 감히 신도를 해치려 들다니!",
  ui_story_5084_50840602_36_dialog_content = "내 걱정부터 하는 게 좋을 텐데, 하하하하!",
  ui_story_5084_50840602_37_dialog_content = "빌헬름...!",
  ui_story_5084_50840602_38_dialog_content = "주여, 당신의 고통을 내리사, 저로 하여금 견디게 하소서.\n삼키고, 탈피할지어다. 진리는 횡포를 압도하리니...",
  ui_story_5084_50840602_39_dialog_content = "안 돼! 나일즈 씨! 빨리 도망쳐──!",
  ui_story_5084_50840602_40_dialog_content = "멈춰! 메이! 우린 개입해선 안 돼... 스칼렛이 한 말을 기억해...!",
  ui_story_5084_50840602_41_dialog_content = "다 내 탓이야... 내가 말을 꺼내 버려서 모든 게 변해버린 거야...\n어떻게든 저들을 도울 다른 방법을 찾을게... 우린 촛대가 있잖아. 분명히 방법이 있을 거야!",
  ui_story_5084_50840602_42_dialog_content = "훗, 의외로 경건한 고집불통이었군.",
  ui_story_5084_50840602_43_dialog_content = "죽어라!",
  ui_story_5084_50840602_44_dialog_content = "주여, 당신의 의식이 이토록 잔혹하다니, 다른 신자들도 이것을 겪어 보았는지요...\n그들은 어떻게 이 고난을 극복했나이까...",
  ui_story_5084_50840602_45_dialog_content = "저는 견디겠나이다. 고통의 상처를 삼키고, 자신의 죄를 씻겠나이다.\n비통의 저주를 감내하고, 영혼의 상처를 태워버리겠나이다──",
  ui_story_5084_50840602_46_dialog_content = "바라컨대 이 모든 고통을 제게 주사, 다른 이에게 미치지 않게 하소서.\n자, 이 몸을 상하게 하여 무거운 죄업을 지우게 하소서.",
  ui_story_5084_50840602_47_dialog_content = "이 생생한 고통으로 저들을 위해 속죄하겠나이다!",
  ui_story_5084_50840602_48_dialog_content = "(이대로는 나일즈가 진짜로 저놈들 손에 죽을 거야! 뭔가 해야만 해...\n그래, 촛대! 이 상황을 바꿀 수 있는 시간으로 날 데려가 줘...)",
  ui_story_5084_50840602_49_dialog_content = "어리석은 녀석!",
  ui_story_5084_50840602_50_dialog_content = "저들은 의식을 거행할 생각도, 네 영혼을 정화할 생각도 없다! 그저 널 죽이려는 것뿐이다!",
  ui_story_5084_50840602_51_dialog_content = "넌 고행자로 보이는군. 그렇다면 살아남아서, 몸부림치며 진리를 찾아라!",
  ui_story_5084_50840602_52_dialog_content = "...멘토님?",
  ui_story_5084_50840602_53_dialog_content = "살아남아라!",
  ui_story_5084_50840602_54_dialog_content = "<color=#e8d9bb>빌헬름은 엄청난 힘으로 나일즈를 일으켜 문밖으로 내던졌고,\n문이 열리면서 검은 바람이 불어 들어왔다.</color>",
  ui_story_5084_50840602_55_dialog_content = "으앗! 촛불이 꺼졌어!",
  ui_story_5084_50840602_56_dialog_content = "이제 어쩔 생각이냐. 얼마든지 덤벼라! 이 빌헬름 왈라키아가 그리 쉽게 굴복할 것 같으냐!",
  ui_story_5084_50840602_57_dialog_content = "하찮은 놈들, 내 검술을 똑똑히 보도록 해라!",
  ui_story_5084_50840602_58_dialog_content = "나와라, <color=#FF0000>적류</color>! 나의 마검이여! 나의 피를 마시고 적의 생기를 빼앗아라!",
  ui_story_5084_50840602_59_dialog_content = "뭐야... 싸우기 시작한 건가?",
  ui_story_5084_50840602_60_dialog_content = "아무것도 안 보여!",
  ui_story_5084_50840602_61_dialog_content = "공간이 또 바뀌려는 것 같아! 여기서 무슨 일이 있었는지 끝까지 봐야 해!\n어떻게든 제어하고... 전송을 멈춰야...",
  ui_story_5084_50840602_62_dialog_content = "메이! 내 뒤로 와서 날 꽉 잡아!",
  ui_story_5084_50840602_63_dialog_content = "쳇, 너무 어둡잖아.",
  ui_story_5084_50840602_64_dialog_content = "그래봤자 놈은 혼자다. 오래 버티진 못할 거다.",
  ui_story_5084_50840602_65_dialog_content = "크아악!",
  ui_story_5084_50840602_66_dialog_content = "자, 다음은 누구냐.",
  ui_story_5084_50840602_67_dialog_content = "클라비스, 내 뒤에 서라. 같이 싸우는 거다!",
  ui_story_5084_50840602_68_dialog_content = "......",
  ui_story_5084_50840602_69_dialog_content = "소용없다. 머리가 깨져도 나는 죽지 않는다.",
  ui_story_5084_50840602_70_dialog_content = "그럼 그 고통을 견딜 수 없을 때까지 깨부숴 주마!",
  ui_story_5084_50840602_71_dialog_content = "대단해... 혼자서 전부 상대하고 있어... 게다가 어둠 속인데... 전혀 밀리질 않잖아.",
  ui_story_5084_50840602_72_dialog_content = "...아직도 나서지 않는 건가?",
  ui_story_5084_50840602_73_dialog_content = "말이야 쉽지...",
  ui_story_5084_50840602_74_dialog_content = "아직도 남을 믿는 거냐? 데이비드! 네놈의 죽음이 다가왔다! 더는 희망을 바라지 마라!",
  ui_story_5084_50840602_75_dialog_content = "우리의 거래를 생각해라...",
  ui_story_5084_50840602_76_dialog_content = "......",
  ui_story_5084_50840602_77_dialog_content = "<size=45>악──!</size>",
  ui_story_5084_50840602_78_dialog_content = "뭐, 뭐야?! 갑자기 빌헬름 씨 기척이 안 느껴져! 설마...",
  ui_story_5084_50840602_79_dialog_content = "얼른 꽉 잡아! 우, 우리 왠지... 곧 다음 장소로 보내질 거 같아!",
  ui_story_5084_50840602_80_dialog_content = "...어째서... 대체 왜 이렇게 돼버린 건데...",
  ui_story_5084_50840602_81_dialog_content = "...만약 저 사람이 정말로 죽는다면... 빅토리아 씨는 어떻게 되는 거지?",
  ui_story_5084_50840602_82_dialog_content = "PlayerName, 저 빌헬름 님 말인데, 전혀 냉혹한 사람처럼 안 보이지 않아?\n저분이 정말 빅토리아 님을 제물로 삼은 게 맞을까...?",
  ui_story_5084_50840602_83_dialog_content = "나도 그게 의문이야... 촛불을 따라 움직이기 시작한 뒤로,\n우리가 마주쳤던 빌헬름 씨는 그 의식 때랑 전혀 다른 사람 같았어...",
  ui_story_5084_50840602_84_dialog_content = "내가 한 말 때문에 일련의 변화가 생긴 건지...",
  ui_story_5084_50840602_85_dialog_content = "아니면 두 빌헬름 씨 사이에 뭔가 차이가 있어서 그런 건지 모르겠어...",
  ui_story_5084_50840602_86_dialog_content = "빅토리아 님은 지금 어디 계실까...?",
  ui_story_5084_50840602_87_dialog_content = "처음 의식 때 빅토리아 씨는 빌헬름 씨가 실종됐다고 했어.\n어쩌면 그 실종의 진상을 쫓고 있는 건지도 몰라.",
  ui_story_5084_50840602_88_dialog_content = "저 의식, 역시 그리 단순한 게 아닌 것 같아...\n빅토리아 씨가 관에 들어가겠다고 한 건, 분명히 뭔가 알아내고 싶은 게 있어서였을 거야.",
  ui_story_5084_50840602_89_dialog_content = "두 사람 사이엔 왠지 오랫동안 쌓인 오해가 있는 것 같아...\n아마 서로 미처 하지 못했던 말도 있겠지.",
  ui_story_5084_50840700_1_dialog_content = "PlayerName! 여긴 촛불이랑 화단이 잔뜩 있어! 어라... 저건... 관이야?!",
  ui_story_5084_50840700_2_dialog_content = "그런 것 같네...",
  ui_story_5084_50840700_3_dialog_content = "우리 이번엔 또 어디로 온 걸까?",
  ui_story_5084_50840700_4_dialog_content = "창밖이 뭔가 음산한데, 어디 보자...",
  ui_story_5084_50840700_5_dialog_content = "여긴 절벽 위에 지어진 고성이야! 누가 집을 굳이 이런 데다 지은 거냐고...",
  ui_story_5084_50840700_6_dialog_content = "<color=#e8d9bb>뚜벅, 뚜벅, 뚜벅...</color>",
  ui_story_5084_50840700_7_dialog_content = "앗! 빅토리아 님이다!",
  ui_story_5084_50840700_8_dialog_content = "...어째서지? 방금 빅토리아 씨를 생각해서 그런 건가?",
  ui_story_5084_50840700_9_dialog_content = "잠깐만, 한 명 더 있어.",
  ui_story_5084_50840700_10_dialog_content = "너도 빌헬름을 찾으러 온 것이냐.",
  ui_story_5084_50840700_11_dialog_content = "그의 거처를 찾는 건 적이 아니면 친족뿐이지.",
  ui_story_5084_50840700_12_dialog_content = "어디 있어?",
  ui_story_5084_50840700_13_dialog_content = "유감이지만 이번엔 나도 모른다. 아무 흔적도 남기지 않고 떠났으니 말이야.",
  ui_story_5084_50840700_14_dialog_content = "안타깝네. 아무리 그 사람이라도 마음을 아는 친구 한두 명쯤은 있을 줄 알았는데.",
  ui_story_5084_50840700_15_dialog_content = "우리가 한때 그런 사이였던 건 분명하다.",
  ui_story_5084_50840700_16_dialog_content = "만약... 빌헬름이 막무가내로 행동하지만 않았다면,\n우린 영원히 좋은 벗으로 남을 수 있었겠지.",
  ui_story_5084_50840700_17_dialog_content = "빅토리아... 넌 빌헬름을, 네 숙부를 조금도 이해하려 들지 않는구나.",
  ui_story_5084_50840700_18_dialog_content = "난 그런 사람을 이해하고 싶진 않아.",
  ui_story_5084_50840700_19_dialog_content = "네 아버지가 진리의 결사의 지도자가 되기 전까지,\n빌헬름은 늘 그 자리를 차지하고 싶어 했다.",
  ui_story_5084_50840700_20_dialog_content = "그의 두 눈은 욕심에 멀었고, 과격한 이론에 빠져 그것을 진리로 추앙했다.",
  ui_story_5084_50840700_21_dialog_content = "그렇기에 그는 선조의 힘을 계승했을 때 잇달아 통제력을 상실했고...\n그때의 그는 이미 소외된 혈족이었으나, 그럼에도 그는 단념하지 않았다.",
  ui_story_5084_50840700_22_dialog_content = "그 미련은 그를 야심가의 꼭두각시로 만들었고, 그 결과 일족에서 추방되는 신세가 되었지.",
  ui_story_5084_50840700_23_dialog_content = "...그 사람 과거엔 관심 없어.",
  ui_story_5084_50840700_24_dialog_content = "그 사람의 손에서 벗어날 수 있어서 난 사실 무척 기쁘니까.",
  ui_story_5084_50840700_25_dialog_content = "밖을 여행하다가 주의 계시를 들었어... 그래서 오늘은 작별 인사를 하러 온 거야.",
  ui_story_5084_50840700_26_dialog_content = "난 계시를 받은 곳으로 가서 진리의 주인의 강림을 기다릴 거야.",
  ui_story_5084_50840700_27_dialog_content = "너는 왈라키아 혈통의 계승자, 모든 것은 너 자신이 선택하면 된다.",
  ui_story_5084_50840700_28_dialog_content = "참, 하나만 물어볼 수 있을까?\n처음에 그 사람... 빌헬름이 당신 집에서 빌리려던 건 대체 뭐야?",
  ui_story_5084_50840700_29_dialog_content = "그 <color=#FFB400>열쇠</color>는 널 해치게 될 거다.",
  ui_story_5084_50840700_30_dialog_content = "죽음을 앞둔 형님이 일부러 그걸 <color=#FFB400>덩굴인간</color> 손에서 되찾아서 네게 준 건...\n누가 봐도 그게 나한테 전해지도록 하기 위해서다.",
  ui_story_5084_50840700_31_dialog_content = "...네가 <color=#FFB400>덩굴인간</color> 손에서 억지로 빼앗는 걸 막기 위해서일 수도 있겠지.",
  ui_story_5084_50840700_32_dialog_content = "...! 그건 「만문의 열쇠」다... 야심에 불타는 자는 그것에 삼켜지게 되지.",
  ui_story_5084_50840700_33_dialog_content = "...자신을 잘 지켜라, 빅토리아 왈라키아.\n네 중임은 이제 막 주어졌을 뿐, 진리를 찾는 여정은 아직도 먼 길을 가야 할 것이다.",
  ui_story_5084_50840700_34_dialog_content = "<color=#e8d9bb>빅토리아는 떠나가는 클라비스를 지켜보았고,\n그가 사라진 후에야 몸을 돌려 빌헬름의 방으로 들어갔다.</color>",
  ui_story_5084_50840700_35_dialog_content = "내가 이해할 수 없는 사람, 당신은 지금 어디 있어?",
  ui_story_5084_50840700_36_dialog_content = "<color=#e8d9bb>그녀는 방을 빙 둘러보았고, 마지막으로 찬란한 관을 열더니 그 안에 누웠다.</color>",
  ui_story_5084_50840700_37_dialog_content = "아버지와 어머니께 다가갔던 것처럼 하면...\n나도 당신이 추구하는 모든 걸 이해할 수 있을까?",
  ui_story_5084_50840700_38_dialog_content = "(이 느낌... 빅토리아 씨가 뭔가를 회상하고 있어...)",
  ui_story_5084_50840700_39_dialog_content = "오늘 우리가 이 자리에 모인 것은 왈라키아 가문 가주의 영면을 추모하기 위해서다.",
  ui_story_5084_50840700_40_dialog_content = "오늘 이후로 이들 두 사람은 가련한 아가씨 빅토리아 왈라키아를 남기고,\n선조들의 반열에 올랐다.",
  ui_story_5084_50840700_41_dialog_content = "이쪽으로 오도록. 이 반지를 직접 아버지의 묘비에 올려두어라.\n이것은 그의 명예의 증거다. 지금 이 순간에도 그는 우리의 경의를 받아야 마땅하다.",
  ui_story_5084_50840700_42_dialog_content = "아버지... 어머니...",
  ui_story_5084_50840700_43_dialog_content = "서두를 필요는 없다. 우리의 가련한 아가씨가 아직 혼란과 슬픔에 잠겨 있는 것도 당연하니.",
  ui_story_5084_50840700_44_dialog_content = "괜찮다, 우리는 네 곁에서 이 어려운 때를 함께 이겨낼 것이다.\n참, 나는 데이비드 포르피리오다.",
  ui_story_5084_50840700_45_dialog_content = "네 아버지가 한때 내 혈통의 혼란을 잠재워 주었고, 덕분에 나는 귀중한 이성을 손에 넣었다.",
  ui_story_5084_50840700_46_dialog_content = "나는 클라비스 아브라함이다. 왈라키아와의 우정은 평생 잊지 않을 것이다.",
  ui_story_5084_50840700_47_dialog_content = "어떤 일이든 도움이 필요할 때면 언제든지 내게 말해도 좋다.",
  ui_story_5084_50840700_48_dialog_content = "왈라키아 아가씨... 제 이름 따위는 모르셔도 좋습니다.\n그저 하인이라고 불러 주시면 됩니다.",
  ui_story_5084_50840700_49_dialog_content = "아버지도... 그렇게 부르셨어?",
  ui_story_5084_50840700_50_dialog_content = "저는 그레이브스라고 합니다...",
  ui_story_5084_50840700_51_dialog_content = "시간이란 얼마나 참혹한 것이란 말인가, 나는 이미 내 이름을 잊어버렸다...\n사람들은 날 <color=#FFB400>살무사</color>라고 부르지. 아가씨도 날 그렇게 불러도 좋다.",
  ui_story_5084_50840700_52_dialog_content = "이로써 의식을 마치고, 왈라키아 가문의 가주는 안식을 얻었다.\n자, 이제 미래에 대해 말할 때가 된 것 같군.",
  ui_story_5084_50840700_53_dialog_content = "빅토리아 양, 그대는 아직 어리다. 아직은 이 반지의 힘을 견디기 힘들지도 모른다.",
  ui_story_5084_50840700_54_dialog_content = "그러니 내가 잠시 맡아두도록 하지. 걱정할 필요는 없다.\n왈라키아 일족이 아닌 자에게는 보통의 반지나 다름이 없으니 말이야...",
  ui_story_5084_50840700_55_dialog_content = "그런가? 그렇다면 왜 그렇게 그 반지를 손에 넣으려 하는 거냐.",
  ui_story_5084_50840700_56_dialog_content = "빌헬름 왈라키아?!",
  ui_story_5084_50840700_57_dialog_content = "흥, 왈라키아 가문의 핏줄이 한 명 더 있다는 걸 잊지 마라.\n진리의 결사의 지도자가 될 수 있는 것은 오직 왈라키아뿐이다.",
  ui_story_5084_50840700_58_dialog_content = "......",
  ui_story_5084_50840700_59_dialog_content = "왈라키아 가문에서 추방당한 이단 주제에, 감히 빅토리아 양 앞에서 그런 망언을 내뱉다니!",
  ui_story_5084_50840700_60_dialog_content = "잘 보아라. 지금이 바로 내가 선조의 지혜와 힘을 계승할 때다!",
  ui_story_5084_50840700_61_dialog_content = "으윽...",
  ui_story_5084_50840700_62_dialog_content = "하하하하! 그 실망한 얼굴은 뭐냐.\n왈라키아 일족이 이 반지를 끼는 모습을 보기 싫었던 모양이지?",
  ui_story_5084_50840700_63_dialog_content = "목도하라! 이제 나 빌헬름 왈라키아가 어둠으로 너희를 감싸 주리라.",
  ui_story_5084_50840700_64_dialog_content = "나는 이미 선조들의 인정을 받은 왈라키아의 새 가주다!",
  ui_story_5084_50840700_65_dialog_content = "빌헬름... 아직도 야심을 버리지 않았던 거냐.",
  ui_story_5084_50840700_66_dialog_content = "훗... 하하하하, 빅토리아 양, 아무래도 그대의 숙부는 그대의 자리를\n비워주고 싶지 않은 모양이군.",
  ui_story_5084_50840700_67_dialog_content = "이것은 왈라키아 가문의 일이니, 우리가 멋대로 개입할 순 없다... 이만 실례하지.",
  ui_story_5084_50840700_68_dialog_content = "빌헬름 왈라키아... 나의 숙부...",
  ui_story_5084_50840700_69_dialog_content = "어디로 갈 생각이야?",
  ui_story_5084_50840700_70_dialog_content = "물론 이곳을 떠나 내가 계승한 영지로 갈 것이다.",
  ui_story_5084_50840700_71_dialog_content = "빅토리아 왈라키아, 오늘부터 나는 네 후견인이다.\n내가 가주인 동안에는 너는 어떤 일이든지 내 말을 들어야 할 것이다.",
  ui_story_5084_50840700_72_dialog_content = "...언젠가 난 하늘의 계시를 얻을 거야. 그 반지는 아버지의 유품이고, 내 것이어야 해.",
  ui_story_5084_50840700_73_dialog_content = "얼마든지 그렇게 생각해라. 하지만 지금은 내 손에 있지.",
  ui_story_5084_50840700_74_dialog_content = "그보다... 하늘의 계시라고?\n빅토리아 왈라키아, 조숙한 네게 꼭 물어보고 싶군. 넌 진리를 뭐라고 생각하지?",
  ui_story_5084_50840700_75_dialog_content = "진리는... 지식이야.",
  ui_story_5084_50840700_76_dialog_content = "훗, 빅토리아 왈라키아. 우리는 같은 혈통을 지녔지만, 두뇌, 힘, 능력... 심지어 용모까지,\n그 무엇이든 내가 너보다 뛰어나다.",
  ui_story_5084_50840700_77_dialog_content = "그럼에도 불구하고, 이 반지가 네 것이라고 생각하는 이유는 무엇이냐.",
  ui_story_5084_50840700_78_dialog_content = "나야말로 진정한 왈라키아! 진리의 결사의 지도자다!",
  ui_story_5084_50840700_79_dialog_content = "넌... 우선 자신이 왈라키아의 이름에 걸맞은 자인지부터 힘써 증명해라.\n날 망신시키지 마라.",
  ui_story_5084_50840700_80_dialog_content = "(지금 이 빌헬름 씨는 너무 악독한 거 아냐? 저게 저 사람 진심인가?\n고작 어린애랑 경쟁하다니...)",
  ui_story_5084_50840700_81_dialog_content = "(뭐, 보통 「어린애」도 아니고 빅토리아 씨긴 하지만... 휴, 뭔가 이상해.\n우리가 계속 봤던 빌헬름 씨는 왠지 저런 사람은 아니었던 것 같은데...)",
  ui_story_5084_50840700_82_dialog_content = "<color=#e8d9bb>바깥에는 섬광이 번쩍이고 천둥소리가 울렸다.\n어린 빅토리아는 부모님의 관을 열고, 그 안으로 들어갔다.</color>",
  ui_story_5084_50840700_83_dialog_content = "아버지... 어머니...",
  ui_story_5084_50840700_84_dialog_content = "가르쳐 줘... 난 이제 어떻게 헤야 할까...?",
  ui_story_5084_50840700_85_dialog_content = "(집...? 내가 언제 돌아온 거지...?)",
  ui_story_5084_50840700_86_dialog_content = "<color=#e8d9bb>부스럭부스럭...</color>",
  ui_story_5084_50840700_87_dialog_content = "누가 왈라키아의 집에서 떠드는...",
  ui_story_5084_50840700_88_dialog_content = "...왜 당신이 여기 있어? 내 하인들은?",
  ui_story_5084_50840700_89_dialog_content = "전부 해고했다. 이제부터는 시간이 우리의 하인이다. 시간이라면 얼마든지 있으니 말이야.",
  ui_story_5084_50840700_90_dialog_content = "<color=#e8d9bb>빌헬름 왈라키아, 갑자기 빅토리아의 삶에 난입한 이 인물은\n이날부터 숙부의 신분으로 그녀를 늘 감독하게 되었다.</color>",
  ui_story_5084_50840700_91_dialog_content = "오, 가련한 빅토리아 양, 이런 감옥 안에서 살고 있다니, 참으로 마음이 아프군.\n하지만 우리도 어쩔 수가 없는 점을 부디 이해해 주게.",
  ui_story_5084_50840700_92_dialog_content = "빌헬름이 「가주」인 이상, 우리도 그자를 따를 수밖에 없다.\n늘 그대에게 접근하지 말라고 하니 말이야...",
  ui_story_5084_50840700_93_dialog_content = "오늘 멋대로 찾아온 건 그대의 건강이 염려되었기 때문이다...\n이렇게 확인했으니 이제 안심할 수 있겠군.",
  ui_story_5084_50840700_94_dialog_content = "그 사람은 그저 날 경계하고 있을 뿐이야.\n내가 당신들과 힘을 합쳐 자기 자리를 빼앗을까 두려운 거겠지.",
  ui_story_5084_50840700_95_dialog_content = "그렇다, 그자는 두려워하고 있다... 그대의 아버지는 그자를 능가하는 재능의 소유자였다.\n그리고 그자는 그저 과거의 이단일 뿐이지.",
  ui_story_5084_50840700_96_dialog_content = "빅토리아 양, 한 가지 확인하고 싶군. 그대도 그대의 아버지처럼 놀라운 힘을 지녔겠지...\n그렇다면 선조의 성배와도 공명할 수 있는 건가?",
  ui_story_5084_50840700_97_dialog_content = "그건 대체 어떤 감각이지?",
  ui_story_5084_50840700_98_dialog_content = "감각... 누군가가 뇌 속에 들어와서 한때 어떤 명주가 유행했는지 말해주는 느낌이야.",
  ui_story_5084_50840700_99_dialog_content = "담담하게 말해주는 이야기도 있는데, 마치...",
  ui_story_5084_50840700_100_dialog_content = "데이비드 포르피리오! 누가 이 빌헬름 왈라키아의 영지에 들어오는 것을 허락했지?",
  ui_story_5084_50840700_101_dialog_content = "허허, 빌헬름. 난 그저 빅토리아 양이 잘 지내는지 걱정이 됐을 뿐이다.\n지금 바로 가도록 하지.",
  ui_story_5084_50840700_102_dialog_content = "그녀는 잘 지내고 있다. 「신선한 피」에 그 어떤 괜한 기대라도 품지 않는 게 좋을 거다.",
  ui_story_5084_50840700_103_dialog_content = "하물며 네 기대에 따르도록 그녀에게 터무니없는 소리를 하는 일은 없도록 해라!",
  ui_story_5084_50840700_104_dialog_content = "내가 누구랑 이야기를 하든 당신 허락은 필요 없어.",
  ui_story_5084_50840700_105_dialog_content = "너무나도 순진하군.\n낡아빠진 책에만 빠져 있어서는 세상 물정도 모르는 아둔한 자가 될 뿐이다.",
  ui_story_5084_50840700_106_dialog_content = "선조의 무덤에 「핏빛 성전」이라는 책이 있는 것은 알고 있겠지.\n그 안에 기록된 계시는 네가 어떤 고서를 보아도 알 수 없는 것이다.",
  ui_story_5084_50840700_107_dialog_content = "부모님이 돌아가신 이후로 넌 선조의 무덤에 간 적이 없었지.",
  ui_story_5084_50840700_108_dialog_content = "뭐, 됐다. 진리의 결사를 싫어하는 건 상관없다만,\n적어도 네 개인적인 감정 외의 이유가 있어야 할 것이다.",
  ui_story_5084_50840700_109_dialog_content = "그렇지 않으면 그저 어린애의 투정이라고밖에 보이지 않을 테니 말이야.",
  ui_story_5084_50840700_110_dialog_content = "더는 누구의 통제도 받지 않기 위해, 나는 반드시 강해져야만 했다.",
  ui_story_5084_50840700_111_dialog_content = "그 후 나는 의식을 통해 고대 유물과 공명하며, 진리를 찾아다니기 시작했다...",
  ui_story_5084_50840700_112_dialog_content = "(어디 있을까? 「고대의 비밀」...)",
  ui_story_5084_50840700_113_dialog_content = "(진리의 주인께서 친히 내 꿈에 강림하셨어. 내가 없어진 걸 빌헬름이 알아채기 전에\n신의 비밀을 보여 주시려는 거야.)",
  ui_story_5084_50840700_114_dialog_content = "아아악!",
  ui_story_5084_50840700_115_dialog_content = "...<color=#FFB400>별</color>을... 놈이 <color=#FFB400>별</color>을 집어삼키고 있다... 시간이 없다... <color=#FFB400>재시작의 때</color>가 다가온다...",
  ui_story_5084_50840700_116_dialog_content = "<size=45>종결의 진정한 의미는 저 어둠 속에 있다──!</size>",
  ui_story_5084_50840700_117_dialog_content = "어리석은 녀석! 그 손에 쥔 건 뭐냐! 멋대로 고대의 유물과 공명하다니!",
  ui_story_5084_50840700_118_dialog_content = "지난날의 지혜여, 광인의 계시여, 빌헬름 왈라키아의 이름으로 명하노니, 그녀에게서 떨어져라!",
  ui_story_5084_50840700_119_dialog_content = "...앗!",
  ui_story_5084_50840700_120_dialog_content = "...돌아가서 푹 쉬어라.",
  ui_story_5084_50840700_121_dialog_content = "...당신이 날 구한 거야? 내가 여기 있는지는 어떻게 알았어...?",
  ui_story_5084_50840700_122_dialog_content = "유물의 특성을 분간하는 법을 배우는 것이 네 첫 수업이다.\n배우지 못한다면, 다음번엔 내가 네 시체를 거두게 될 거다.",
  ui_story_5084_50840700_123_dialog_content = "오해는 하지 마라. 진리의 결사의 지도자로서 난 내가 형의 딸을 해쳤다는 의심을\n받고 싶지 않을 뿐이다.",
  ui_story_5084_50840700_124_dialog_content = "그리고 널 남겨두는 건 내 지위를 지키는 데도 도움이 되고 말이야.",
  ui_story_5084_50840700_125_dialog_content = "게다가 피의 일족은 죽어가는 상대를 보면, 구하는 것보다는 비틀어 죽여\n신선한 피를 맛보는 걸 더 기뻐하기 마련이다.",
  ui_story_5084_50840700_126_dialog_content = "빌헬름 왈라키아... 당신...!",
  ui_story_5084_50840700_127_dialog_content = "교만하고, 오만하고, 가증스러운 빌헬름 왈라키아.\n그는 늘 기괴한 이유를 대며 멋대로 내 인생을 통제했다.",
  ui_story_5084_50840700_128_dialog_content = "하지만 그 얄미운 숙부 외의 다른 사람들이라고 더 나을 것도 없다.",
  ui_story_5084_50840700_129_dialog_content = "가주들은 전부 흉계를 품은 자들이고, 괴이하며 어리석다.\n그중에는 구더기처럼 무지해서, 마치 시체가 마을을 떠도는 듯한 가문도 있다.",
  ui_story_5084_50840700_130_dialog_content = "그들이 떠드는 아둔하며 사악한 사상은 진리를 찾는 신자들에게 그 어떤 도움도 되지 않는다.\n그런 자들은 길을 잃은 양들을 구할 수 없다.",
  ui_story_5084_50840700_131_dialog_content = "반드시 신중하게 경계해야 한다... 진리의 결사의 그 어떤 관습에도 물들지 않도록.",
  ui_story_5084_50840700_132_dialog_content = "진리의 주인의 계시를 듣고, 내가 본 「종결」을 해결하기 위해.",
  ui_story_5084_50840700_133_dialog_content = "요즘은 계속 집에 틀어박혀 있군. 고대의 유물에 대한 흥미가 가신 거냐?",
  ui_story_5084_50840700_134_dialog_content = "네 아버지나 나는 네 나이 때 이미 혈통을 각성해서 진리의 길에\n충만한 호기심을 품고 있었지.",
  ui_story_5084_50840700_135_dialog_content = "아니면 네가 여전히 무지해서, 「진리란 무엇인지」에 대한 답을 내놓지 못하고 있는 건가?",
  ui_story_5084_50840700_136_dialog_content = "...여행을 떠나기로 결정했어. 진리의 발자취를 찾으러.",
  ui_story_5084_50840700_137_dialog_content = "좋다, 마음대로 해라.",
  ui_story_5084_50840700_138_dialog_content = "그리고 나는 내 진리의 계시를 찾는 여행을 떠났다.",
  ui_story_5084_50840700_139_dialog_content = "집을 나온 뒤로, 나는 세상을 더 깊이 이해하기 시작했다.",
  ui_story_5084_50840700_140_dialog_content = "진리에 대한 깨달음과 함께, 내 혈통도 비로소 각성을 시작했다...\n하지만 나는 여전히 진리의 결사에 들어가지 않겠다고 자신을 타이르고 있었다.",
  ui_story_5084_50840700_141_dialog_content = "다만 내가 깨달음을 얻고 그에게 답을 찾았다고 전하려 했을 때,\n그는 이미 나의 대답에 기대를 잃은 뒤였다.",
  ui_story_5084_50840700_142_dialog_content = "돌아왔네... 당신 이번엔 석 달이나 나가 있었어. 어떻게 된 거야?",
  ui_story_5084_50840700_143_dialog_content = "...너와는 무관한 일이다.",
  ui_story_5084_50840700_144_dialog_content = "그 눈빛은 뭐야...? 원한, 알 수 없는 감정...",
  ui_story_5084_50840700_145_dialog_content = "빌헬름 왈라키아, 밖에서 무슨 일이 있었던 거지?",
  ui_story_5084_50840700_146_dialog_content = "누가 내 방에 들어와도 된다고 했나.",
  ui_story_5084_50840700_147_dialog_content = "당신은 진리의 결사의 지도자야. 그런데도 일은 제쳐두고 밖으로만 나가고...\n게다가 집에 있는 시간도 갈수록 줄어들고 있잖아.",
  ui_story_5084_50840700_148_dialog_content = "몇 번이나 말했을 텐데, 너와는 무관하다. 지금 당장 나가라.",
  ui_story_5084_50840700_149_dialog_content = "그래, 당신은 늘 그렇게 나와의 대화를 거부했지. 하지만 오늘 밤은 성명제 날이야.\n난 대화를 한다면 오늘이 마지막 기회라고 생각했는데.",
  ui_story_5084_50840700_150_dialog_content = "진리에 대해서, 그리고 우리에 대해서...",
  ui_story_5084_50840700_151_dialog_content = "꺼져! 당장 내 앞에서 꺼지란 말이다!",
  ui_story_5084_50840700_152_dialog_content = "......",
  ui_story_5084_50840700_153_dialog_content = "결국 나는 끝까지 그를 이해할 수 없었다.",
  ui_story_5084_50840700_154_dialog_content = "어쩌면 나는 이미 그 「마지막 기회」를 놓쳤을지도 모른다.",
  ui_story_5084_50840700_155_dialog_content = "교만하고, 오만하며, 가증스러운 빌헬름 왈라키아.\n내가 이해할 수 없는 사람, 나의 마지막 가족, 당신은 지금 또 어디로 간 거지?",
  ui_story_5084_50840700_156_dialog_content = "(기억 속 두 사람은 서로를 이런 식으로 대하고 있었다니...)",
  ui_story_5084_50840700_157_dialog_content = "(그래도 빌헬름 씨 쪽은 분명히 계속 빅토리아 씨를 지키려고 했어...)",
  ui_story_5084_50840700_158_dialog_content = "(혼자서 정신의 고통을 견뎠고, 가주들과 함께 신도들의 피를 마시지도 않았고...\n마지막엔 남을 위하면서 나일즈를 구했어...)",
  ui_story_5084_50840700_159_dialog_content = "(저 오해는... 그 오랜 시간 동안 이어져 왔어... 빌헬름 씨가 살해될 때까지...)",
  ui_story_5084_50840700_160_dialog_content = "(빅토리아 씨는 그걸 볼 수 있을까...?)",
  ui_story_5084_50840801_1_dialog_content = "촛불이 또 깜빡이네... 우리가 또 어느 시간대로 보내진 걸까?",
  ui_story_5084_50840801_2_dialog_content = "저건 빅토리아 씨랑... 다른 가주들이잖아? 왜 모여 있는 거지?",
  ui_story_5084_50840801_3_dialog_content = "어? 빅토리아 님 옆에... 파우스트 씨 아냐? 왠지 이쪽을 본 것 같은데?",
  ui_story_5084_50840801_4_dialog_content = "설마...",
  ui_story_5084_50840801_5_option_content = "[감응한다]",
  ui_story_5084_50840801_6_dialog_content = "파우스트, 내 목소리 들려?",
  ui_story_5084_50840801_7_dialog_content = "물론이지. 그리고 지금 네가 느낄 의문도 알고 있어.",
  ui_story_5084_50840801_8_dialog_content = "지금 여기 계신 빅토리아 님은 네가 잘 아는 그분이 맞아.",
  ui_story_5084_50840801_9_dialog_content = "우리랑 같이 시공을 넘어온 빅토리아 씨인 거구나... 근데 왜 또 저 사람들이랑...",
  ui_story_5084_50840801_10_dialog_content = "빌헬름이 실종된 지 벌써 3년이 지났다. 왈라키아 가문의 후예는 이제\n아브라함과 빌헬름의 조카 빅토리아뿐이지...",
  ui_story_5084_50840801_11_dialog_content = "(3년이라면... 빌헬름 씨가 살해당한 게 1915년이니까,\n지금은 1918년이 되는 건가?)",
  ui_story_5084_50840801_12_dialog_content = "클라비스 아브라함은 자기 자식이 진리의 결사에 가입하는 것을 원하지 않았으니,\n이곳에 그의 자리가 없는 건 당연한 이치다.",
  ui_story_5084_50840801_13_dialog_content = "지금 지도자 자리는 공석이고, 우린 빌헬름과 함께 사라진 가주의 반지를 찾지 못했다.",
  ui_story_5084_50840801_14_dialog_content = "따라서, 빅토리아, 너도 이제 더는 선조들의 지혜를 계승할 기회가 없게 되었다...",
  ui_story_5084_50840801_15_dialog_content = "호오? 이 많은 가주들을 불러 놓아놓고, 하려는 이야기가 고작 그거였어?",
  ui_story_5084_50840801_16_dialog_content = "네가 밖을 여행하며 진리를 찾아다니는 걸 좋아한다고 하던데, 계속 그렇게 하는 게 어떤가.",
  ui_story_5084_50840801_17_dialog_content = "이곳을 떠나도 좋고, 포르피리오 가문의 일원으로 들어와도 좋다.\n어차피 넌 지도자가 될 자격을 잃었으니 말이야.",
  ui_story_5084_50840801_18_dialog_content = "오늘은 성명제다. 진리의 결사의 지도자 자리는...",
  ui_story_5084_50840801_19_dialog_content = "빌헬름이 사라진 몇 년 동안, 너흰 줄곧 이렇게 고요하고 케케묵어\n구역질 나는 회의를 해 온 걸까?",
  ui_story_5084_50840801_20_dialog_content = "마셔선 안 되는 피를 마셨다면, 피의 일족이라 해도 막대한 대가를 치르게 될 거야.",
  ui_story_5084_50840801_21_dialog_content = "<color=#e8d9bb>빅토리아는 손 옆에 놓인 잔 속의 붉은 액체를 탁자 위로 쏟아 버렸고,\n잔 바닥에서는 빌헬름이 한때 차고 있던 반지가 모습을 드러냈다.</color>",
  ui_story_5084_50840801_22_dialog_content = "......?",
  ui_story_5084_50840801_23_dialog_content = "...빌헬름의 반지...",
  ui_story_5084_50840801_24_dialog_content = "빌헬름은 떠나기 전 진작에 이 반지를 내게 맡겼고,\n선조들의 말씀은 이미 익숙할 정도로 들었어.",
  ui_story_5084_50840801_25_dialog_content = "이 진리의 결사의 지도자 자리에 대해 더 할 말이 있을까?",
  ui_story_5084_50840801_26_dialog_content = "...말도 안 돼!",
  ui_story_5084_50840801_27_dialog_content = "계획을 바꿔야겠군...",
  ui_story_5084_50840801_28_dialog_content = "계획이라, 너희 가주들은 모두 어떤 계획에 참여한 모양이네.",
  ui_story_5084_50840801_29_dialog_content = "이건 3년 전 성명제에서 내가 자신을 희생해서 얻은 계시야.",
  ui_story_5084_50840801_30_dialog_content = "3년 전의 제물이...",
  ui_story_5084_50840801_31_dialog_content = "아니, 절대 불가능해!",
  ui_story_5084_50840801_32_dialog_content = "아직도 남을 믿는 거냐? 데이비드! 네놈의 죽음이 다가왔다! 더는 희망을 바라지 마라!",
  ui_story_5084_50840801_33_dialog_content = "우리의 거래를 생각해라...",
  ui_story_5084_50840801_34_dialog_content = "......",
  ui_story_5084_50840801_35_dialog_content = "<size=45>악──!</size>",
  ui_story_5084_50840801_36_dialog_content = "오오, 가련한 빌헬름, 인정받지 못한 빌헬름이여, 이렇게 자기 고향에서 죽음을 맞이하다니.",
  ui_story_5084_50840801_37_dialog_content = "......",
  ui_story_5084_50840801_38_dialog_content = "계승 받을 후예가 없다면, 왈라키아의 반지는 후대에 계속 전해진들 아무 의미도 없겠지.",
  ui_story_5084_50840801_39_dialog_content = "이게 무슨 짓이냐! 반지를 부수면 앞으론...",
  ui_story_5084_50840801_40_dialog_content = "반지는 우리에겐 아무 쓸모도 없다. 이 가루라도 빌헬름의 시체와 함께 영면하게 해 주자고.",
  ui_story_5084_50840801_41_dialog_content = "앞으로는 우리 모두 다시는 마음 졸일 필요가 없겠군.",
  ui_story_5084_50840801_42_dialog_content = "왈라키아 대가주라는 족쇄도 이로써 과거가 된 것이다!",
  ui_story_5084_50840801_43_dialog_content = "그 반지는... 분명 빌헬름과 함께...",
  ui_story_5084_50840801_44_dialog_content = "...전부 알게 된 것이냐.",
  ui_story_5084_50840801_45_dialog_content = "호오? 내가 알면 안 되는 일이라도 있는 건가?",
  ui_story_5084_50840801_46_dialog_content = "...정말로 반지를 착용했나? 계시를 받았냔 말이다.",
  ui_story_5084_50840801_47_dialog_content = "선조들의 인정을 받지 못했다면, 계승을 운운할 자격은 없다!",
  ui_story_5084_50840801_48_dialog_content = "선조들께서 내게 왈라키아라는 이름을 내리시고, 잃어버린 반지를 「되찾게」 해 주신 게\n바로 인정의 증거야. 이제 그걸 직접 보여줄게.",
  ui_story_5084_50840801_49_dialog_content = "PlayerName! 저 반지가 빅토리아 님이 이성을 잃게 만들 수도 있는 거지?!",
  ui_story_5084_50840801_50_dialog_content = "...내가 뭘 해야 할지 알겠어, 메이!\n그리고 내가 왜 여기 있는 건지도 이제 알 것 같아.",
  ui_story_5084_50840801_51_option_content = "(감응 연결──)",
  ui_story_5084_50840801_52_dialog_content = "으윽... 또 시작인가...",
  ui_story_5084_50840801_53_dialog_content = "저 속삭임들... 옛 계시들...",
  ui_story_5084_50840801_54_dialog_content = "괜찮아, 빅토리아 씨. 내가 막아줄게!",
  ui_story_5084_50840801_55_dialog_content = "아이테르?! ....그래, 그런 거였어. 이게 바로 진리의 주인의 계획이셨구나...\n그럼 부탁할게.",
  ui_story_5084_50840801_56_dialog_content = "반지를 꼈어... 진짜로 반지를 꼈다고...",
  ui_story_5084_50840801_57_dialog_content = "다들 뭘 걱정한 거지? 진정한 왈라키아가 선조들의 말씀을 감당하지 못할 리가 없잖아?",
  ui_story_5084_50840801_58_dialog_content = "후훗.... 아하하하하하!",
  ui_story_5084_50840801_59_dialog_content = "저 웃음...",
  ui_story_5084_50840801_60_dialog_content = "목도하라! 이제 나 빌헬름 왈라키아가 어둠으로 너희를 감싸 주리라.",
  ui_story_5084_50840801_61_dialog_content = "나는 이미 선조들의 인정을 받은 왈라키아의 새 가주다!",
  ui_story_5084_50840801_62_dialog_content = "왈라키아...!",
  ui_story_5084_50840801_63_dialog_content = "목도하라, 왈라키아의 계승자를!",
  ui_story_5084_50840802_1_dialog_content = "그렇다면 내가 너희를 정화해 주마!",
  ui_story_5084_50840802_2_dialog_content = "어떻게 된 거야? 이 광경...",
  ui_story_5084_50840802_3_dialog_content = "나도 최대한 억제해 봤는데, 이 장면들은 반지에서 계속해서 전해지고 있어.",
  ui_story_5084_50840802_4_dialog_content = "이건 「타인」의 의지와 관계없는... 뭔가 더 높은 차원의 「잡음」 같아.",
  ui_story_5084_50840802_5_dialog_content = "악의는 없는 것 같으니까, 계속 보게 해 줘.",
  ui_story_5084_50840802_6_dialog_content = "<size=45>악──!</size>",
  ui_story_5084_50840802_7_dialog_content = "네 피를 내놓아라! 그 「자격」은 내가 가지겠다!",
  ui_story_5084_50840802_8_dialog_content = "빌헬름 왈라키아, 내가 선조들의 계시를 열도록 도울 <color=#FFB400>열쇠</color>는 바로 너다! 흐하하하하!",
  ui_story_5084_50840802_9_dialog_content = "빌헬름 왈라키아...!",
  ui_story_5084_50840802_10_dialog_content = "빌헬름, 편지에는 네가 마을을 떠나겠다고 해서,\n난 네가 빅토리아와 정착할 곳을 찾은 줄 알았다...",
  ui_story_5084_50840802_11_dialog_content = "어리석은 놈... 어째서 다시 이곳으로 돌아온 거냐... 하하...",
  ui_story_5084_50840802_12_dialog_content = "하하... <color=#FFB400>저놈</color>의 말을 곧이곧대로 믿은 나도 똑같이 어리석은 놈이겠지.",
  ui_story_5084_50840802_13_dialog_content = "선조들이시여, 부디 빌헬름 왈라키아를 받아 주소서.\n오직 그 핏속에 흐르는 야심만이 불순물이었을 뿐, 그는 왈라키아의 명예를 저버리지 않았습니다.",
  ui_story_5084_50840802_14_dialog_content = "이제 빌헬름은 저라는 죄인에게 배신당했으니, 그의 죄를 씻어 주시고,\n제가 그를 대신하여 모든 것을 짊어지게 하소서.",
  ui_story_5084_50840802_15_dialog_content = "제 영혼이 모든 저주를 받고 나면, 부디 카론과 제 아내는 무사히 이 땅을\n벗어날 수 있길 바랍니다.",
  ui_story_5084_50840802_16_dialog_content = "빌헬름 왈라키아, 한때 나의 절친한 벗이여, 부디 이 관에서 안식을 얻기를...",
  ui_story_5084_50840802_17_dialog_content = "...정말 죽은 거야? 빌헬름 왈라키아... 그 사람이 이미 죽었다고...?",
  ui_story_5084_50840802_18_dialog_content = "이게 바로 반지가 나한테 알려 주려 한 진실이야?",
  ui_story_5084_50840802_19_dialog_content = "3년 전 내게 반지를 줬던 그 사람이... 이미 죽었단 말이야...?",
  ui_story_5084_50840802_20_dialog_content = "...이제 어떻게 할 거야?",
  ui_story_5084_50840802_21_dialog_content = "점점 진상에 가까워지고 있다는 느낌이 들어.",
  ui_story_5084_50840802_22_dialog_content = "난 진리의 주인께서 나를 여기로 이끄신 건, 이미 진리의 결사의 지도자가 된 내가\n두 눈에 담아야 할 순간이 있어서라고 생각했어.",
  ui_story_5084_50840802_23_dialog_content = "하지만 제물이 되고, 네가 합류하면서 깨달았어.\n주의 은총, 그리고 떼어낼 수 없는 증오를 품은 채로, 난 이 모든 것에 개입해야 해.",
  ui_story_5084_50840802_24_dialog_content = "이건 오직 힘과 이성을 충분히 갖춘 나만이 완수할 수 있는 일이니까.",
  ui_story_5084_50840802_25_dialog_content = "제 의문을 풀어 주시고, 복수의 기쁨을 주신 진리의 주인께 감사드립니다.",
  ui_story_5084_50840802_26_dialog_content = "오늘 밤은 성명제야. 우리의 원한은 선조께 계시를 구하면서부터 시작됐어.\n그럼 선조들이 지켜보시는 가운데 끝맺도록 하자.",
  ui_story_5084_50840802_27_dialog_content = "다들 오래 기다렸어.",
  ui_story_5084_50840802_28_dialog_content = "난 이미 진리의 주인께 계시를 받았고, 나의 사명을 알게 됐어.",
  ui_story_5084_50840802_29_dialog_content = "그 반지를 끼고 아무 고통도 못 느꼈니?",
  ui_story_5084_50840802_30_dialog_content = "빌헬름이 그 반지를 낄 땐 그렇게 가뿐해 보이진 않았거든.",
  ui_story_5084_50840802_31_dialog_content = "빅토리아, 어떤 계시를 받았지?",
  ui_story_5084_50840802_32_dialog_content = "<color=#e8d9bb>빅토리아는 자리에서 일어나 긴 탁자의 상석으로 걸어갔다.</color>",
  ui_story_5084_50840802_33_dialog_content = "<color=#FF0000>파벌을 숙청하라.</color>",
  ui_story_5084_50840802_34_dialog_content = "뭐라고?!",
  ui_story_5084_50840802_35_dialog_content = "<color=#e8d9bb>검은 바람이 불어와 문과 창문이 요란하게 흔들렸고,\n시대를 초월한 힘을 다루는 계승자는 가주들에게 최후통첩을 보내듯 말했다.</color>",
  ui_story_5084_50840802_36_dialog_content = "<color=#e8d9bb>쨍그랑──</color>",
  ui_story_5084_50840802_37_dialog_content = "살무사 가주님, 잔을 떨어트리시다니, 뭘 그리 놀라셨습니까.\n그래서야 너무 품위가 없지 않겠습니까?",
  ui_story_5084_50840802_38_dialog_content = "......",
  ui_story_5084_50840802_39_dialog_content = "그 반지가... 대체 네게 뭘 보여 준 거냐!",
  ui_story_5084_50840802_40_dialog_content = "데이비드! 여긴 진리의 전당이야.",
  ui_story_5084_50840802_41_dialog_content = "......!",
  ui_story_5084_50840802_42_dialog_content = "모든 것은 선조들의 축일에서 시작되었으니, 오늘 밤 같은 날에 끝내야겠지.",
  ui_story_5084_50840802_43_dialog_content = "왈라키아의 새 가주로서, 난 오늘 밤 성명제의 준비를 시작해야겠어.",
  ui_story_5084_50840802_44_dialog_content = "자── 핏빛 달이 뜨고, 교회에서 종소리가 울릴 때,\n우린 다시 모여 기나긴 밤을 마치는 거야.",
  ui_story_5084_50840900_1_dialog_content = "<color=#e8d9bb>어두운 밤의 등불 아래, 데이비드는 피 웅덩이에 몸을 담그고 있었다.\n같은 방 안에는 그의 광신도들, 그리고 고문으로 처참한 몰골이 된 클라비스가 있었다.</color>",
  ui_story_5084_50840900_2_dialog_content = "...대체 빌헬름은 죽은 게 맞는 거냐?!",
  ui_story_5084_50840900_3_dialog_content = "어서... 말해라!",
  ui_story_5084_50840900_4_dialog_content = "계속... 날 고문해 봐야 소용없다. 내가 아는 건 이미 다 이야기했다...",
  ui_story_5084_50840900_5_dialog_content = "내 손으로 직접 빌헬름을 관에 넣었고, 그가 죽은 것을 확인했다...",
  ui_story_5084_50840900_6_dialog_content = "3년 전 성명제 때, 빌헬름은 빅토리아를 관에서 내보냈다.",
  ui_story_5084_50840900_7_dialog_content = "우린 참지 못하고 마침내 그를 없애기로 결정했고, 우릴 속박하는 그 반지도 없애고자 했지.",
  ui_story_5084_50840900_8_dialog_content = "헌데 어째서 3년이 지난 지금, 빅토리아가 그 반지를 가지고 돌아올 수 있다는 거냐.",
  ui_story_5084_50840900_9_dialog_content = "그 숙부와 조카가 대체 무슨 짓을 꾸민 거냔 말이다.",
  ui_story_5084_50840900_10_dialog_content = "이 성전엔 아무 내용도 적혀 있지 않아. 당신이 기대하는 「성언」 같은 건 하나도 없다고.",
  ui_story_5084_50840900_11_dialog_content = "그나저나 그 왈라키아 아가씨는 자기 아버지랑 꽤 닮았던데?",
  ui_story_5084_50840900_12_dialog_content = "흐흐흐... 흐하하하하!",
  ui_story_5084_50840900_13_dialog_content = "뭘 웃어?",
  ui_story_5084_50840900_14_dialog_content = "우리도 참 우습게 됐군. 그때 빌헬름의 허세에 겁을 집어먹고 우물쭈물하는 바람에,\n지금처럼 선택의 여지가 없는 지경에 몰려 버렸으니 말이야.",
  ui_story_5084_50840900_15_dialog_content = "두 늙은이가 죽었을 때, 빅토리아와 빌헬름도 한꺼번에 없앴어야 했다.",
  ui_story_5084_50840900_16_dialog_content = "그땐 빅토리아도 각성 전이었고, 지금처럼 성가시진 않았을 거다.",
  ui_story_5084_50840900_17_dialog_content = "데이비드, 우린 왈라키아에 너무 오랫동안 복종해 왔고, 그래서 잊어버렸는지도 모른다...\n「진리」란 결국 밖에서 흘러온 쓸모없는 불순물이란 사실을 말이다.",
  ui_story_5084_50840900_18_dialog_content = "그래, 피를 가까이하고, 핏속에서 힘을 얻는 것이야말로 우리 혈족의 생존 방식이다!",
  ui_story_5084_50840900_19_dialog_content = "모자란 힘만 가지고 그저 「단언」과 「반복」, 「폐쇄」와 「욕망」을 통해\n<color=#FFB400>진리의 주인</color>을 향한 믿음을 설파하는 건, 애초부터 삿된 방식일 뿐이었다!",
  ui_story_5084_50840900_20_dialog_content = "이미 늦었다... 빅토리아는 반지의 힘을 얻었고, 우리를 모조리 없앨 준비를 마쳤다.",
  ui_story_5084_50840900_21_dialog_content = "반나절도 남지 않은 지금, 아무리 준비해 봤자 우린...",
  ui_story_5084_50840900_22_dialog_content = "닥쳐라! 그때 빌헬름도 그 빌어먹을 반지를 끼고 있었지만,\n결국 내가 놈의 피를 모조리 마셨다!",
  ui_story_5084_50840900_23_dialog_content = "흥, 빌헬름은 인정받은 자가 아니었고, 그래서 놈의 피를 마시고도\n난 성전과 계약할 수 없었다.",
  ui_story_5084_50840900_24_dialog_content = "그나마 끝없이 늘어나는 신도들 덕에 난 계속해서 힘을 보충할 수 있었고...\n이젠 마침내 희미하게나마 성전의 부름을 들을 수 있게 되었다!",
  ui_story_5084_50840900_25_dialog_content = "조금만 더... 이제 조금만 더 하면 나도 성전에서 계시를 드러낼 수 있을 것이다.",
  ui_story_5084_50840900_26_dialog_content = "모든 것은 우리가 그 어떤 우월함도 누리지 못하도록 왈라키아가 우리의 혈통을 억압한 탓이다.",
  ui_story_5084_50840900_27_dialog_content = "우리는 피를 마시는 본성을 지녔지만, 저들은 우리의 본성에 목줄을 채웠다...\n이제 보니 놈들은 그저 우리의 힘이 두려워서 그랬던 것이겠지.",
  ui_story_5084_50840900_28_dialog_content = "또 무슨 짓을 하려는 거냐...",
  ui_story_5084_50840900_29_dialog_content = "계획대로... 오늘 밤 나는 반드시 의식 현장에 나갈 것이다.\n내가 의식을 주도해 모든 신도들에게 성전이 날 인정했음을 보여줄 것이다.",
  ui_story_5084_50840900_30_dialog_content = "조력자도 없는 빅토리아 때문에 내 입지가 흔들릴 일은 없다.",
  ui_story_5084_50840900_31_dialog_content = "그 숙질에게 믿을 거라곤 이제 그 무덤뿐이다.\n덩굴인간은 늘 겁이 많았으니, 금꾼, 살무사, 그리고 물귀신, 너희에게 맡기겠다.",
  ui_story_5084_50840900_32_dialog_content = "알겠다.",
  ui_story_5084_50840900_33_dialog_content = "빌헬름도 죽인 내가 빅토리아라고 못 죽일 것 같나?",
  ui_story_5084_50840900_34_dialog_content = "지금 내게 필요한 것은 힘의 보충이다.\n오늘 밤, 빅토리아가 무슨 재미있는 수작을 보여 줄지 똑똑히 봐 주마.",
  ui_story_5084_50840900_35_dialog_content = "으윽... 데이비드...",
  ui_story_5084_50840900_36_dialog_content = "...설명하자면 그래. 우린 여러 번 시공을 뛰어넘었고,\n순간적으로 우리가 어느 시간에 있는 건지도 모르게 됐어.",
  ui_story_5084_50840900_37_dialog_content = "계시는 비록 심오하지만, 그 안배에는 모두 뜻이 있는 법이야.",
  ui_story_5084_50840900_38_dialog_content = "우리가 있는 「현재」의 3년 전인 1915년, 난 성명제에서 빌헬름과 만났고,\n그의 계획대로 관에 들어갔어.",
  ui_story_5084_50840900_39_dialog_content = "그때, 난 빌헬름이 손에 낀 이 반지를 좌우로 돌리고 있는 걸 봤어.\n난 그게 기억 속의 그라면 절대 하지 않았던 행동이란 걸 눈치챘고...",
  ui_story_5084_50840900_40_dialog_content = "그 사람은 내게 뭔가 전하고 싶었던 거야. 그래서 난 그 의식에 참여했어.",
  ui_story_5084_50840900_41_dialog_content = "하지만 깨어났을 때 난 이미 「현재」에 와 있었어.",
  ui_story_5084_50840900_42_dialog_content = "난 3년이란 시간을 뛰어넘어, 집에 있는 침대 위에서 눈을 떴어.\n손에는 우리 가문에 대대로 전해져 내려오는 이 반지뿐이었지.",
  ui_story_5084_50840900_43_dialog_content = "빌헬름이 그 의식 마지막에 내게 건네줬던 거야.",
  ui_story_5084_50840900_44_dialog_content = "전 눈을 떴을 때 그 대저택에 있었고, 때마침 누군가가 제게\n빅토리아 님께 편지를 한 통 전해달라고 하더군요.",
  ui_story_5084_50840900_45_dialog_content = "그 사람이 떠난 후, 이곳이 어딘지 생각하고 있을 때,\n빅토리아 님이 방문을 열고 나오셨지요.",
  ui_story_5084_50840900_46_dialog_content = "편지 속엔 내게 성명제 전 가주 회의에 참석하라는 내용이 적혀 있었지만,\n가주들은 내 등장을 전혀 예상하지 못했다는 반응이었어.",
  ui_story_5084_50840900_47_dialog_content = "이 편지를 보낸 사람은 내가 이곳에 있는 걸 알고, 그게 「나」라는 것도 알았어.\n다시 말해서 이 시대의 「빅토리아」가 아니란 걸 알고 있던 거야.",
  ui_story_5084_50840900_48_dialog_content = "참, 빅토리아 님... 저희는 나일즈 씨도 만났는데, 왠지... 좀 이상했어요...",
  ui_story_5084_50840900_49_dialog_content = "나일즈 씨는 자길 전혀 못 알아보는 빌헬름 씨한테 인사를 했거든요.\n「절 이곳에 초대해 주셔서 감사합니다」라고 말이에요.",
  ui_story_5084_50840900_50_dialog_content = "이 모든 걸 계획한 사람은 3년 전 성명제 때의 빌헬름 씨인 걸까?",
  ui_story_5084_50840900_51_dialog_content = "우리가 본 시간대의 빌헬름은 이미 숨을 거둔 뒤였지만, 과거엔 여전히 살아 있었어.",
  ui_story_5084_50840900_52_dialog_content = "3년 전 성명제 때 빌헬름이 분명히 뭔가를 했을 거야.\n하지만 지금 여기 있는 우리로선 아직 알 방법이 없어.",
  ui_story_5084_50840900_53_dialog_content = "다만 우리가 점점 더 진상에 가까워지고 있다는 건 느낄 수 있어..",
  ui_story_5084_50840900_54_dialog_content = "빅토리아 님, 줄곧 의문인 점이 하나 있습니다.\n「현재」가 1918년의 성명제라면, 당시 빅토리아 님께선 어떤 일을 겪으신 겁니까?",
  ui_story_5084_50840900_55_dialog_content = "내가 기억하는 1918년의 난... 아직 마을 밖을 여행하는 중이었고,\n가주 회의에 참석하지 않았어.",
  ui_story_5084_50840900_56_dialog_content = "그해 성명제 당일엔 소용돌이 마을에 머물고 있었어.\n그러다 밤중에 갑자기 여기로 돌아와서 성전을 손에 넣으라는 하늘의 계시를 받았지.",
  ui_story_5084_50840900_57_dialog_content = "그리고 눈을 떴을 때, 난 손에는 성전을 쥔 채 왈라키아의 무덤 속 <color=#FFB400>관</color> 안에 누워 있었어.",
  ui_story_5084_50840900_58_dialog_content = "성전은 뜻밖에도 계시를 보였고, 이 소용돌이 마을을 인정했어.\n그리고 날 진리의 결사의 지도자로 추대했지.",
  ui_story_5084_50840900_59_dialog_content = "이게 바로 우리가 출발하기 전, 내가 이 반지를 만졌을 때 보게 된 나 자신의 기억이야.",
  ui_story_5084_50840900_60_dialog_content = "왈라키아의 무덤 속 <color=#FFB400>관</color>이라고 하셨습니까? 하지만 어째서 <color=#FFB400>관</color>이었던 것일까요?",
  ui_story_5084_50840900_61_dialog_content = "어쩌면... 나도 관에서 잠을 자는 습관이 있어서 그런 걸지도 모르겠네.",
  ui_story_5084_50840900_62_dialog_content = "(맞아... 부모님의 관... 그리고 빌헬름 씨의 관에서...)",
  ui_story_5084_50840900_63_dialog_content = "설마 왈라키아 가문의 관에는 저희가 모르는 힘이 숨겨져 있는 것입니까?",
  ui_story_5084_50840900_64_dialog_content = "다른 시공으로 이동하는 힘 같은 거?",
  ui_story_5084_50840900_65_dialog_content = "아이테르가 들고 있는 촛대도 타오르고 꺼질 때 너흴 다른 곳으로 데려가고 있잖니.",
  ui_story_5084_50840900_66_dialog_content = "게다가 3년 전 성명제 때 빌헬름 씨가 무덤 문을 열 수 있게 해 준 것도 이 촛대야...",
  ui_story_5084_50840900_67_dialog_content = "스칼렛 언니가 지키는 무덤엔... 대체 보물이 얼마나 많은 거야?!",
  ui_story_5084_50840900_68_dialog_content = "스칼렛의 일족은 무덤을 지키며 줄곧 빅토리아 님이 그 안을 보는 것을 허락하지 않았습니다.",
  ui_story_5084_50840900_69_dialog_content = "매번 때가 되지 않았다고만 하더니... 그 「때」라는 게 어째서 지금인 것일까요?",
  ui_story_5084_50840900_70_dialog_content = "빌헬름 숙부의 실종, 그리고 그의 죽음, 그 배후에는 다른 깊은 뜻이 숨겨져 있을 거야.",
  ui_story_5084_50840900_71_dialog_content = "마치 오늘의 「위기」를 미리 보고, 우리가 함께 「이 안」으로 들어오길 기다렸던 것 같아.",
  ui_story_5084_50840900_72_dialog_content = "그는 전에 내게 진리가 뭐냐고 물었었지. 난 그 해답을 찾으려 애썼지만,\n지금 생각해 보면 내가 「정답」을 말하는 걸 기다린 건 아니었을 거야.",
  ui_story_5084_50840900_73_dialog_content = "왜냐하면 진리엔 영원히 답이 없으니까.",
  ui_story_5084_50840900_74_dialog_content = "오직 끝없이 회답하는 굳은 신념뿐이지.",
  ui_story_5084_50840900_75_dialog_content = "난 이제 그 회답이 지닌 힘을 알고 있어.\n그래서 아무 두려움 없이 저 「가주」들을 없애기로 결정했어.",
  ui_story_5084_50840900_76_dialog_content = "다만 개인적으로는, 3년 전 빌헬름이 나와 대화를 나누고,\n내가 찾는 것을 이해해 주었더라면...",
  ui_story_5084_50840900_77_dialog_content = "(...결국 두 사람 다 그냥 고집이 센 거였잖아. 이렇게 긴 시간을 뛰어넘고도\n여전히 서로 화해할 수 없는 걸까...?)",
  ui_story_5084_50840900_78_dialog_content = "어쨌든 이번엔 반드시... 이 반지가 내 손으로 되돌아온 이유를 확인하고 말겠어...",
  ui_story_5084_50840900_79_dialog_content = "(여기까지 달려오면서... 나도 그 확실한 답이 알고 싶어졌어...)",
  ui_story_5084_50840900_80_dialog_content = "(내가 본 빌헬름 씨랑, 빅토리아 씨의 기억 속 빌헬름 씨가 다른 이유는 뭐지?\n내가 본 빌헬름 씨는 빅토리아 씨한테 그렇게나 헌신적이었잖아.)",
  ui_story_5084_50840900_81_dialog_content = "(이제 얼마 안 남았어... 안개 속에 감춰진 그 열쇠만 찾으면,\n빅토리아 씨도 그 답을 말할 기회가 생길지도 몰라...)",
  ui_story_5084_50840900_82_dialog_content = "(촛대... 넌 매번 내가 의문을 풀 방향을 가르쳐 줬는데,\n왜 이번엔 꿈쩍도 안 하는 거야?)",
  ui_story_5084_50840900_83_dialog_content = "(휴... 진리의 결사 멤버들의 집념이 대체 어디서 오는 건지,\n드디어 이해하게 된 것 같아...)",
  ui_story_5084_50840900_84_dialog_content = "밤의 장막이 내려왔어. 성명제의 의식이 곧 시작될 거야.\n우리에게 주어진 시간도 이제 얼마 남지 않았어.",
  ui_story_5084_50840900_85_dialog_content = "시간... 그렇네, 내 양초도 이제 3분의 1밖에 안 남았어.",
  ui_story_5084_50840900_86_dialog_content = "걱정하지 마. 난 이미 뭘 해야 할지 알고 있으니까.",
  ui_story_5084_50840900_87_dialog_content = "가주 회의에서 내가 한 위협은 그저 저들이 힘을 더 갈망하게 만들 뿐이야.\n저들은 수단과 방법을 가리지 않고 나와 맞서려 하겠지.",
  ui_story_5084_50840900_88_dialog_content = "만약 다들 도망쳐 버렸으면? 빅토리아 씨 그때 엄청 무서웠거든.",
  ui_story_5084_50840900_89_dialog_content = "데이비드는 도망치지 않을 거야. 그자는 야심으로 가득하거든.\n자기가 원하는 바를 이루지 못하면 절대 단념하지 않을 거야.",
  ui_story_5084_50840900_90_dialog_content = "그리고 데이비드는 이미 「지금」의 핏빛 성전을 가지고 있겠지.",
  ui_story_5084_50840900_91_dialog_content = "대가주의 자리에 오르고, 진리의 결사를 차지하기 위해서라도,\n데이비드는 반드시 남아서 오늘 밤의 의식을 주관하려 할 거야.",
  ui_story_5084_50840900_92_dialog_content = "야심은 이렇게나 무서운 거란다. 빌헬름을 집어삼킨 것처럼, 그 또한 집어삼켜질 거야.",
  ui_story_5084_50840900_93_dialog_content = "그럼 우린 이제 어디로 가?",
  ui_story_5084_50840900_94_dialog_content = "내 선조의 무덤으로 갈 거야. 확인하고 싶은 게 있어.\n예상대로라면 데이비드도 사람을 보낼 거야.",
  ui_story_5084_50840900_95_dialog_content = "빅토리아 님, 잠깐만요... 나일즈 씨는 어떡해요?",
  ui_story_5084_50840900_96_dialog_content = "아직 마을에 있잖아요.",
  ui_story_5084_50840900_97_dialog_content = "걱정하지 말렴, 주께서 이미 그를 지켜주시니까, 진리가 그를 올바른 곳으로 인도할 거란다.",
  ui_story_5084_50840900_98_dialog_content = "그치만 빅토리아 님... 전 가주들이 나일즈 씨를 해치는 걸 봤어요...",
  ui_story_5084_50840900_99_dialog_content = "걱정이 돼서 계속 찾으러 가고 싶었는데...\n그럼 빅토리아 님이랑 다른 사람들한테 문제가 생길까 걱정돼요.",
  ui_story_5084_50840900_100_dialog_content = "마음이 갈피를 잡지 못해도 괜찮아. 타인을 걱정하는 건 아름다운 품성이니까.\n메이, 네가 바라는 대로 하면 돼.",
  ui_story_5084_50840900_101_dialog_content = "파우스트, 넌 메이와 여기 남아서 나일즈를 지켜봐.",
  ui_story_5084_50840900_102_dialog_content = "난 아이테르와 함께 움직일게. 오늘 밤 교회에서 만나.",
  ui_story_5084_50841001_1_dialog_content = "입구 쪽 덩굴이 피를 흘리고 있어... 관도 쪼개져 있고. 가주들이 우리보다 한발 빨랐나?!",
  ui_story_5084_50841001_2_dialog_content = "혈족의 규율을 가벼이 여긴 걸로도 모자라... 선조들의 유해까지 욕보였구나.",
  ui_story_5084_50841001_3_dialog_content = "우리가 전에 본 게 여기가 맞는 것 같아!",
  ui_story_5084_50841001_4_dialog_content = "클라비스가 빌헬름 씨를 관에 집어넣은 곳 말이야...",
  ui_story_5084_50841001_5_dialog_content = "하지만 그 관은 여기 없어.",
  ui_story_5084_50841001_6_dialog_content = "아가씨... 빅토리아 아가씨... 맞으십니까?",
  ui_story_5084_50841001_7_dialog_content = "그레이브스? 무사했구나. 피 흘리는 덩굴을 보고 당신까지 이미 당했다고 생각했어...",
  ui_story_5084_50841001_8_dialog_content = "3년... 3년입니다.\n왈라키아의 가주가 이 땅을 제대로 다스리지 못해, 모든 것이 통제를 잃었습니다.",
  ui_story_5084_50841001_9_dialog_content = "빌헬름 님께서 돌아가시고, 아가씨는 행방이 묘연해지셨지요.\n놈들은 물불을 가리지 않고 선조님들의 유산을 손에 넣으려 했습니다.",
  ui_story_5084_50841001_10_dialog_content = "놈들은 제 가족을 붙잡고, 그들을 괴롭히며, 제게 고통을 가했습니다...",
  ui_story_5084_50841001_11_dialog_content = "데이비드 짓입니다... 데이비드는 모든 것을 차지하려고,\n왈라키아의 하인으로서의 제 힘을 빼앗아 갔습니다...",
  ui_story_5084_50841001_12_dialog_content = "...미안해, 내가 떠나 있는 동안 당신 가족이 고통받게 될 줄은 몰랐어.",
  ui_story_5084_50841001_13_dialog_content = "그레이브스, 빌헬름은 정말 죽은 거야?",
  ui_story_5084_50841001_14_dialog_content = "클라비스... 대, 대체 무슨 짓을 한 거냐...",
  ui_story_5084_50841001_15_dialog_content = "...그저 시체 한 구를 더 가져다 놨을 뿐이다.",
  ui_story_5084_50841001_16_dialog_content = "내 아둔한 친구를 잘 돌봐주길 바란다.",
  ui_story_5084_50841001_17_dialog_content = "클라비스... 클라비스...",
  ui_story_5084_50841001_18_dialog_content = "제 두 눈으로 빌헬름 님이 돌아가신 것을 봤습니다...\n클라비스가 멋대로 「열쇠」를 사용해 무덤으로 들어왔고, 그분을 안장했습니다.",
  ui_story_5084_50841001_19_dialog_content = "...안으로 들어가 살펴보자, 아이테르.",
  ui_story_5084_50841001_20_dialog_content = "걱정 마, 그레이브스. 모든 분쟁은 오늘 밤 주의 눈 아래 끝을 맞이할 거야.",
  ui_story_5084_50841001_21_dialog_content = "조심하십시오... 아가씨...",
  ui_story_5084_50841001_22_dialog_content = "안쪽 깊은 곳에서... 그자들이 무덤을 파괴하며... 무언가를 찾고 있습니다...",
  ui_story_5084_50841001_23_dialog_content = "오, 이게 누구신가.",
  ui_story_5084_50841001_24_dialog_content = "우리의 왈라키아 아가씨가 행차하셨군.",
  ui_story_5084_50841001_25_dialog_content = "...아가씨!",
  ui_story_5084_50841001_26_dialog_content = "덩굴인간, 생각보다 명줄이 길군...",
  ui_story_5084_50841001_27_dialog_content = "데이비드가 왈라키아 아가씨를 죽이라고 했었던가?",
  ui_story_5084_50841001_28_dialog_content = "선수 치는 쪽이 유리한 법이다.",
  ui_story_5084_50841001_29_dialog_content = "아둔한 무리들...!",
  ui_story_5084_50841001_30_dialog_content = "감히 왈라키아의 무덤에 함부로 발을 들여 선조들의 영면을 방해하다니!",
  ui_story_5084_50841001_31_dialog_content = "오늘 밤 의식에서 너희를 벌하려 했는데, 너희가 먼저 나설 줄이야.",
  ui_story_5084_50841002_1_dialog_content = "빅토리아 씨... 「물귀신」이라는 녀석, 땅에 스며들더니 도망쳐 버렸어...",
  ui_story_5084_50841002_2_dialog_content = "훗, 그럼 남은 너희 둘은 종말을 맞이할 준비가 됐을까?",
  ui_story_5084_50841002_3_dialog_content = "잠깐... 확실히 성장했군, 왈라키아 가문의 아가씨.\n아니면 데이비드와 잘 이야기해 보는 건 어떤가?",
  ui_story_5084_50841002_4_dialog_content = "말도 안 돼! 고작 3년간 밖을 돌아다녔을 뿐인데, 대체 어디서 힘을 얻은 거냐...",
  ui_story_5084_50841002_5_dialog_content = "3년? 스스로를 비좁은 세상 속에 가둔 너희는 그런 강렬한 변화를 이해하지 못해.",
  ui_story_5084_50841002_6_dialog_content = "이 힘이 쌓여온 게 고작 3년일 것 같아? ...뭐, 너희에게 그 비밀을 밝힐 생각은 없어.",
  ui_story_5084_50841002_7_dialog_content = "욕망에 이끌려 진리의 길에서 멀어진 광인들이여. 성명제의 전주 속에서 죽음을 맞이할지어다!",
  ui_story_5084_50841002_8_dialog_content = "(...스칼렛이 과거를 바꾸면 안 된다고 했는데, 빅토리아 씨가 저 두 사람을\n죽이려고 하는 건... 과거를 바꾸는 거 아닌가?)",
  ui_story_5084_50841002_9_dialog_content = "(아니면... 빅토리아 씨의 무의식도 기록된 역사 속 일부인 건가?)",
  ui_story_5084_50841002_10_dialog_content = "으음?",
  ui_story_5084_50841002_11_dialog_content = "「뱀의 비술」이다... 넌 이해할 수 없겠지.",
  ui_story_5084_50841002_12_dialog_content = "머리를 잘라 내도, 뱀은 여전히 허물을 벗고 재생할 수 있다...",
  ui_story_5084_50841002_13_dialog_content = "그렇다면 여러 번 잘라 내면 그만이야!",
  ui_story_5084_50841002_14_dialog_content = "머, 멈춰! 넌 날 죽일 수 없다!",
  ui_story_5084_50841002_15_dialog_content = "널 죽일 생각은 없어. 하지만 머리가 잘려 나가는 고통을 넌 어떻게 견뎌 낼 수 있을까?",
  ui_story_5084_50841002_16_dialog_content = "넌 애원하고! 울부짖게 될 거야!\n<size=45>스스로 생을 끝내고 싶어질 거라고──!</size>",
  ui_story_5084_50841002_17_dialog_content = "(빅토리아 씨한테... 이런 잔혹한 면도 있었던 거야...?)",
  ui_story_5084_50841002_18_dialog_content = "<color=#e8d9bb>그 순간, 깊고 어두운 무덤 속 벽에 기대어져 있던 관이 벌컥 열렸고,\n안에서 한 사람이 걸어 나왔다...</color>",
  ui_story_5084_50841002_19_dialog_content = "그자를 고문할 필요는 없다.",
  ui_story_5084_50841002_20_dialog_content = "?!",
  ui_story_5084_50841002_21_dialog_content = "...비, 빌헬름?!",
  ui_story_5084_50841002_22_dialog_content = "그럴 리가! 넌 이미 진작에 죽었잖아!",
  ui_story_5084_50841002_23_dialog_content = "...역시 살아 있었구나.",
  ui_story_5084_50841002_24_dialog_content = "아니, 난 한때 죽었다. 허나 시간의 흐름 속에서 오랜 세월을 떠돌았지.\n그리고 마침내 주의 뜻을 조금이나마 깨닫게 되었다.",
  ui_story_5084_50841002_25_dialog_content = "3년 전 성명제 땐... 당신이었구나.",
  ui_story_5084_50841002_26_dialog_content = "운명이 나를 이곳으로 인도했다. 3년은 찰나일 뿐, 아마 이곳이 나의 마지막 종착지겠지.",
  ui_story_5084_50841002_27_dialog_content = "......?!",
  ui_story_5084_50841002_28_dialog_content = "(그랬구나! 내가 본 빌헬름 씨는 역시 두 사람이었어!)",
  ui_story_5084_50841002_29_dialog_content = "(빅토리아 씨를 제물로 바치고 이 모든 걸 계획한 건 전부...\n죽음을 맞이했던 이 빌헬름 씨인 건가?)",
  ui_story_5084_50841002_30_dialog_content = "받아라. 이것은 스스로 널 따르고자 하는 운명이다.",
  ui_story_5084_50841002_31_dialog_content = "이건... 핏빛 성전?",
  ui_story_5084_50841002_32_dialog_content = "아니야... 이건 내게 이미 익숙한 그 성물이 아냐.",
  ui_story_5084_50841002_33_dialog_content = "「새로운 성전」이다. 미래의 인도자에게 반드시 전해져야 할 성물이지.",
  ui_story_5084_50841002_34_dialog_content = "잘 간직해라. 오직 너만이 다룰 수 있는 힘이다.",
  ui_story_5084_50841002_35_dialog_content = "그 힘으로 네 눈앞의 광대들을 없애라.",
  ui_story_5084_50841002_36_dialog_content = "...필요 없어.",
  ui_story_5084_50841002_37_dialog_content = "......?!",
  ui_story_5084_50841002_38_dialog_content = "「당신」이 준 힘은 필요하지 않아.\n당신을 죽인 건 저들이니, 당신 원한은 당신 스스로 갚아.",
  ui_story_5084_50841002_39_dialog_content = "...대체 어떻게 된 거냐, 우리가 싸울 힘조차 내지 못하다니.",
  ui_story_5084_50841002_40_dialog_content = "저 빌헬름은 우리가 숨통을 끊었던 그 빌헬름이 아냐.",
  ui_story_5084_50841002_41_dialog_content = "빌헬름! 죽고 나서 대체 어떤 일이 있었던 거냐! 적어도 네가 본 「진리」를 내게 말해다오!",
  ui_story_5084_50841002_42_dialog_content = "...시끄럽다!",
  ui_story_5084_50841002_43_dialog_content = "진리는 네놈들 따위의 이해를 필요로 하지 않는다!",
  ui_story_5084_50841002_44_dialog_content = "왈라키아의 선조들을 모욕한 너희들의 죄는 오직 피로만 속죄할 수 있을 것이다!",
  ui_story_5084_50841002_45_dialog_content = "왈라...키아...",
  ui_story_5084_50841002_46_dialog_content = "(검을 한 번 휘둘렀을 뿐인데 가주 둘을 처치했어... 이게 빌헬름 씨의 실력...!)",
  ui_story_5084_50841002_47_dialog_content = "빌헬름 왈라키아, 이 관은 선조들이 영면을 취해야 할 곳이었을 텐데...\n당신 몸에 무슨 일이 있었던 거야?",
  ui_story_5084_50841002_48_dialog_content = "당신은 왜 사라졌고, 왜 지금 다시 나타날 수 있었던 거지?",
  ui_story_5084_50841002_49_dialog_content = "부활한 거야? 아니면 그저 환영에 불과한가?",
  ui_story_5084_50841002_50_dialog_content = "넌 여전히 내가 기억하는 그대로군. 입만 열면 질문이 그칠 줄 모르지.",
  ui_story_5084_50841002_51_dialog_content = "유감스럽지만 이미 지나간 일이다. 난 이미 죽었고, 그런 의논 또한 무의미하겠지.",
  ui_story_5084_50841002_52_dialog_content = "작별이다, 빅토리아.",
  ui_story_5084_50841002_53_dialog_content = "(이대로 가 버리는 거야...? 간신히 만났고, 분명히 서로를 엄청 신경 쓰면서,\n어떻게 이렇게 말을 마칠 수가 있는 건데?)",
  ui_story_5084_50841002_54_dialog_content = "...빌헬름 씨, 잠깐만요!",
  ui_story_5084_50841002_55_dialog_content = "아이테르...",
  ui_story_5084_50841002_56_dialog_content = "너는...",
  ui_story_5084_50841002_57_dialog_content = "그 목소리...",
  ui_story_5084_50841002_58_dialog_content = "아... 그랬군...",
  ui_story_5084_50841002_59_dialog_content = "이것이 바로... 운명이었단 말인가...",
  ui_story_5084_50841002_60_dialog_content = "운명이라, 하하...",
  ui_story_5084_50841002_61_dialog_content = "빌헬름 씨! 아무리 당신이 이걸 「운명」이라 부른다 해도...",
  ui_story_5084_50841002_62_dialog_content = "그때의 빌헬름 씨는 「운명」의 부름을 받았어도, 여전히 자신이 믿는 진리를 추구했어요.\n그래서 빅토리아 씨의 미래를 걱정하며 무덤으로 갔었고요.",
  ui_story_5084_50841002_63_dialog_content = "그리고 빅토리아 씨는 이미 정해진 이 「운명」 속으로 들어왔고, 빌헬름 씨를 찾기 위해\n위험을 무릅쓰고 반지를 꼈어요. 머릿속의 속삭임을 견디면서 말이에요!",
  ui_story_5084_50841002_64_dialog_content = "시간조차 뛰어넘어 여기까지 왔는데, 두 사람 다 서먹함을 풀고\n잘 좀 이야기해 볼 순 없는 건가요?",
  ui_story_5084_50841002_65_dialog_content = "두 사람이 가주들과 싸우고, 검을 휘두를 때...\n전 두 사람을 움직이는 감정을 「볼」 수 있었어요.",
  ui_story_5084_50841002_66_dialog_content = "죄송해요... 어쩌면 지금 전 또 하지 말아야 할 말을 해서,\n뭔가를 영원히 바꿔버린 건지도 모르겠죠...",
  ui_story_5084_50841002_67_dialog_content = "하지만 전 그 어느 때보다도 제가 하려는 말에 확신이 있어요.",
  ui_story_5084_50841002_68_dialog_content = "전 언어야말로 자기 뜻을 전하는 최고의 방법이라고 생각해요...\n아무 말도 하지 않으면... 상대를 이해할 기회를 영원히 잃고 말아요.",
  ui_story_5084_50841002_69_dialog_content = "......",
  ui_story_5084_50841002_70_dialog_content = "......",
  ui_story_5084_50841002_71_dialog_content = "어쩌면 문제나 답 같은 건 중요하지 않을지도 몰라요.\n그것보단 두 사람이 지금 여기 있다는 게 더 중요하죠.",
  ui_story_5084_50841002_72_dialog_content = "이게 「운명」의 인도든 아니든, 두 사람의 선택은 각자의 마음에서 비롯된 거니까요.",
  ui_story_5084_50841002_73_dialog_content = "아이테르... 너...",
  ui_story_5084_50841002_74_dialog_content = "후훗, 세상 사람들이 모두 너처럼 진실하다면,\n다들 그리 쉽게 잘못된 길로 빠지진 않을 거야.",
  ui_story_5084_50841002_75_dialog_content = "진실함은 저 아이테르와 같은 젊은이만이 지닌 보물이다.",
  ui_story_5084_50841002_76_dialog_content = "흐음... 어디서부터 이야기를 하는 게 좋을지 모르겠군.",
  ui_story_5084_50841002_77_dialog_content = "난 이미 시간의 너머에서 오랫동안 떠돌았다...\n이렇게까지 안식을 갈망해 본 적이 없을 정도로 기나긴 시간이었지.",
  ui_story_5084_50841002_78_dialog_content = "빅토리아... 난 마침내 긴 잠을 바라던 형님을 이해할 수 있게 되었다.\n지금의 너 또한 분명히 이해하겠지.",
  ui_story_5084_50841002_79_dialog_content = "마음에서 비롯된 선택은 한때 하늘의 별만큼이나 많았다.",
  ui_story_5084_50841002_80_dialog_content = "허나 네게 감사를 전하고 싶다... 네가 왈라키아 가문을 혈통의 저주에서 해방시켜 주었기에,\n나는 미래에서 순조롭게 눈을 감을 수 있었다.",
  ui_story_5084_50841002_81_dialog_content = "...당신도 남한테 감사할 수 있는 거였어...?\n그것보다, 혈통의 저주를 해방시킨 게 나라고...?",
  ui_story_5084_50841002_82_dialog_content = "아이테르의 말대로다.\n네가 이곳에 도달할 수 있었던 것을 보면, 문제와 답은 이미 중요하지 않...",
  ui_story_5084_50841002_83_dialog_content = "중요해!",
  ui_story_5084_50841002_84_dialog_content = "진리는 사람에 따라 다르고, 최종적인 답도 없어. 오직 끊임없이 추구하는 신념만이 진실해.",
  ui_story_5084_50841002_85_dialog_content = "...그렇다면 계속 말해 봐라.",
  ui_story_5084_50841002_86_dialog_content = "세상에는 「갈림길」과 「고난」이 존재해.\n장생하는 종족은 죽음을 갈망하지만, 반대로 하루살이는 더 많은 미래를 간청해.",
  ui_story_5084_50841002_87_dialog_content = "이 아이올리아엔 <color=#FFB400>구세주</color>가 존재할까?",
  ui_story_5084_50841002_88_dialog_content = "난 예언 속 거대한 고난을 목도했지만, 그것을 통해 <color=#FFB400>구원</color>의 존재를 확신하게 됐어.",
  ui_story_5084_50841002_89_dialog_content = "그래서 내가 추구하는 진리는 세상의 모든 타락의 씨앗을 없앨 수 있는 <color=#FFB400>구원</color>이야.",
  ui_story_5084_50841002_90_dialog_content = "우린 물질의 한계와 의식의 속박을 뛰어넘고, 드높은 진화를 이루어 별들을 향해 나아갈 거야.\n그건 오직 지고의 진리를 통해서만 이룰 수 있어.",
  ui_story_5084_50841002_91_dialog_content = "...계시에서 드러난 대로, 너는 이미 성장했고, 충분한 자격을 손에 넣었다.",
  ui_story_5084_50841002_92_dialog_content = "「별들」이라... 나는 숨을 거두었을 때, 어둠 속에서 한 줄기 강을 보았다.",
  ui_story_5084_50841002_93_dialog_content = "그 위로는 세상의 인과가 흐르고 있었고, 미약한 파동도 거대한 고난을 자아내더군.",
  ui_story_5084_50841002_94_dialog_content = "긴 삶을 누리는 우리 혈족들이 무한에 가까운 시간을 들여 추구한 것도,\n그 강에서는 그저 모래 한 톨에 불과했지...",
  ui_story_5084_50841002_95_dialog_content = "그럼에도 불구하고, 진리를 추구하겠다는 나의 집념은 나를 그 강으로 이끌었다.",
  ui_story_5084_50841002_96_dialog_content = "그렇기에 나는 나의 진리를 확신하게 되었다. 실천의 길에는 수많은 어려움이 존재하겠지만,\n고난을 소거하고 나면 소망이 인과의 흐름을 좌우할 것이다.",
  ui_story_5084_50841002_97_dialog_content = "당신 신념이 변하지 않고, 당신이 증오하던 「운명의 굴레」를 초월했다고 생각하는 거야?",
  ui_story_5084_50841002_98_dialog_content = "나는 신념에 복종하고, 신념을 따를 것이다.\n그리고... 운명을 간파할 기회를 찾고, 내 손으로 직접 인과의 흐름을 비틀 것이다.",
  ui_story_5084_50841002_99_dialog_content = "...가거라, 빅토리아여. 너의 길을 행하고, 길 위의 장애물을 없애라.",
  ui_story_5084_50841002_100_dialog_content = "물론 그래야지.",
  ui_story_5084_50841002_101_dialog_content = "데이비드가 우리의 마을을 죽음의 영역으로 만들기 전에, 네가 그 모든 것을 막아야 한다.",
  ui_story_5084_50841002_102_dialog_content = "...또 어딜 가려고?",
  ui_story_5084_50841002_103_dialog_content = "나는 이미 시간의 밖을 표류하는 존재가 되었고, 이 처지를 함부로 바꾸진 않을 것이다.\n그것이 운명이라면 모를까...",
  ui_story_5084_50841002_104_dialog_content = "...우리가 그때의 대화를 끝마치게 될 줄은 몰랐어, 숙부.",
  ui_story_5084_50841002_105_dialog_content = "빅토리아, 많이 성장했군... 다행이다.",
  ui_story_5084_50841002_106_dialog_content = "이 「재앙의 서」를 가지고 가라. 필요하게 될 것이다.",
  ui_story_5084_50841002_107_dialog_content = "난 이미 진리의 탐구에 필요한 힘을 가지고 있어. 그걸 가질 필요는 없어.",
  ui_story_5084_50841002_108_dialog_content = "...운명이 너희의 만남을 인도할 것이다.",
  ui_story_5084_50841002_109_dialog_content = "작별이다, 빅토리아 왈라키아.",
  ui_story_5084_50841002_110_dialog_content = "네 신도 가운데... 그 나일즈란 자는 잠재력이 있더군.",
  ui_story_5084_50841002_111_dialog_content = "미래의 진리의 결사는 너희에게 맡기겠다.",
  ui_story_5084_50841002_112_dialog_content = "...다시 만날 수 있을까?",
  ui_story_5084_50841002_113_dialog_content = "나는 이미 그분께서 내게 주신 시련을 모두 완수했다.\n이제는 나 자신을 위한 일을 하고자 한다.",
  ui_story_5084_50841002_114_dialog_content = "모든 것이 끝나면, 그때 이곳에서 만나도록 하자.",
  ui_story_5084_50841002_115_dialog_content = "...한 가지 더, 미래에서 온 아이테르여, 네 진실함으로 그때의 나를 이끌어 주어 고맙다.",
  ui_story_5084_50841101_1_dialog_content = "이게 다 할머니 때문이야... 진리의 주인께 드리고 싶은 말이 있다면서\n다 듣고 가라고 하다니...",
  ui_story_5084_50841101_2_dialog_content = "결국 맨 뒤 자리밖에 없어서 행렬이 보이지도 않잖아.",
  ui_story_5084_50841101_3_dialog_content = "할머니는 이제 움직이는 게 불편하셔서 성명제에 참가하기 힘드셔.",
  ui_story_5084_50841101_4_dialog_content = "하지만 평생 신도들의 옷을 만들어 오셨으니까, 네가 그 마음을 대신 전해 주길 바라신 거야.",
  ui_story_5084_50841101_5_dialog_content = "이따가 엄마가 앞에 볼 수 있게 높이 들어 줄게.\n대신 할머니 말씀 잊으면 안 돼. 장난치지 말고, 경건한 마음으로 봐.",
  ui_story_5084_50841101_6_dialog_content = "...알겠어.",
  ui_story_5084_50841101_7_dialog_content = "익숙한 그 거리야. 내가 PlayerName하고 만난 곳이야.",
  ui_story_5084_50841101_8_dialog_content = "근데 사람이 너무 많아. 어디로 가야 나일즈 씨를 찾을 수 있을까?",
  ui_story_5084_50841101_9_dialog_content = "메이... 그때도 저런 기묘한 망토를 두른 사람들이 있었어?",
  ui_story_5084_50841101_10_dialog_content = "조, 좀 생각해 볼게...",
  ui_story_5084_50841101_11_dialog_content = "끼아아악──!",
  ui_story_5084_50841101_12_dialog_content = "...? 가서 확인해 보자!",
  ui_story_5084_50841101_13_dialog_content = "...사도다! 사도가 나타났다!",
  ui_story_5084_50841101_14_dialog_content = "위대하신 주님... 절 벌하시는 건 압니다!\n전 언니의 일기를 훔쳐 보고, 언니의 위선을 만인 앞에서 폭로했습니다...",
  ui_story_5084_50841101_15_dialog_content = "하지만 진리의 결사의 가주들은 제가 이미 병들었고,\n제 피가 당신께 총애를 받을 일은 없을 거라고 했습니다...",
  ui_story_5084_50841101_16_dialog_content = "그러니 제 살을 베어, 벌을 받겠습니다...!",
  ui_story_5084_50841101_17_dialog_content = "엄마...?",
  ui_story_5084_50841101_18_dialog_content = "하지만 부디 하나밖에 없는 제 딸만큼은 빼앗지 말아 주세요. 이 아이는 죄가 없습니다...",
  ui_story_5084_50841101_19_dialog_content = "주여!",
  ui_story_5084_50841101_20_dialog_content = "...위대하신 진리의 주인이시여! 저를 벌하시려고... 저들을 보내신 겁니까?",
  ui_story_5084_50841101_21_dialog_content = "알겠습니다... 눈도 깜빡이지 않겠습니다! 부디 제게 벌을 내려 주세요!",
  ui_story_5084_50841101_22_dialog_content = "──!",
  ui_story_5084_50841101_23_dialog_content = "엄마아아──!",
  ui_story_5084_50841101_24_dialog_content = "아악...!",
  ui_story_5084_50841101_25_dialog_content = "도, 도망쳐!",
  ui_story_5084_50841101_26_dialog_content = "망토를 쓴 괴물들... 거리에 흐르는 피... 무슨 일이 벌어진 게 분명해!",
  ui_story_5084_50841101_27_dialog_content = "...! 메이, 싸울 준비를 해!",
  ui_story_5084_50841101_28_dialog_content = "역시... 빅토리아 님을 시작으로, 「운명」은 우리의 개입을 허락한 거야.",
  ui_story_5084_50841101_29_dialog_content = "알겠어! 나쁜 애는 벌을 받아야지!",
  ui_story_5084_50841101_30_dialog_content = "...통증 따위는 느끼지 않습니다!",
  ui_story_5084_50841101_31_dialog_content = "아직입니다...!",
  ui_story_5084_50841101_32_dialog_content = "아악...!",
  ui_story_5084_50841101_33_dialog_content = "엄마아아아──!",
  ui_story_5084_50841101_34_dialog_content = "길 잃은 어린양이여, 두려워 마세요... 「성혈」이 굳기 시작했습니다...",
  ui_story_5084_50841101_35_dialog_content = "...계시를 받은 그분이셨군요! 왜 자기 몸을 찌르고 있는 건가요?!",
  ui_story_5084_50841101_36_dialog_content = "어리석은 아가씨, 이것은 제 힘이 아닙니다...\n저는 계시를 받은 자가 아니라, 나일즈일 뿐입니다...",
  ui_story_5084_50841101_37_dialog_content = "진리의 주인께서는 제게 죄책감과 연민을 느끼지 말라 하셨습니다.",
  ui_story_5084_50841101_38_dialog_content = "설령 당신의 어머니가 저와 같은 죄인이라 할지라도...",
  ui_story_5084_50841101_39_dialog_content = "죄인을 대신해 제가 대답하도록 하죠!",
  ui_story_5084_50841101_40_dialog_content = "오빠...? 이게 뭐예요...?",
  ui_story_5084_50841101_41_dialog_content = "죄악이자... 축복이며...",
  ui_story_5084_50841101_42_dialog_content = "멘토님께서 말씀하신... 「성혈」의 힘입니다!",
  ui_story_5084_50841101_43_dialog_content = "뜨겁고 선명하게 타오르는 불꽃... 진리의 주인께서 제 몸 안을 흐르고 계십니다.\n바라건대 저를 불태우시어, 위없는 온기를 느끼게 하소서!",
  ui_story_5084_50841101_44_dialog_content = "길 잃은 어린양이여, 보십시오...",
  ui_story_5084_50841101_45_dialog_content = "진리의 주인께서 우리의 죄를 사하실 겁니다!",
  ui_story_5084_50841101_46_dialog_content = "......!",
  ui_story_5084_50841101_47_dialog_content = "당신은... 그때... 계시를 받은 분! 이미 주의 「성도」가 되셨군요!",
  ui_story_5084_50841101_48_dialog_content = "아닙니다... 그렇게 부르지 말아 주십시오... 저는 아직...",
  ui_story_5084_50841101_49_dialog_content = "...아직 그 옷을 입고 계셨네요... 그건 저랑 우리 엄마, 그리고 우리 할머니가\n오빠를 위해 함께 만든 성도의 의복이에요.",
  ui_story_5084_50841101_50_dialog_content = "감사합니다. 여러분의 선물 덕분에 저는 지금의 모습이 될 수 있었습니다.",
  ui_story_5084_50841101_51_dialog_content = "그때 빌헬름 님께선 다른 생각이 있으셨을지도 모르지만...\n올해 계시를 받을 자는 분명히 당신이에요!",
  ui_story_5084_50841101_52_dialog_content = "멘토님께서 제게 전해주신 것 또한 숭고한 진리였습니다.\n이제 저는 감사의 마음으로 충만합니다.",
  ui_story_5084_50841101_53_dialog_content = "위험하지 않을 때 어서 이곳을 떠나십시오. 괜찮을 겁니다.",
  ui_story_5084_50841101_54_dialog_content = "알겠어요! 진리가 당신을 축복하길... 「성도」 나일즈 님!",
  ui_story_5084_50841101_55_dialog_content = "진리의 축복이 있길 바랄게요, 「성도」 나일즈 오빠!",
  ui_story_5084_50841101_56_dialog_content = "진리의 축복 있으라.",
  ui_story_5084_50841101_57_dialog_content = "「성도」 나일즈 씨!",
  ui_story_5084_50841101_58_dialog_content = "멀리서 괴물들을 처치하는 모습을 봤어.",
  ui_story_5084_50841101_59_dialog_content = "아, 메이, 파우스트... 오랜만입니다.",
  ui_story_5084_50841101_60_dialog_content = "완전... 멀쩡하네!",
  ui_story_5084_50841101_61_dialog_content = "나랑 PlayerName 둘이 엄청 걱정했다구!",
  ui_story_5084_50841101_62_dialog_content = "당시의 저는 주제넘었습니다... 결국 여러분을 곤란하게 만들었군요... 참회합니다...",
  ui_story_5084_50841101_63_dialog_content = "그래도 아까 그 힘은 진짜 대단했어! 설마 지금 입고 있는 그 옷 덕분인 거야?",
  ui_story_5084_50841101_64_dialog_content = "그런 이유도 있겠지요...\n지난 3년간, 저는 늘 저 재봉사 가족이 지어 준 이 옷을 입고 지냈습니다.",
  ui_story_5084_50841101_65_dialog_content = "아, 아무 데도 안 가고 여기 있었어?! 그러니까... 왈라지 마을에 3년이나 있었다고?!",
  ui_story_5084_50841101_66_dialog_content = "수행을 시작한 지도 이미 3년이 되었군요... 이 마을에만 머물진 않았습니다...\n멘토님께선 저를 아주 많은 곳에 데려가 주셨지요.",
  ui_story_5084_50841101_67_dialog_content = "멘토님...?",
  ui_story_5084_50841101_68_dialog_content = "그럼 네 「드문 피」가 새로운 형태로 굳어지게 된 건...\n그 멘토님이라는 분을 따라 수행에 매진했기 때문인 건가?",
  ui_story_5084_50841101_69_dialog_content = "그렇습니다... 멘토님께선 「드문 피」는 저주가 아니라고 하셨습니다...",
  ui_story_5084_50841101_70_dialog_content = "「그 땅에서 잃고, 이 땅에서 얻는다. 그 땅에서 죄를 속죄하고, 이 땅에서 은혜를 얻는다」\n이건 멘토님께서 제게 해 주신 말씀입니다.",
  ui_story_5084_50841102_1_dialog_content = "<color=#e8d9bb>3년 전...</color>",
  ui_story_5084_50841102_2_dialog_content = "위대하신 진리의 주인이시여, 당신의 신도 나일즈가 다시 한번 해방을 간구하나이다...",
  ui_story_5084_50841102_3_dialog_content = "제 피는 더럽혀져 있고... 저는 이미 각오를 다졌습니다...",
  ui_story_5084_50841102_4_dialog_content = "(여긴...)",
  ui_story_5084_50841102_5_dialog_content = "빅토리아 님께서는 신앙이 저를 이끌어 줄 것이라고 하셨습니다만...\n저는 희생을 택하고자 합니다...",
  ui_story_5084_50841102_6_dialog_content = "저는...",
  ui_story_5084_50841102_7_dialog_content = "......",
  ui_story_5084_50841102_8_dialog_content = "...주님이십니까?",
  ui_story_5084_50841102_9_dialog_content = "주님이시군요! 위대하신 진리의 주인이시여!",
  ui_story_5084_50841102_10_dialog_content = "방금... 「빅토리아 님」이라고 했나?",
  ui_story_5084_50841102_11_dialog_content = "저는 죄가 깊으나... 빅토리아 님과는 아무 관계도 없습니다.",
  ui_story_5084_50841102_12_dialog_content = "빅토리아 님께서는 저를 받아 주셨고, 진리의 결사의 동료들은 저를 아껴 주었지만,\n저는 이 더러운 피로 세상을 오염시키는 것 외에는 아무런 쓸모도 없습니다.",
  ui_story_5084_50841102_13_dialog_content = "진리의 결사의 지도자는 빅토리아고, 너는 진리의 결사의 일원이라는 것이냐.",
  ui_story_5084_50841102_14_dialog_content = "나일즈... 저는 나일즈라고 합니다. 위대하신 주인이시여.",
  ui_story_5084_50841102_15_dialog_content = "이 무덤에 있는 건 너 하나뿐인가?",
  ui_story_5084_50841102_16_dialog_content = "처음에는 빅토리아 님과 파우스트, 메이, 그리고 아이테르와 함께 왔습니다...\n저희는 밤하늘 무덤에 발을 들인 후 흩어지게 되었습니다.",
  ui_story_5084_50841102_17_dialog_content = "분명 당신께서 그들을 다른 곳으로 이끄신 것이겠지요...\n그들은 선하고, 용감하며, 눈부신 사람들입니다...",
  ui_story_5084_50841102_18_dialog_content = "「진리의 안내자로서」...",
  ui_story_5084_50841102_19_dialog_content = "인도하게 된다던 게 너희였나... 아이테르까지 진리의 결사의 일원이 되다니...",
  ui_story_5084_50841102_20_dialog_content = "「진리는 이미 그의 마음에 드러났으며, 그는 진리의 결사에 변혁을 가져올 힘이자,\n진리의 축복을 받은 자다」...",
  ui_story_5084_50841102_21_dialog_content = "진리의 축복이라...",
  ui_story_5084_50841102_22_dialog_content = "너는 진리의 주인께 무엇을 참회하고 싶으냐.",
  ui_story_5084_50841102_23_dialog_content = "...제가 태어나 지금까지 저지른 죄를 참회하고 싶습니다. 이것을 보아 주십시오...",
  ui_story_5084_50841102_24_dialog_content = "이런 피가 흐르는 것은 오직 저 같은 괴물뿐입니다... 저는 죄인입니다.",
  ui_story_5084_50841102_25_dialog_content = "헛소리...",
  ui_story_5084_50841102_26_dialog_content = "그, 그게 무슨 말씀이신지...",
  ui_story_5084_50841102_27_dialog_content = "해가 아직 저물지 않았으니, 너의 죄 많은 과거를 들어 줄 시간이 있다는 뜻이다.",
  ui_story_5084_50841102_28_dialog_content = "내가 뭘 하든 개의치 말고 계속 말해 봐라.",
  ui_story_5084_50841102_29_dialog_content = "다만 한 가지 조건이 있다. 그 못은 치워라.\n이곳은 왈라키아의 무덤, 피 한 방울조차 용납하지 않는다.",
  ui_story_5084_50841102_30_dialog_content = "알겠습니다! 위대하신 진리의 주인이시여.",
  ui_story_5084_50841102_31_dialog_content = "하나 더, 나는 진리의 주인이 아니다.",
  ui_story_5084_50841102_32_dialog_content = "그럼 당신은...?",
  ui_story_5084_50841102_33_dialog_content = "나는 빌헬름이다. 물론, 왈라키아라는 성도 가지고 있지. 내게 잘 어울리는 성은 아니다만.",
  ui_story_5084_50841102_34_dialog_content = "왈라키아...! 빅토리아 님과 같은 고귀한 가문의 일원이셨군요!",
  ui_story_5084_50841102_35_dialog_content = "하하, 고귀한 가문이라. 그저 다른 이들을 두려움에 몸서리치게 하는 존재일 뿐이다.",
  ui_story_5084_50841102_36_dialog_content = "지금의 나는 진리의 결사의 근원에 꽤나 맞닿아 있으며, 또한 시간 밖을 표류하는 자다.",
  ui_story_5084_50841102_37_dialog_content = "그런 내 앞에 너는 나타난 것이다. 먼저 말해 봐라. 누가 너를 괴물이라 부른 것이냐.",
  ui_story_5084_50841102_38_dialog_content = "제... 동생과, 제... 부모님... 그리고 온 가문 사람들입니다...",
  ui_story_5084_50841102_39_dialog_content = "그 이유는 고작 네가 방금 흘린 그 「드문 피」 때문인가?",
  ui_story_5084_50841102_40_dialog_content = "...물론 저의 존재가 그 이유이기도 합니다.\n저는 존재 자체만으로 제 동생에게 해가 되고, 제 가문을 수치스럽게 만들었습니다.",
  ui_story_5084_50841102_41_dialog_content = "제 동생은 본래 저 진리의 결사의 동료들처럼 선하고, 용감하며, 눈부신 사람이었습니다...",
  ui_story_5084_50841102_42_dialog_content = "그러나 저는 이 힘으로 순조롭게 작위를 받고, 기사들과의 대결에서\n승리를 거둘 수 있었던 반면...",
  ui_story_5084_50841102_43_dialog_content = "동생은 모든 면에서 저만큼 순탄하지 않았습니다...",
  ui_story_5084_50841102_44_dialog_content = "적대 가문의 아들은 더러운 수단으로 동생을 해치려 했습니다.\n그리고 저는 제가 지닌 힘을 제대로 의식하지 못한 채, 멋대로 동생을 지키려 했습니다...",
  ui_story_5084_50841102_45_dialog_content = "그 결과...!",
  ui_story_5084_50841102_46_dialog_content = "동생은... 분명 가문을 위해서 그랬겠지요.\n저 같은 사람은 그 순결하고 고귀한 고성에 있는 것만으로도 크나큰 죄악이니까요.",
  ui_story_5084_50841102_47_dialog_content = "그래서 동생은 저를 해방시켜 준 것입니다...\n제 「드문 피」를 드러내서, 절... 백야성에서 추방당하게 만들었습니다.",
  ui_story_5084_50841102_48_dialog_content = "왠지 익숙한 이야기로군...",
  ui_story_5084_50841102_49_dialog_content = "그 후, 너는 각지를 떠돌다가 빅토리아의 권유로 진리의 결사의 일원이 되었다는 건가?",
  ui_story_5084_50841102_50_dialog_content = "예... 한때는 오로리안과 암귀의 전쟁에서 제 목숨을 바치려 했지만...",
  ui_story_5084_50841102_51_dialog_content = "주께서 저의 죄가 깊다 여기시어, 「드문 피」로 하여금 계속하여\n저를 죽음에서 일으키시고, 일깨워 주셨습니다...",
  ui_story_5084_50841102_52_dialog_content = "제 참회는 아직 부족하고... 저는 아직 진리의 주인의 품으로 돌아갈 수 없다고 말입니다.",
  ui_story_5084_50841102_53_dialog_content = "......",
  ui_story_5084_50841102_54_dialog_content = "제가... 말이 너무 많았던 모양이군요. 죄송합니다, 빌헬름 님.\n조금 전까지 전 순진하게도 제가 이미 용서를 받고 주의 품으로 돌아간 줄 알았습니다.",
  ui_story_5084_50841102_55_dialog_content = "들어 보니 네 이야기는 결국 네가 귀족 가문에서 태어났고,\n특별한 재능을 지녔다는 이야기에 지나지 않는군.",
  ui_story_5084_50841102_56_dialog_content = "그리고 너를 시기하는 무능한 네 동생이 가주 자리를 노리고,\n너를 제거하려 갖은 수단을 쓴 거겠지.",
  ui_story_5084_50841102_57_dialog_content = "지금은 네 아우가 가주 자리를 이어받았나?",
  ui_story_5084_50841102_58_dialog_content = "그가 이어받아 마땅한 자리입니다...\n게다가... 동생은 저를 「제거」하려 하진 않았습니다...",
  ui_story_5084_50841102_59_dialog_content = "하하, 의심스럽기 짝이 없군... 백야성의 자제가 선하고, 용감하며, 눈부시다?",
  ui_story_5084_50841102_60_dialog_content = "진리의 결사의 열두 가주도 백야성에서 배척받던 「이단」이었다.",
  ui_story_5084_50841102_61_dialog_content = "그 「이단」들이 없었다면, 지금의 진리의 결사는 없었겠지.",
  ui_story_5084_50841102_62_dialog_content = "저는 확실히 백야성에서 배척받은 「이단」입니다만... 제 동생은...",
  ui_story_5084_50841102_63_dialog_content = "그렇다면 말해 봐라. 네가 백야성을 떠날 때, 네 아우는 어떤 표정을 짓고 있었지?",
  ui_story_5084_50841102_64_dialog_content = "......",
  ui_story_5084_50841102_65_dialog_content = "음? 모두의 앞에서 너를 파멸시키려 했던 네 아우가 너를 떠나보내며 짓던 표정은\n아마 평생 잊을 수 없을 텐데?",
  ui_story_5084_50841102_66_dialog_content = "동생은... 미소를 지으며 저를 축복해 주었습니다.",
  ui_story_5084_50841102_67_dialog_content = "하하하하! 네가 학대받든, 박해당하든, 그 족속들은 늘 네게서\n죄의 이유를 찾아내기 마련이다.",
  ui_story_5084_50841102_68_dialog_content = "그렇기에 너는 자신의 죄가 무겁다고 여겨 진리의 결사의 일원이 되었고,\n참회하며 자해하는 옛 습성을 그토록 오랜 시간 동안 신봉해 온 것이겠지.",
  ui_story_5084_50841102_69_dialog_content = "참회의 근원은 자기혐오일 뿐, 넌 그 「드문 피」를 혐오하는 것이다!",
  ui_story_5084_50841102_70_dialog_content = "그리고 그 자기혐오의 근원은 네가 그 악인들에게 헛된 기대를 품고,\n그들이 네게 퍼부은 악담을 진실이라 받아들이고 있기 때문이다.",
  ui_story_5084_50841102_71_dialog_content = "내가 똑똑히 말해주지. 「드문 피」는 괴물 따위가 아니라, 진리의 주인께서 내리신 축복이다.",
  ui_story_5084_50841102_72_dialog_content = "네가 암귀를 멸하도록 드문 피가 널 돕고 있다는 것이 바로 그 증거다.\n잘 들어라. 네게는 자기혐오에 빠져야 하는 이유가 단 하나도 없다.",
  ui_story_5084_50841102_73_dialog_content = "나일즈여, 네 아우에게 너라는 형은 과분하다. 오히려 네가 좋은 형이라는 점이 비극이겠지.",
  ui_story_5084_50841102_74_dialog_content = "형제의 반목, 배신, 소원한 관계...\n빌헬름 왈라키아여, 운명이 우리를 만나도록 이끌었군...",
  ui_story_5084_50841102_75_dialog_content = "한결같이 날 조롱하고 있는 것이 아니더냐!",
  ui_story_5084_50841102_76_dialog_content = "들어라, 나일즈. 선하고 용감한 이는 바로 너다. 빛은 조금 덜할지 몰라도 말이다.\n성스러운 못에서 비롯된 네 이름처럼 너는 고결하고 거룩하다.",
  ui_story_5084_50841102_77_dialog_content = "다른 이들을 구하는 일에 그 「드문 피」의 힘을 사용한다면,\n너는 진정한 구원을 얻을 수 있을 것이다.",
  ui_story_5084_50841102_78_dialog_content = "그렇게 생각하시다니... 정말 용감하시군요. 하지만 저는...",
  ui_story_5084_50841102_79_dialog_content = "넌 할 수 있다.",
  ui_story_5084_50841102_80_dialog_content = "......",
  ui_story_5084_50841102_81_dialog_content = "주께서는 어느 누구도 편애하지 않으신다.\n네가 마음속으로 너를 용서하지 못한다면, 주께서 어찌 너를 구원하실 수 있겠느냐.",
  ui_story_5084_50841102_82_dialog_content = "잊지 마라. 네가 먼저 자신을 인정해야만, 주께서도 너를 인정하신다.",
  ui_story_5084_50841102_83_dialog_content = "빌헬름 님... 어째서 제게 이런 말씀을 해 주시는 겁니까?",
  ui_story_5084_50841102_84_dialog_content = "그것은 지금 이 순간에 이루어진 우리의 만남이,\n이미 무언가를 영원히 바꾸어 놓았다는 것을 알기 때문이다.",
  ui_story_5084_50841102_85_dialog_content = "주께서 너를 내 곁으로 보낸 것이다. 나는 단언할 수 있다.",
  ui_story_5084_50841102_86_dialog_content = "나일즈, 지금은 네 생의 종점이 아니라, 네 생을 바쳐야 할 시작점이다.\n나를 따라 수행하겠느냐?",
  ui_story_5084_50841102_87_dialog_content = "이 한 몸의 죄를 씻어 낼 수만 있다면, 무엇이든 기꺼이 하겠습니다.",
  ui_story_5084_50841102_88_dialog_content = "좋다. 그렇다면 지금 바로 시작하도록 하지. 우리에겐 해야 할 일이 아직 많이 남아 있다.\n하지만 그게 이곳은 아니다...",
  ui_story_5084_50841102_89_dialog_content = "이곳의 시간은 종언을 고할 것이다.\n그리고 네 3년간의 수행은 너희가 도착한 그때, 그해의 성명제부터 시작될 것이다.",
  ui_story_5084_50841102_90_dialog_content = "네 지도자는 이미 그곳으로 돌아갔다.\n내 뒤에 있는 관에 누워, 왈라지 마을의 성명제를 떠올려라. 너의 동료들은 그곳에 있다.",
  ui_story_5084_50841102_91_dialog_content = "네가 다시 눈을 떴을 때, 성명제 의식이 거행되는 곳으로 가서 나를 찾아라.\n내가 널 계시를 받을 자로 선택하여, 진리의 축복을 받게 하겠다.",
  ui_story_5084_50841102_92_dialog_content = "제가 어떻게 해야 그곳에 갈 수 있는 겁니까...?",
  ui_story_5084_50841102_93_dialog_content = "너의 신념으로 갈 수 있을 것이다, 나일즈.",
  ui_story_5084_50841102_94_dialog_content = "네가 이곳에 올 수 있었던 것 또한 참회를 향한 너의 신념 덕분이다.\n그러니 너의 몸으로 느껴라.",
  ui_story_5084_50841102_95_dialog_content = "단 한 순간이라도 네가 이 세상에 태어났음을 축복할 수 있을 때,\n너는 비로소 진리를 발견하게 될 것이다.",
  ui_story_5084_50841102_96_dialog_content = "신념... 말씀이십니까...",
  ui_story_5084_50841102_97_dialog_content = "그렇다. 이제부터 내가 바로 너의 멘토다.",
  ui_story_5084_50841102_98_dialog_content = "<color=#e8d9bb>왈라지 마을, 재봉소 입구</color>",
  ui_story_5084_50841102_99_dialog_content = "...내가 어떻게... 여기에...?",
  ui_story_5084_50841102_100_dialog_content = "손님도 축제의 로브를 받으러 오셨나요?",
  ui_story_5084_50841102_101_dialog_content = "축제의 로브...?",
  ui_story_5084_50841102_102_dialog_content = "그래서 그때 우리가 이해할 수 없는 말을 했던 거구나...\n빌헬름 님이랑도 이미 아는 사이였던 거고.",
  ui_story_5084_50841102_103_dialog_content = "게다가 더 신비로운 그분 말이지요.",
  ui_story_5084_50841102_104_dialog_content = "저는 진심으로 제가 계시를 받게 될 것이라고 여겼고...\n그런 생각을 지닌 채 진리의 전당에 들어갔던 겁니다.",
  ui_story_5084_50841102_105_dialog_content = "하지만 이렇게 보니 지금껏 일어난 모든 일이 참으로 불가사의하군요.\n제가 처음으로 멘토님을 뵌 것이 언제인지도 잘 모르겠습니다.",
  ui_story_5084_50841102_106_dialog_content = "게다가 멘토님께서는 저를 성명제 당일로 돌려보내셨지만,\n그분은 어찌 된 영문인지 저를 알아보지 못하셨지요...",
  ui_story_5084_50841102_107_dialog_content = "그다음엔 어떻게 됐어? 빌헬름 님이 나일즈 씨를 교회 밖으로 내보낸 뒤에 말이야.",
  ui_story_5084_50841102_108_dialog_content = "......",
  ui_story_5084_50841102_109_dialog_content = "아아... 죄악의 피가 모두 흘러 사라지길...\n이제 더는 주의 용서를 구하지 않겠습니다...",
  ui_story_5084_50841102_110_dialog_content = "저는 죄인입니다... 죄가 너무나 깊습니다...",
  ui_story_5084_50841102_111_dialog_content = "저는 이 세상에 재앙을 가져오는 괴물일 뿐입니다. 그 사실은 이곳에 와서도 변하지 않습니다.",
  ui_story_5084_50841102_112_dialog_content = "서둘러 성명제에 참여하기 위해, 저는 그 재봉사 모녀의 성의를 저버렸습니다...",
  ui_story_5084_50841102_113_dialog_content = "그들은 저와 마주치는 바람에 돈을 벌 기회를 잃었습니다...",
  ui_story_5084_50841102_114_dialog_content = "방금 그 사람들은... 제 본질을 꿰뚫어 보았습니다...\n그래서 저를 계시를 받을 자로 인정하지 않고 사지에 몰아넣으려 했습니다...",
  ui_story_5084_50841102_115_dialog_content = "저는 계시를 받을 자가 아닙니다... 제가 멘토님과 동문들을 분개하게 만든 것입니다...",
  ui_story_5084_50841102_116_dialog_content = "어딜 가더라도... 저라는 존재는 미움을 받을 뿐입니다...",
  ui_story_5084_50841102_117_dialog_content = "으윽... 아아아...",
  ui_story_5084_50841102_118_dialog_content = "손과 발이 저려 오기 시작했습니다... 조금 전까지의 추위가...\n오히려 이제는 오랫동안 기다려 왔던 온기처럼 느껴집니다...",
  ui_story_5084_50841102_119_dialog_content = "이것도 좋겠지요...",
  ui_story_5084_50841102_120_dialog_content = "이 죄악으로 찬 마음을 가지고 조용히 눈을 감아, 다시는 이 세상에 해를 끼치지 않겠습니다.",
  ui_story_5084_50841102_121_dialog_content = "저는...",
  ui_story_5084_50841102_122_dialog_content = "내 설명에 부족한 점이 있었나 싶군.",
  ui_story_5084_50841102_123_dialog_content = "......?",
  ui_story_5084_50841102_124_dialog_content = "이토록 아름다운 「드문 피」의 힘을 그리도 혐오하는 건가?",
  ui_story_5084_50841102_125_dialog_content = "...멘토님? 멘토님이시군요! 괜찮으신... 겁니까?",
  ui_story_5084_50841102_126_dialog_content = "움직이지 마라, 상처가 치유되고 있는지 확인할 것이다.",
  ui_story_5084_50841102_127_dialog_content = "네가 조금 전 마주한 이는 나다. 그러나 처음의 나도 아니고, 지금의 나도 아니지.",
  ui_story_5084_50841102_128_dialog_content = "안에서 발생한 일을 쭉 지켜보았지만, 나는 네게 대체 무슨 죄가 있는지 알 수 없었다.",
  ui_story_5084_50841102_129_dialog_content = "제 몸엔... 멘토님께서도 보셨듯, 괴물이 있습니다...",
  ui_story_5084_50841102_130_dialog_content = "괴물? 지난날의 내가 보기에도 네 능력은 두려울 정도로 강했고,\n진리의 결사와 인연이 닿도록 정해져 있었다...",
  ui_story_5084_50841102_131_dialog_content = "알아 두어라. 내가 본 진리의 결사의 미래는, 기이하면서도 품위를 잃지 않고,\n감성적이면서도 지혜를 잃지 않은 이들로 이루어져 있었다.",
  ui_story_5084_50841102_132_dialog_content = "네가 계속 자신의 특이성을 탐구해 나간다면, 시간의 흐름이 반드시 널 적확한 곳으로 이끌어,\n응당 만나야 할 이들과 마주하게 할 것이다.",
  ui_story_5084_50841102_133_dialog_content = "앞으로는 내가 너와 함께 수행할 것이라고 말했었지.\n그러니 네가 겪은 일들 또한 수행의 일부다.",
  ui_story_5084_50841102_134_dialog_content = "멋대로 죄스러운 마음을 품고 죽음을 택하려 하다니,\n내 말을 진지하게 여기지 않은 모양이로군.",
  ui_story_5084_50841102_135_dialog_content = "부디 제게 벌을 내려 주십시오... 멘토님... 제가 약속을 실천하지 못했습니다...",
  ui_story_5084_50841102_136_dialog_content = "그럴 필요 없다. 네 마음과 영혼은 갖은 모욕을 당했고,\n네 육체 역시 고통에 시달리며 방랑해 왔다. 이는 네 탓이 아니다.",
  ui_story_5084_50841102_137_dialog_content = "그러나 이제는 네가 있어야 할 곳에 왔으니, 네 특별한 능력을 발휘해\n빛을 발할 때가 되었다.",
  ui_story_5084_50841102_138_dialog_content = "제가... 말입니까?",
  ui_story_5084_50841102_139_dialog_content = "잘 생각해 봐라. 다른 사람들이 아닌 오롯이 너의 상황만을 생각했을 때,\n그 「드문 피」가 단 한 번이라도 널 해친 적이 있었나?",
  ui_story_5084_50841102_140_dialog_content = "......",
  ui_story_5084_50841102_141_dialog_content = "부유하고 안락한 삶을 보내는 이들이 앞다투어 던지는 재산은,\n고생하며 떠돌아다니는 이들에게는 구원의 동아줄이 되기도 한다.",
  ui_story_5084_50841102_142_dialog_content = "너는 자신의 영혼을 상처입히고, 다른 사람의 죄악으로 자신을 옥죄며,\n너와 다른 이들을 구하고자 하는 네 영혼의 바람을 저버리고 있다.",
  ui_story_5084_50841102_143_dialog_content = "어째서 그 「드문 피」가 괴물을 없애고, 타인을 구할 수 있다는 사실을\n믿으려 하지 않는 것이냐.",
  ui_story_5084_50841102_144_dialog_content = "다른 이들은... 저를 피하고, 혐오할 겁니다...",
  ui_story_5084_50841102_145_dialog_content = "또 타인이냐... 잘 들어라, 그렇게 생각하는 것은 과거의 너다.\n미래에는 그러지 않아야 마땅하다.",
  ui_story_5084_50841102_146_dialog_content = "넌 그 한 몸의 죄를 씻어 낼 수만 있다면, 무엇이든 기꺼이 하겠다고 내게 말했었지.\n그 첫걸음은 바로 네게 죄가 없다고 믿는 것이다.",
  ui_story_5084_50841102_147_dialog_content = "할 수 있겠나?",
  ui_story_5084_50841102_148_dialog_content = "멘토님...",
  ui_story_5084_50841102_149_dialog_content = "그래, 지혜로운 너라면 내 뜻을 이해하겠지.",
  ui_story_5084_50841102_150_dialog_content = "날 따라와라. 나의 거처는 사람들의 눈을 피해 수행하기 좋은 곳이다.",
  ui_story_5084_50841102_151_dialog_content = "너는 그곳에서부터 시작해서, 여러 마을로 향해 길 잃은 양들을 찾아 구원할 수 있을 것이다.",
  ui_story_5084_50841102_152_dialog_content = "네 힘으로 그들을 구원하고 인도하여, 너의 「드문 피」를 향한 타인의 축복을 손에 넣어라.",
  ui_story_5084_50841102_153_dialog_content = "「드문 피」는 진리의 축복 속에 허물을 씻어낼 것이다.\n그리고 언젠가는 너 역시 수행의 본질을 깨닫고 이해하게 될 것이다.",
  ui_story_5084_50841102_154_dialog_content = "알겠습니다...",
  ui_story_5084_50841102_155_dialog_content = "그래서 이 3년 동안, 저는 곳곳을 다니며 저의 기질을 억누르고,\n다른 사람들의 목소리에 귀를 기울였습니다.",
  ui_story_5084_50841102_156_dialog_content = "그리고 다른 사람들의 고통을 치유하던 저는, 「드문 피」의 힘이 조금씩\n변하고 있음을 깨달았습니다.",
  ui_story_5084_50841102_157_dialog_content = "하지만 조금 전에 그 재봉사 모녀를 구했을 때, 그제서야 전 지난 3년간의 수행이\n결실을 얻었음을 깨달았습니다.",
  ui_story_5084_50841102_158_dialog_content = "진리의 결사에 몸담은 수년간, 저는 줄곧 귀를 막은 채 성토와 참회를\n쏟아 놓는 데만 급급했습니다.",
  ui_story_5084_50841102_159_dialog_content = "그러나 멘토님께서는 제 죄악의 근원을 발견하셨습니다...\n진리의 목소리를 가로막고 있던 것은 끊임없이 계속되는 저의 넋두리였던 것입니다...",
  ui_story_5084_50841102_160_dialog_content = "스스로 되뇌는 미온적인 말들은 제 생각을 형성하고,\n제 죄를 더욱 깊고 무겁게 만들었지요...",
  ui_story_5084_50841102_161_dialog_content = "진리가 제게 현현하지 않았던 것은 저의 깨달음이 너무나 얕았기 때문입니다...",
  ui_story_5084_50841102_162_dialog_content = "진리는 애당초 저의 신념 속에 존재해 왔던 것이었습니다...",
  ui_story_5084_50841102_163_dialog_content = "진리와 고통은 서로 닮아, 결코 누군가를 편애하는 법이 없습니다.",
  ui_story_5084_50841102_164_dialog_content = "무언가를 잃었다면, 잃어야 했기에 그렇게 된 것이고,\n무언가를 얻었다면, 얻어야 했기에 그렇게 된 것입니다.",
  ui_story_5084_50841102_165_dialog_content = "속죄를 하기 위해서는 반드시 실질적인 죄가 있어야 합니다.\n성혈의 은혜를 얻은 것은 모두 신도들이 제게 준 축복인 것이지요.",
  ui_story_5084_50841102_166_dialog_content = "나일즈 씨 말은 하나도 이해 못 했지만...",
  ui_story_5084_50841102_167_dialog_content = "지금 나일즈 씨 표정을 보니까 꼭 따뜻한 물에 목욕하고 나온 것처럼\n마음이 포근해지는 거 같아.",
  ui_story_5084_50841102_168_dialog_content = "멘토님 덕분에... 저는 「드문 피」가 더는 죄악이 아니라 신성한 것임을 믿게 되었습니다.\n진리의 주인께서는 늘 저를 지켜주고 계시기 때문입니다.",
  ui_story_5084_50841102_169_dialog_content = "빅토리아 님께선 틀림없이 네 변화를 기뻐하실 거야.",
  ui_story_5084_50841102_170_dialog_content = "다만, 빅토리아 님 쪽은 상황이 어떻게 되어가고 있는지 모르겠어.",
  ui_story_5084_50841102_171_dialog_content = "난 빅토리아 님을 믿어! 그리고 더 중요한 건... 난 내가 빅토리아 님을 위해\n중요한 일을 할 수 있다고 믿어!",
  ui_story_5084_50841102_172_dialog_content = "멘토님께서도 제 수행이 일단락되었다고 하셨으니,\n저는 이 힘을 가지고 진리의 결사를 위해 중요한 일을 해야 합니다.",
  ui_story_5084_50841102_173_dialog_content = "자, 갑시다. 제 기쁨을 빅토리아 님과 더 많은 신도들에게 전하고 싶습니다.",
  ui_story_5084_50841201_1_dialog_content = "설령 더는 아무도 내 열차에 타지 않는다 해도, 네게 약속할게.\n반드시 아버지를 설득해서 널 아스트라 대륙 여행에 데리고 가겠어.",
  ui_story_5084_50841201_2_dialog_content = "<color=#e8d9bb>덜컹, 덜컹── 덜커덩──</color>",
  ui_story_5084_50841201_3_dialog_content = "...잠깐만 기다려, 창문 좀 닫고 올게.",
  ui_story_5084_50841201_4_dialog_content = "으앗──!",
  ui_story_5084_50841201_5_dialog_content = "<color=#e8d9bb>쾅──!</color>",
  ui_story_5084_50841201_6_dialog_content = "이상해. 요즘 들어 저 기분 나쁜 녀석들이 자꾸 근처를 어슬렁거리고 있어...",
  ui_story_5084_50841201_7_dialog_content = "아버지는 창문만 닫으면 괜찮을 거라고 하셨지만... 그나저나 아버지는 지금 어디 계실까...",
  ui_story_5084_50841201_8_dialog_content = "<color=#e8d9bb>핏빛 달이 높이 걸린 왈라지 마을 위로, 성명제의 자정을 알리는 종소리가 울려 퍼졌다.\n마치 밤낮을 가리지 않는 역사의 시계추처럼...</color>",
  ui_story_5084_50841201_9_dialog_content = "정말 꿈같은 광경이네요. 제 인생의 모든 날이 오늘 같으면 좋을 텐데 말이에요...",
  ui_story_5084_50841201_10_dialog_content = "진리의 결사의 새로운 지도자가 결정되는 오늘 말이야?\n...얼마 전에 누가 목숨을 잃었다고 다른 신도가 그러던데...",
  ui_story_5084_50841201_11_dialog_content = "지도자가 바뀌는 건 딱히 놀랄 일도 아니죠.\n오히려 전 가주들이 왈라키아 혈통이 아닌 신도들을 배제하고 있다는 점을 주목하고 있어요.",
  ui_story_5084_50841201_12_dialog_content = "어쩌면 이 핏빛 달의 붉은 광휘는 오직 그 혈통만을 비추고 있는 걸지도 모르지.",
  ui_story_5084_50841201_13_dialog_content = "진리의 전당에 있는 관에 들어가 주님의 가르침을 듣는 건,\n애초부터 우리가 할 수 있는 일이 아니잖아.",
  ui_story_5084_50841201_14_dialog_content = "그런 혈통론 같은 걸 신봉할 필요는 없어요.\n3년 전만 해도 진리의 주인께서 왈라키아 가문의 아가씨를 거부하셨는걸요...",
  ui_story_5084_50841201_15_dialog_content = "대신 은거해 수행 중이던 한 신도의 몸에 강림하셨죠.\n지금 그 신도는 이미 성도가 돼서 주의 힘으로 사람들을 구제하고 있어요.",
  ui_story_5084_50841201_16_dialog_content = "변두리 마을의 신도라고 하던데, 어쩌면 왈라지 마을 바깥에도\n더 넓은 진리의 땅이 있을지도 모르겠네요.",
  ui_story_5084_50841201_17_dialog_content = "여러모로 시사하는 바가 큰 일이야. 왈라지 마을의 가주들도 변혁을 맞이한 모양이고.",
  ui_story_5084_50841201_18_dialog_content = "만약 오늘 밤에 차기 지도자가 정말로 포르피리오 님이라고 공표된다면,\n진리의 결사의 미래도 더 힘겨워지겠지...",
  ui_story_5084_50841201_19_dialog_content = "세상은 변하고 있고, 진리 또한 변하고 있어요. 부디 진리가 이곳에 축복을 내리길...",
  ui_story_5084_50841201_20_dialog_content = "아직 PlayerName하고 빅토리아 님이 안 보이는데, 혹시 무슨 일이 생긴 건 아니겠지?",
  ui_story_5084_50841201_21_dialog_content = "빅토리아 님께선 지금껏 단 한 번도 약속을 어기신 적이 없는 분입니다.\n보는 눈이 많아서일지도 모르죠. 신도들이 떠나면 그때 나타나실 수도 있습니다.",
  ui_story_5084_50841201_22_dialog_content = "아니, 지금 같은 상황에선 빅토리아 님께서 몸을 숨기셔야 할 이유가 없어.",
  ui_story_5084_50841201_23_dialog_content = "PlayerName도 있으니까, 인파 속에서도 금방 눈에 띄게 되겠지.",
  ui_story_5084_50841201_24_dialog_content = "파우스트 씨 말이 맞아!\n난 오늘 밤 왠지 진리의 결사의 기적을 볼 수 있을 것 같단 예감이 들어!",
  ui_story_5084_50841201_25_dialog_content = "헤헷, 돌아가면 언니한테 말해 줘야지.",
  ui_story_5084_50841201_26_dialog_content = "다만, 마을에 사도들로 인한 인명 피해가 이미 여러 건 발생했는데도,\n신도들은 위험을 무릅쓰고 성명제 의식에 참여하고 있어.",
  ui_story_5084_50841201_27_dialog_content = "아무리 진리의 결사가 서광력 2000년까지 이어 온 성대한 의식이라고는 해도...",
  ui_story_5084_50841201_28_dialog_content = "행진에 참여하는 신도들이 안전할 수 있도록, 제가 철저히 경계하겠습니다.",
  ui_story_5084_50841201_29_dialog_content = "벌써 한참이나 지났는데, 빅토리아 씨는 왜 아직도 안 오시는 거지...",
  ui_story_5084_50841201_30_dialog_content = "다들 봤어? 왈라키아 가문의 아가씨가 의식에 참여하러 오셨어!",
  ui_story_5084_50841201_31_dialog_content = "그러게... 게다가 화려한 옷까지 빼입고 말이야...\n저건 진리의 결사의 규칙에 어긋나는 행동이잖아!",
  ui_story_5084_50841201_32_dialog_content = "(...옷을 갈아입으러 갔던 건가? 어디 있는 거지...?)",
  ui_story_5084_50841201_33_dialog_content = "줄곧 자기 숙부님이랑 불화가 있었으니까, 결사의 규칙을 지키지 않을 만도 하지...",
  ui_story_5084_50841201_34_dialog_content = "저러다 왈라키아 가문이 정말로 가주 자리에서 쫓겨나는 건 아니겠지...?",
  ui_story_5084_50841201_35_dialog_content = "그럴 리가 없잖아? 빅토리아 아가씨는 진리의 결사를 이끌기 위해 돌아오신 거라고 들었거든.",
  ui_story_5084_50841201_36_dialog_content = "정말? 하지만 3년 전 성명제 때 아가씨는...",
  ui_story_5084_50841201_37_dialog_content = "뭐, 누가 알겠어... 관에 들어간 건 우리가 아니라 빅토리아 아가씨잖아.",
  ui_story_5084_50841201_38_dialog_content = "그래도... 왠지는 모르겠지만, 몇백 년이 지났어도 난 진리의 결사 지도자는\n왈라키아 가문이 맡아야 마음이 놓이는 것 같아...",
  ui_story_5084_50841201_39_dialog_content = "오래 기다렸지?",
  ui_story_5084_50841201_40_dialog_content = "우와... 비, 빅토리아 씨, 일부러 의식용 예복으로 갈아입은 거야?",
  ui_story_5084_50841201_41_dialog_content = "그것만이 이유는 아냐. 이 옷은 아직 왈라키아 가문을 생각하는 사람들이\n내가 돌아왔단 걸 알고 특별히 보내온 선물이거든.",
  ui_story_5084_50841201_42_dialog_content = "이 솜씨, 한두 사람이 짧은 시간에 완성할 수 있는 수준이 아냐.",
  ui_story_5084_50841201_43_dialog_content = "배후의 제작자들은 이 옷을 통해 기세등등한 가주들을 향한 불만을\n표현하고 싶었던 걸지도 몰라.",
  ui_story_5084_50841201_44_dialog_content = "그러니까 신도들의 그런 기대에 부응하고, 빅토리아 씨한테 진리의 결사를 이끌\n힘이 있다는 걸 증명하기 위해...",
  ui_story_5084_50841201_45_dialog_content = "반드시 그 옷을 입고 오늘 밤에 있는 의식에 참여해야 하는 거야?",
  ui_story_5084_50841201_46_dialog_content = "힘과 옷은 아무 관계도 없어. 예전 옷이든, 새 옷이든, 나의 힘에 걸맞은 복장이니까.",
  ui_story_5084_50841201_47_dialog_content = "하지만 유서 깊은 이 마을엔 마침 사람의 마음을 고무시킬 만한 변화가 부족해.",
  ui_story_5084_50841201_48_dialog_content = "성전, 반지, 핏빛 달처럼, 모든 형식은 그저 그 사람들이 중요하다 여기는 순간을\n나타내는 표식에 불과한 거야.",
  ui_story_5084_50841201_49_dialog_content = "만약 가주들이 이런 눈에 띄는 변화를 두려워한다면, 내가 그들에게 변화를 보여 주겠어.",
  ui_story_5084_50841201_50_dialog_content = "그들 눈에는 여자가 눈부신 모습으로 탈바꿈하는 걸 연약한 과거를 향한\n작별 인사라고 여기거든.",
  ui_story_5084_50841201_51_dialog_content = "음... 아무튼... 옷이 되게 잘 어울린단 얘길 하고 싶었어!",
  ui_story_5084_50841201_52_dialog_content = "PlayerName! PlayerName!",
  ui_story_5084_50841201_53_dialog_content = "너희도 왔구나!",
  ui_story_5084_50841201_54_dialog_content = "후후! 내가 인파 속에서 반짝반짝 빛나는 빅토리아 님을 한 번에 발견했어!",
  ui_story_5084_50841201_55_dialog_content = "멀리서 봤을 땐 진짜 빅토리아 님이 맞는지 믿기 힘들었다니까요.",
  ui_story_5084_50841201_56_dialog_content = "지금은 어떠니?",
  ui_story_5084_50841201_57_dialog_content = "제 눈앞에 계신 건 전보다 훨씬 더 아름다워지신 빅토리아 님이세요!",
  ui_story_5084_50841201_58_dialog_content = "빅토리아 님, 모든 게 순조롭게 진행된 모양이군요. 축하드립니다.",
  ui_story_5084_50841201_59_dialog_content = "나일즈도 큰 변화가 있었던 모양이네.",
  ui_story_5084_50841201_60_dialog_content = "오랜만에 뵙습니다, 빅토리아 님! 이 모든 건 멘토님의 노고 덕분입니다...",
  ui_story_5084_50841201_61_dialog_content = "말씀드리고 싶은 게... 아주 많습니다!",
  ui_story_5084_50841201_62_dialog_content = "그래, 거리에서 널 봤어. 나중에 네가 무엇을 느끼고 깨달았는지 기꺼이 들어줄게.",
  ui_story_5084_50841201_63_dialog_content = "시간이 거의 다 됐어.",
  ui_story_5084_50841201_64_dialog_content = "하지만 빅토리아 님, 조금 전 사도들이 사람들을 해치고 있는 것을 보았습니다...",
  ui_story_5084_50841201_65_dialog_content = "이제 난 왈라지 마을에 전해 내려오는 검은 기사의 전설이 누굴 말하는 건지 알아.",
  ui_story_5084_50841201_66_dialog_content = "가자. 거리의 신도들은 빌헬름이 무사히 지켜 줄 거야.",
  ui_story_5084_50841201_67_dialog_content = "오늘 밤은 진리의 결사의 힘을 보여 줘야 해. 모두 나와 함께 교회로 가도록 해.",
  ui_story_5084_50841201_68_dialog_content = "네!",
  ui_story_5084_50841201_69_dialog_content = "바라건대 진리가 영원히 진리의 결사를 축복하길.",
  ui_story_5084_50841201_70_dialog_content = "<color=#e8d9bb>끼이이익──!</color>",
  ui_story_5084_50841201_71_dialog_content = "사람들이...",
  ui_story_5084_50841201_72_dialog_content = "다 바닥에 쓰러져 있어... 마치...",
  ui_story_5084_50841201_73_dialog_content = "......",
  ui_story_5084_50841201_74_dialog_content = "빅토리아 님, 이 신도들은 이미 숨을 거뒀습니다...",
  ui_story_5084_50841201_75_dialog_content = "......!",
  ui_story_5084_50841201_76_dialog_content = "제가 저들을 구해 보겠습니다... 저들의 고통은 제가 대신 받겠습니다.",
  ui_story_5084_50841201_77_dialog_content = "오오... 왈라키아 가문의 가주와 수하 여러분이 드디어 납셨군.",
  ui_story_5084_50841201_78_dialog_content = "이건 진리의 결사의 성대한 의식이야. 내가 어떻게 자리를 비우겠어.",
  ui_story_5084_50841201_79_dialog_content = "빅토리아...",
  ui_story_5084_50841201_80_dialog_content = "......",
  ui_story_5084_50841201_81_dialog_content = "클라비스 씨의 몸에 수많은 상처가...",
  ui_story_5084_50841201_82_dialog_content = "그게 바로 날 배신한 대가다...",
  ui_story_5084_50841201_83_dialog_content = "뭐든 상관없다... 다 괜찮으니까... 부디 카론과... 아내만은...",
  ui_story_5084_50841201_84_dialog_content = "진리의 전당에서 사람을 해치다니──",
  ui_story_5084_50841201_85_dialog_content = "가만히 있는 게 좋을 거다, 왈라키아──!",
  ui_story_5084_50841201_86_dialog_content = "이 자식!",
  ui_story_5084_50841201_87_dialog_content = "메이, 내 뒤로 오렴.",
  ui_story_5084_50841201_88_dialog_content = "지금쯤 넌 혈족의 규율을 많이 잊어버렸겠지.\n네가 어떤 규율을 어겼는지 아브라함이 알려줄 거다...",
  ui_story_5084_50841201_89_dialog_content = "돌아오지... 말았어야 했다... 빅토리아...",
  ui_story_5084_50841201_90_dialog_content = "이제 와서 내 앞에 나타나 봤자 소용없다. 의식은 이미 끝났다.\n주께 바쳐야 할 「제물」들은 이미 모두 바쳤다.",
  ui_story_5084_50841201_91_dialog_content = "지금은 내 수하들에게 음식을 낭비하면 안 된다고 가르치고 있는 중이지.",
  ui_story_5084_50841201_92_dialog_content = "오로리안은 진리의 주인께서 내리신 선물이야. 넌 그들을 식량으로 여기는 거야?",
  ui_story_5084_50841201_93_dialog_content = "왈라키아 가문의 아가씨, 당신도 깊은 밤에 굶주림을 참지 못하고,\n수하들에게 곳곳을 뒤지며 신선한 피를 찾으라고 하겠지. 아닌가?",
  ui_story_5084_50841201_94_dialog_content = "난 내 몫의 제물은 단 한 방울도 낭비하지 않았다.",
  ui_story_5084_50841201_95_dialog_content = "식량을 낭비하고 날 기만하기까지 한 아브라함과는 하늘과 땅 차이 아닌가, 하하하하하....",
  ui_story_5084_50841201_96_dialog_content = "──!",
  ui_story_5084_50841201_97_dialog_content = "크윽── 으으윽──! 멈춰라... 포르피리오... 그만둬...!",
  ui_story_5084_50841201_98_dialog_content = "빌헬름은 어디 있나?!",
  ui_story_5084_50841201_99_dialog_content = "당장 멈춰, 데이비드 포르피리오!",
  ui_story_5084_50841201_100_dialog_content = "뭐냐? 대신 대답해 줄 생각이냐?",
  ui_story_5084_50841201_101_dialog_content = "가져와.",
  ui_story_5084_50841201_102_dialog_content = "...예, 빅토리아 님.",
  ui_story_5084_50841201_103_dialog_content = "<color=#e8d9bb>덜컹──</color>",
  ui_story_5084_50841201_104_dialog_content = "덩굴인간, 뭘 하는 거냐.",
  ui_story_5084_50841201_105_dialog_content = "...왈라키아 아가씨의 분부대로 이 떠도는 관을...\n포르피리오 님 앞에 가져다 놓았을 뿐입니다.",
  ui_story_5084_50841201_106_dialog_content = "설마 왈라키아 선조의 유해가 정말로 내게 위협이 될 거라고 생각한 건 아니겠지?",
  ui_story_5084_50841201_107_dialog_content = "훗, 아니면 또 빌헬름 왈라키아가 사용했던 수법으로 도망칠 작정인가?",
  ui_story_5084_50841201_108_dialog_content = "관 안에 누워 있는 건 빌헬름이야.",
  ui_story_5084_50841201_109_dialog_content = "......?",
  ui_story_5084_50841201_110_dialog_content = "너희가 잔인하게 목숨을 빼앗아 놓고, 왜 내게 빌헬름의 행방을 묻는 걸까?",
  ui_story_5084_50841201_111_dialog_content = "하하... 참아 주는 데도 한계가 있다...",
  ui_story_5084_50841201_112_dialog_content = "이 병 속에 든 피를 다 마시고 나면, 네게서 양분을 흡수해야 할 지도 모르겠군.",
  ui_story_5084_50841201_113_dialog_content = "자... 조금 더 가까이 와 봐라. 말해. 빌헬름과 대체 무슨 짓을 꾸미고 있는 것이냐.",
  ui_story_5084_50841201_114_dialog_content = "빌헬름은 죽었어.",
  ui_story_5084_50841201_115_dialog_content = "거짓말!",
  ui_story_5084_50841201_116_dialog_content = "빅토리아 씨, 조심해!",
  ui_story_5084_50841201_117_dialog_content = "빅토리아 님께 다가오지 마라!",
  ui_story_5084_50841201_118_dialog_content = "진리를 추구하는 무리를 이룬 자들은 많이 봐 왔지만,\n너희처럼 주인을 간절히 지키는 자들은 흔치 않았지.",
  ui_story_5084_50841201_119_dialog_content = "하지만 날 머저리라 생각하지 마라.\n너와 네 숙부가 살무사와 금꾼을 죽이는 걸 내 눈으로 봤거든.",
  ui_story_5084_50841201_120_dialog_content = "두렵니? 살무사와 금꾼만이 아냐.\n반역을 도모한 너희는 모두 그의 검에 죽음을 맞이하게 될 거야.",
  ui_story_5084_50841201_121_dialog_content = "그러니까 너희가 아무리 고문하고, 살해하고, 매장한다 해도,\n너희는 영원히 빌헬름 왈라키아를 죽일 수 없어.",
  ui_story_5084_50841201_122_dialog_content = "빌헬름이... 죽지 않았다고? 정말로... 살아있는 거냐...?",
  ui_story_5084_50841201_123_dialog_content = "......",
  ui_story_5084_50841201_124_dialog_content = "죽지 않았다고...? 왈라키아는 죽은 후에 무슨 유령으로 변하기라도 한다는 거야?",
  ui_story_5084_50841201_125_dialog_content = "이 세상에 유령 따위는 없다!\n저 사도들은 나 포르피리오의 힘을 흡수해 저렇게 된 것이다...",
  ui_story_5084_50841201_126_dialog_content = "이것이 바로 내가 지배하는 사도의 힘이다...\n혈족의 역사 속에서도 유일무이한 힘이란 말이다!",
  ui_story_5084_50841201_127_dialog_content = "죽음에서 부활하는 능력이라니... 웃기지도 않는군. 절대 불가능하다.",
  ui_story_5084_50841201_128_dialog_content = "넌 왈라키아가 지닌 힘이 선조들의 힘을 계승하거나,\n유물을 통해 미래를 예견하는 것뿐인 줄 아는 모양이구나.",
  ui_story_5084_50841201_129_dialog_content = "......?",
  ui_story_5084_50841201_130_dialog_content = "바로 조금 전, 난 성전과 계약을 맺었고, 이미 진리의 결사의 지도자로 인정을 받았다.",
  ui_story_5084_50841201_131_dialog_content = "신도들은 무릎을 꿇고, 경건한 마음으로 찬송하며 진리로 돌아갔지...",
  ui_story_5084_50841201_132_dialog_content = "이 감각이 뭔지 난 잘 알고 있다. 선택받은 왈라키아의 혈통?\n그건 왈라키아 가문이 권력을 장악하기 위한 말장난일 뿐이다!",
  ui_story_5084_50841201_133_dialog_content = "나 포르피리오는 이 특별한 영광을 손에 넣고, 진리의 결사를 다시금\n진리의 무리로 되돌려야 할 책임이 있다.",
  ui_story_5084_50841201_134_dialog_content = "흡혈귀는... 피와 밤의 지배자다.\n내가 어째서 빛 아래 살아가는 것들의 통치에 굴복해야 한단 말이냐.",
  ui_story_5084_50841201_135_dialog_content = "나는 이 특별한 영광을 받아들여, 선조들이 정한 방식대로 모든 이를 구제해야 한다.\n그것이 바로... 성전이 내게 전한 계시다!",
  ui_story_5084_50841301_1_dialog_content = "<color=#e8d9bb>이성을 잃을 정도로 격렬한 전투가 계속되던 중, 관이 뒤집혔다.\n그리고 모두의 눈에 들어온 광경은...</color>",
  ui_story_5084_50841301_2_dialog_content = "<color=#e8d9bb>마치 운명으로 그렇게 정해져 있듯...\n새로운 성전이 나타나 빅토리아의 발치에 떨어지는 모습이었다.</color>",
  ui_story_5084_50841301_3_dialog_content = "진리는 구원의 길을 이루길 원하고, 내가 자신의 대행자가 되길 바라는 모양이네.",
  ui_story_5084_50841301_4_dialog_content = "재앙의 서여, 현현하라!",
  ui_story_5084_50841301_5_dialog_content = "......",
  ui_story_5084_50841301_6_dialog_content = "...? 그건 뭐냐?",
  ui_story_5084_50841301_7_dialog_content = "미래를 예지하는 성전을 통해 미래를 엿볼 수는 있겠지.\n하지만 넌 걸음마를 배우는 아기처럼, 성전을 제대로 다루지 못해.",
  ui_story_5084_50841301_8_dialog_content = "반면 이 원시의 강에서 건져 올린 재앙의 서는 모든 것을 알고... 모든 것을 할 수 있지.",
  ui_story_5084_50841301_9_dialog_content = "「새로운 장」이 예고되었으니, 이제 내가 페이지를 넘겨 주겠어!",
  ui_story_5084_50841301_10_dialog_content = "이 책에서 네가 언제 태어났고, 언제 죽고, 언제 무릎 꿇고 참회할 것이라 예언하는지...\n보고 싶어?",
  ui_story_5084_50841301_11_dialog_content = "......!",
  ui_story_5084_50841301_12_dialog_content = "포르피리오와 거래한 다른 가주들도 잘 듣도록 해.",
  ui_story_5084_50841301_13_dialog_content = "진리의 결사 열두 가주 중 세 번째인 포르피리오는...",
  ui_story_5084_50841301_14_dialog_content = "핏빛 달이 뜰 때 피에 굶주려, 신도를 대량으로 살해하여 그들의 피를 취했고,\n가문에 전해 내려오는 황금 담뱃대로 사도를 조종했어.",
  ui_story_5084_50841301_15_dialog_content = "그리고 진리의 결사에서 추방된 열세 번째 가주와 결탁해,\n왈라지 마을에 사악한 신을 끌어들이고 신도들을 학살했어.",
  ui_story_5084_50841301_16_dialog_content = "그 추방된 아이를 말하는 건가...?",
  ui_story_5084_50841301_17_dialog_content = "열세 번째 가주는 한때 어둠의 밑바닥에서 강림의 땅을 찾았고...",
  ui_story_5084_50841301_18_dialog_content = "「사악한 신」을 마을로 끌어들여 신도들을 죽이고, 진리의 주인의 강림 의식을 망쳤지.",
  ui_story_5084_50841301_19_dialog_content = "데이비드 포르피리오는 그걸 위한 기회를 만들기 위해, 신도들의 피를 잔뜩 마셨어.",
  ui_story_5084_50841301_20_dialog_content = "이런 중죄들을 저질러 놓고도, 아직까지 진리의 결사의 지도자는 물론,\n가주의 자격이 있다고 생각하는 거야?",
  ui_story_5084_50841301_21_dialog_content = "......",
  ui_story_5084_50841301_22_dialog_content = "지금 무슨 헛소리를 하는 거냐!",
  ui_story_5084_50841301_23_dialog_content = "<color=#FFB400>왈라키아의 반지</color> 아래, 네 <color=#FFB400>본질</color>을 드러내라!",
  ui_story_5084_50841301_24_dialog_content = "──!",
  ui_story_5084_50841301_25_dialog_content = "나...나는 열세 번째 가주와 결탁해, 성도의 신선한 피를 마시면\n내 힘이 강해질 거라 생각했다.",
  ui_story_5084_50841301_26_dialog_content = "다른 가주들은 진리의 주인께 축복을 받아, 다른 것들을 마실 수 있었지만...",
  ui_story_5084_50841301_27_dialog_content = "오직 나만은... 피를 향한 갈망이 점점 커졌고,\n이제는 이 부유하는 피의 병 없이는 살 수 없는 지경에 이르렀지.",
  ui_story_5084_50841301_28_dialog_content = "이해를 못 하는 모양이네. 그 가주는 애초부터 이 모든 걸 너와의 계약이라고 여기지 않았어.",
  ui_story_5084_50841301_29_dialog_content = "널 죽이는 것과 만물을 죽이는 것 사이엔 별반 차이가 없어.\n그 가주는 그저 널 이용했을 뿐이야.",
  ui_story_5084_50841301_30_dialog_content = "<color=#FFB400>그녀</color>는 이클립스에 의탁해, <color=#FFB400>팬텀</color> 중 하나가 됐어...\n네가 그런 그녀를 이해할 수 있다고 생각한 거야?",
  ui_story_5084_50841301_31_dialog_content = "다, 닥쳐라──!",
  ui_story_5084_50841301_32_dialog_content = "빅토리아 왈라키아... 반지를 조종해 날 속박하다니...",
  ui_story_5084_50841301_33_dialog_content = "아, 아니야... 예전의 그 반지는 그렇지 않았단 말이다...",
  ui_story_5084_50841301_34_dialog_content = "난 이미 반지를 지배하고 있어. 왈라키아 가문의 모든 선조가 나와 함께하시니까.",
  ui_story_5084_50841301_35_dialog_content = "지금 네가 마주하고 있는 건 왈라키아 일족의 힘이야. 우리의 앞에서 네 죄를 인정해!",
  ui_story_5084_50841301_36_dialog_content = "하하... 하하하하! 내가...",
  ui_story_5084_50841301_37_dialog_content = "내가 빌헬름을 죽였다!",
  ui_story_5084_50841301_38_dialog_content = "하지만 그건 진리의 결사의 진정한 장애물을 제거하기 위해서였다!",
  ui_story_5084_50841301_39_dialog_content = "뒤틀린 마음을 지닌 외로운 늑대... 형을 살해한 왈라키아의 차남이\n어떻게 진리의 결사의 지도자가 될 수 있겠냔 말이다!",
  ui_story_5084_50841301_40_dialog_content = "빌헬름은... 아무도 죽이지 않았다...!",
  ui_story_5084_50841301_41_dialog_content = "네 녀석이 끼어들 자리가 아니다!",
  ui_story_5084_50841301_42_dialog_content = "──!",
  ui_story_5084_50841301_43_dialog_content = "성전은 왈라키아의 성물이다...\n성전은 다루는 이에게 힘을 주고, 내가 미래를 두려워하지 않게 해 준다.",
  ui_story_5084_50841301_44_dialog_content = "설령 내가 피에 굶주리고, 사람을 죽인다 해도, 성전은 나를 인정하고 내게 힘을 주지.",
  ui_story_5084_50841301_45_dialog_content = "진리의 결사의 그 누구도 날 막지 못한다!",
  ui_story_5084_50841301_46_dialog_content = "핏빛 성전이여──! 내게 왈라키아를 숙청할 힘을 다오!",
  ui_story_5084_50841301_47_dialog_content = "......",
  ui_story_5084_50841301_48_dialog_content = "핏빛 성전이여──!",
  ui_story_5084_50841301_49_dialog_content = "넌 처음부터 끝까지 왈라키아 가문이 진리의 결사의 지도자가 된 이유를 이해하지 못했어.",
  ui_story_5084_50841301_50_dialog_content = "왈라키아 일족엔 단 한 번도 성전의 힘을 가지고 남을 해친 자는 없었어.",
  ui_story_5084_50841301_51_dialog_content = "오히려 성전은 왈라키아 일족의 피를 흡수해 미래를 계시해 왔어.",
  ui_story_5084_50841301_52_dialog_content = "......?",
  ui_story_5084_50841301_53_dialog_content = "선조들부터 나의 아버지와 어머니, 빌헬름, 그리고 나 역시 마찬가지야.",
  ui_story_5084_50841301_54_dialog_content = "이 성물들엔 역대 가주들의 의식이 남아 있어.\n이성적인 의식도... 광기에 휩싸인 의식도 말이야...",
  ui_story_5084_50841301_55_dialog_content = "따라서 계약자는 강인한 정신력으로 그 속삭임들을 떨쳐 내야 해.\n그래야만 진리의 경지에 도달할 수 있고...",
  ui_story_5084_50841301_56_dialog_content = "더 높은 차원에서 진리의 주인이 내리신 계시를 해석할 수 있는 거야!",
  ui_story_5084_50841301_57_dialog_content = "넌... 대체 어떤 계시를 받은 거지...?",
  ui_story_5084_50841301_58_dialog_content = "......",
  ui_story_5084_50841301_59_dialog_content = "무, 무슨 짓이냐...?!",
  ui_story_5084_50841301_60_dialog_content = "가주 회의 때 했던 말도 잊어버렸어?",
  ui_story_5084_50841301_61_dialog_content = "빅토리아, 어떤 계시를 받았지?",
  ui_story_5084_50841301_62_dialog_content = "<color=#FF0000>파벌을 숙청하라.</color>",
  ui_story_5084_50841301_63_dialog_content = "......!",
  ui_story_5084_50841301_64_dialog_content = "진리의 신도들이여. 함께 맹세를 낭독하자.",
  ui_story_5084_50841301_65_dialog_content = "이 나일즈, 목숨을 바쳐 낭송하겠습니다!",
  ui_story_5084_50841301_66_dialog_content = "저도 「베이비」랑 같이 낭송할게요!",
  ui_story_5084_50841301_67_dialog_content = "신도 파우스트, 빅토리아 님과 함께 낭송하겠습니다!",
  ui_story_5084_50841301_68_dialog_content = "데이비드, 패배를 인정해라...",
  ui_story_5084_50841301_69_dialog_content = "너도 겁쟁이냐? 진리의 결사는 반드시 포르피리오가 통치해야 한다!",
  ui_story_5084_50841301_70_dialog_content = "...우린 이만 실례하도록 하지.",
  ui_story_5084_50841301_71_dialog_content = "너흰 분명히 내게 약속했다──!",
  ui_story_5084_50841301_72_dialog_content = "끝이야. 우리 계약은 핏빛 달이 떠 있을 때까지였잖아. 역시 내가 조건을 맞게 걸었네.\n아하하하... 신선한 피를 자주 마실 수 있길 바랄게.",
  ui_story_5084_50841301_73_dialog_content = "사도들이여──!",
  ui_story_5084_50841301_74_dialog_content = "진리의 결사의 가주들이여, 함께 목도하라──",
  ui_story_5084_50841301_75_dialog_content = "......",
  ui_story_5084_50841301_76_dialog_content = "모든 신도의 핏속에 흐르는 진리의 영혼이여, 일어나라!",
  ui_story_5084_50841301_77_dialog_content = "나와 함께 진리의 소리를 들어라!",
  ui_story_5084_50841301_78_dialog_content = "나를 따라 춤추는 기나긴 강의 흐름이여, 허공을 깨트리고 이곳에 모여라.",
  ui_story_5084_50841301_79_dialog_content = "나는 곧 진리의 주인께서 손에 쥐신 주문이니, 성지에서 주의 현현을 기다리노라.",
  ui_story_5084_50841301_80_dialog_content = "나는 빛을 맞이하는 자이자, 어둠의 연주자라!\n영생의 경계에서 다시금 죽은 별에 다시금 시작을 부여하리라.",
  ui_story_5084_50841301_81_dialog_content = "지극히 거룩하신 진리의 주인이시여, 바라건대 왈라키아의 피에 계시를 흘리사,\n제게 신의 나라를 열 힘을 주소서!",
  ui_story_5084_50841301_82_dialog_content = "「성혈」이 굳기 시작했습니다...\n고난을 받는 자여, 고해하세요!",
  ui_story_5084_50841301_83_dialog_content = "댕댕이덩굴이 되살아났어...\n진리의 주인님! 부디 메이에게 강림해 주세요!",
  ui_story_5084_50841301_84_dialog_content = "이것이야말로 진정한 악몽, 나를 향해 오라! 태고의 힘을 해방할지니!",
  ui_story_5084_50841301_85_dialog_content = "원시의 강을 잇는 다리여, 우주의 진리를 꿰뚫는 「조종사」여, 우리에게 힘을 빌려주소서!",
  ui_story_5084_50841301_86_dialog_content = "뭐?! 무, 무슨 다리를 잇고... 진리를 꿰뚫는다는 건지는 잘 모르겠지만...",
  ui_story_5084_50841301_87_dialog_content = "난 당연히 너흴 도울 거야!",
  ui_story_5084_50841301_88_dialog_content = "진리의 주인께서 네 헌신을 보셨을 거야. 이 계약은 맺어졌어.\n이제 우리와 함께 조용히 신의 강림을 기다리렴.",
  ui_story_5084_50841302_1_dialog_content = "똑같이 피에 굶주리고... 추하고... 태어날 때부터 저주받은 종족이건만...",
  ui_story_5084_50841302_2_dialog_content = "너희 왈라키아 가문은 뭘 믿고 계속 그 자리에 앉을 수 있는 거냐...",
  ui_story_5084_50841302_3_dialog_content = "네가 그 질문을 했을 때부터, 답은 이미 네 눈앞에 있었어.",
  ui_story_5084_50841302_4_dialog_content = "왈라키아...",
  ui_story_5084_50841302_5_dialog_content = "피를 향한 굶주림, 긴 삶, 저주, 힘을 얻는 동시에 대가를 치러야 하는 피의 일족...",
  ui_story_5084_50841302_6_dialog_content = "그 생각들은 내가 태어났을 때부터 날 따라다니며, 날 형성해 왔어.",
  ui_story_5084_50841302_7_dialog_content = "하지만 얼마 전에 난 진리를 깨달았어. 내가 겪은 모든 일들은 대가가 아니라,\n자격을 갖춘 자로서 받은 선물이자 인도였던 거야.",
  ui_story_5084_50841302_8_dialog_content = "진리의 주인께선 피의 일족을 선택하셨고, 변혁을 이끌 힘과 시대를 열어갈 기회를\n선물로 주셨어.",
  ui_story_5084_50841302_9_dialog_content = "암귀, 구문명의 무기, 또는 사악한 신...\n그 어떤 것이라도 모두 오로리안의 존망을 위협할 수 있어.",
  ui_story_5084_50841302_10_dialog_content = "오로리안들 사이에도 너처럼 주를 모독하는 사악한 존재가 많다는 사실은\n더더욱 말할 필요도 없겠지.",
  ui_story_5084_50841302_11_dialog_content = "왈라지 마을 밖으로 나가 물의 흐름과 별들의 형상을 관찰하고...",
  ui_story_5084_50841302_12_dialog_content = "이 「은총받은」 고독한 별 아이올리아가 주의 눈 속에서 어떻게 움직이고 있는지\n관측해 본 적이 없다면...",
  ui_story_5084_50841302_13_dialog_content = "이 고독한 별이 역사의 틈바구니에서 이미 여러 번 멸망을 반복해 왔단 사실도\n영원히 이해하지 못할 거야.",
  ui_story_5084_50841302_14_dialog_content = "오로리안이 다시 종언을 부르는 힘을 마주했을 때,\n오직 주께서 선택하신 왈라키아의 혈족만이 아이올리아의 멸망을 막을 수 있어.",
  ui_story_5084_50841302_15_dialog_content = "그리고 미지의 공포 앞에서 더 높은 위격으로 물리칠 수 있느냐가 곧\n사람을 선택하는 기준이 되지.",
  ui_story_5084_50841302_16_dialog_content = "데이비드 포르피리오, 넌 피의 일족으로서 이 특별한 영광을 얻고도 진리를 깨닫지 못했어.\n그러니 응당 주께서 주신 힘을 되돌려드려야 해.",
  ui_story_5084_50841302_17_dialog_content = "깨달음이나 진리의 주인의 선택은 상관없다... 피의 일족은 오직 왈라키아만 인정하지...",
  ui_story_5084_50841302_18_dialog_content = "포르피리오도 원래는 왈라키아를 선조로 둔 후예였건만...",
  ui_story_5084_50841302_19_dialog_content = "나의 선대는 왈라키아의 탄압으로 인해 이름을 잃었고...\n결국 나는 인정받을 수 없게 되었다...",
  ui_story_5084_50841302_20_dialog_content = "허나 수백 년이 지났는데도, 혈족은 바뀐 것이 없다. 네 깨달음은 논할 가치조차 없다...",
  ui_story_5084_50841302_21_dialog_content = "너... 왈라키아는... 영원히 피의 일족의 숙명에서 벗어나지 못할 것이다...",
  ui_story_5084_50841302_22_dialog_content = "흐하하... 하하... 하...",
  ui_story_5084_50841302_23_dialog_content = "......",
  ui_story_5084_50841302_24_dialog_content = "왈라키아 아가씨, 아니... 빅토리아 님...",
  ui_story_5084_50841302_25_dialog_content = "정말로 마을 밖을 여행하다가 주님의 계시를 받으신 겁니까...?",
  ui_story_5084_50841302_26_dialog_content = "우리 일족은 고대 유물을 수많이 보유하고 있습니다.",
  ui_story_5084_50841302_27_dialog_content = "그 속삭임들이 날 통제하는 건 아닌지, 그리고 나 자신이 진리의 주인께서 주신 힘에\n합당한 자인지 어떻게 판단해야 합니까?",
  ui_story_5084_50841302_28_dialog_content = "진리의 결사는 예전부터 혈족이 지닌 강한 정신력을 통해 성장해 왔어.\n그 고대 유물들과 공명할 수 있다는 것 자체가 이미 주께서 내리신 선물이야.",
  ui_story_5084_50841302_29_dialog_content = "하지만 오랜 세월, 가주들의 권력 다툼과 안일한 삶으로 혈통에 잡념이 스며들었고,\n유물을 통해 후손들에게 전해졌어.",
  ui_story_5084_50841302_30_dialog_content = "수많은 유물들과 공명을 한 후에 알게 된 사실이지만,\n사실 그 안에는 광기와 고통스러운 외침 외에는 아무것도 존재하지 않아.",
  ui_story_5084_50841302_31_dialog_content = "오로리안과 유물이 서로를 속박하는 본질은 두려움이야.",
  ui_story_5084_50841302_32_dialog_content = "왈라키아의 계승자들은 매일 밤, 이 두려움에 서성이다가,\n옷 너머의 피부와 마음에 겹겹의 상처가 쌓이게 되었지...",
  ui_story_5084_50841302_33_dialog_content = "난 끊임없이 고서와 문건을 찾아읽고, 이성적인 오로리안의 지식으로\n우리를 광기에 휩싸이게 만드는 본능을 다스렸어.",
  ui_story_5084_50841302_34_dialog_content = "그래서 난 그 속삭임들의 안개를 한 겹씩 걷어내고,\n진리의 주인의 품에 도달할 수 있었던 거야.",
  ui_story_5084_50841302_35_dialog_content = "계속 질문을 던지고 탐구하며, 지식의 힘으로 속삭임을 억눌러서,\n끝내 속삭임들이 날 두려워하고 굴복하게 만들었어. 난 이게 올바른 길이라고 생각해.",
  ui_story_5084_50841302_36_dialog_content = "...빅토리아 님의 가르침을 삼가 받들겠습니다.",
  ui_story_5084_50841302_37_dialog_content = "하지만 그게 혈족만의 특권은 아니란 사실도 말해주려고 해.",
  ui_story_5084_50841302_38_dialog_content = "바깥세상을 여행하면서, 난 혈족이 아닌 오로리안 중에서도 특별한 유물을 끌어당기는 듯한\n신비한 힘을 지닌 이들이 있다는 사실을 발견했어.",
  ui_story_5084_50841302_39_dialog_content = "그들의 유물은 바퀴일 수도... 눈동자일 수도 있고...",
  ui_story_5084_50841302_40_dialog_content = "덩굴일 수도... 종이일 수도 있지...",
  ui_story_5084_50841302_41_dialog_content = "애완동물일 수도... 아니면 가방일 수도 있고...",
  ui_story_5084_50841302_42_dialog_content = "모두 조종하는 이에 따라 굉장한 의식의 잠재력을 발휘했어.",
  ui_story_5084_50841302_43_dialog_content = "형태를 굳혀 암귀를 죽일 수 있는 피, 너흰 본 적 있을까?",
  ui_story_5084_50841302_44_dialog_content = "...마침 제자 한 명이 전에 거리에서 그런 신도를 본 적이 있다고 했습니다.",
  ui_story_5084_50841302_45_dialog_content = "......",
  ui_story_5084_50841302_46_dialog_content = "그런 신도들이 세상 곳곳에 퍼져 있어. 진리의 결사는 오로리안들에게 나아가 진리를 전파하고,\n그 힘들을 진리의 결사로 받아들여야만 해.",
  ui_story_5084_50841302_47_dialog_content = "계시를 받은 이는 이미 모습을 드러냈지만, 그들은 아직 세상 곳곳에 흩어져 있고,\n그 계시가 무엇을 의미하는지도 모르고 있지.",
  ui_story_5084_50841302_48_dialog_content = "우리 피의 일족은 그런 계시들을 모아, 그들과 함께 진리의 주인께 전해드려야 해.\n부디 주께서 강림하셔서 오로리안의 미래를 이끌어 주시길 바란다고.",
  ui_story_5084_50841302_49_dialog_content = "만약 그런 것이라면... 왈라지 마을을 떠나 오로리안들에게 진리를 전파하는 일에\n저도 찬성하겠습니다...",
  ui_story_5084_50841302_50_dialog_content = "신도들을 널리 받아들여, 힘을 모아야겠군요...",
  ui_story_5084_50841302_51_dialog_content = "하지만 진리의 주인께 대체 어떤 목소리를 전해야 하는 것입니까?",
  ui_story_5084_50841302_52_dialog_content = "만약 진리의 결사엔 성물을 통해 원시의 강에 도달하고, 심지어 그런 성물들의 힘을\n지휘할 수 있는 「조종사」가 있다는 사실을 내가 말해 준다면...",
  ui_story_5084_50841302_53_dialog_content = "너희 모두 진리의 결사의 미래를 기대하게 될까?",
  ui_story_5084_50841302_54_dialog_content = "조...종...사...?",
  ui_story_5084_50841302_55_dialog_content = "아니, 잠깐만... 난 진리의 결사에 가입한다고 한 적 없어!",
  ui_story_5084_50841302_56_dialog_content = "아이테르, 촛대를 내게 줘.",
  ui_story_5084_50841302_57_dialog_content = "...어? 근데 여긴 사람이 너무 많은데...",
  ui_story_5084_50841302_58_dialog_content = "이리 줘.",
  ui_story_5084_50841302_59_dialog_content = "......",
  ui_story_5084_50841302_60_dialog_content = "이 청년은... 진리의 결사의 맹우, 아이테르야.",
  ui_story_5084_50841302_61_dialog_content = "어, 음... 여러분, 안녕하세요...",
  ui_story_5084_50841302_62_dialog_content = "아이테르... 들어 본 적 있습니다.\n콜로서스를 조종하고, 감응할 수 있는 힘을 가진 종족 말이지요.",
  ui_story_5084_50841302_63_dialog_content = "아이테르님, 방금까지 계속 여기 계셨던 것입니까...?",
  ui_story_5084_50841302_64_dialog_content = "음... 정확히 말하자면... 대부분 계속 여기 있긴 했는데,\n이런저런 이유로 모습을 드러낼 수 없었어요.",
  ui_story_5084_50841302_65_dialog_content = "감응 능력은... 설마 혈족의 공명 능력과 같은 것입니까...?",
  ui_story_5084_50841302_66_dialog_content = "달라.",
  ui_story_5084_50841302_67_dialog_content = "내가 말했듯이, 혈족은 피를 통해 성물과 공명해.",
  ui_story_5084_50841302_68_dialog_content = "하지만 아이테르의 감응은 실질적으론 혈족보다 더 높은 차원의 힘을 다루어...\n그리고 그 차원의 힘 역시 오로리안의 능력을 기초로 하고 있고...",
  ui_story_5084_50841302_69_dialog_content = "...원시의 강 말씀이십니까?",
  ui_story_5084_50841302_70_dialog_content = "세상에! 빅토리아 님... 고대의 문서를 손에 넣으신 겁니까?",
  ui_story_5084_50841302_71_dialog_content = "아니, 고대의 문서는 지금껏 아무도 손에 넣지 못했고, 그 누구도 행방을 알지 못해...",
  ui_story_5084_50841302_72_dialog_content = "하지만 고대의 문서를 움직이는 원시의 강은...\n지금 상황으로 본다면 누군가 다녀간 게 분명해.",
  ui_story_5084_50841302_73_dialog_content = "난 그곳으로 향할 거야.\n그래서 이 마을의 가주인 당신들에게 미래의 왈라지 마을을 부탁하고 싶어.",
  ui_story_5084_50841302_74_dialog_content = "지도자의 가르침을 삼가 받들겠습니다. 전해 주신 진리를 깊이 깨닫도록 하겠습니다.",
  ui_story_5084_50841302_75_dialog_content = "...그게... 사실...인가? 원시의 강에 다녀온 사람이 있다고...?",
  ui_story_5084_50841302_76_dialog_content = "클라비스 아브라함, 당신은 그때 내게 빌헬름을 죽였다는 사실을 고백해야 할지 망설였어.",
  ui_story_5084_50841302_77_dialog_content = "......",
  ui_story_5084_50841302_78_dialog_content = "클라비스, 오늘 널 찾아온 건 네게 빌리고 싶은 물건이 있어서다.",
  ui_story_5084_50841302_79_dialog_content = "...검은 상자, 「파리아」 말이냐?",
  ui_story_5084_50841302_80_dialog_content = "그래.",
  ui_story_5084_50841302_81_dialog_content = "설마 핏빛 성전을 손에 넣으려는 거냐?!",
  ui_story_5084_50841302_82_dialog_content = "핏빛 성전이 무덤에 남겨져 있다면, 언젠가는 저 흡혈귀의 손아귀에 들어가고 말겠지.",
  ui_story_5084_50841302_83_dialog_content = "그자는... 그럴 자격이 없다.",
  ui_story_5084_50841302_84_dialog_content = "그건 왈라키아 가문의 역대 지도자들이 가주들의 심장에 낙인을 남겼기 때문이지.",
  ui_story_5084_50841302_85_dialog_content = "허나 지금 빅토리아는 아직 자신의 피에 얼마나 중요한 힘이 잠들어 있는지\n깨닫지 못하고 있다.",
  ui_story_5084_50841302_86_dialog_content = "게다가 나의 과거는 이미 왈라키아의 신성성을 더럽혔고,\n저 가주들은 호시탐탐 내 자리를 노리고 있지.",
  ui_story_5084_50841302_87_dialog_content = "어느 날 내가 없어진다면, 가주들은 빅토리아를 내버려두지 않을 거다.",
  ui_story_5084_50841302_88_dialog_content = "게다가 포르피리오가 이끄는 진리의 결사는 반드시 세상에 큰 재앙을 가져올 것이다.",
  ui_story_5084_50841302_89_dialog_content = "빌헬름, 그 일은...",
  ui_story_5084_50841302_90_dialog_content = "오직 성명제의 밤에 핏빛 달이 덩굴을 비출 때에만,\n왈라키아의 무덤이 가주들에게 문을 열어 주겠지.",
  ui_story_5084_50841302_91_dialog_content = "허나 그때까지 기다리면 너무 늦는다.\n우린 만문의 열쇠, 검은 상자 파리아의 가능성에 대해 논의한 적이 있었지.",
  ui_story_5084_50841302_92_dialog_content = "형님이 그걸 네게 맡긴 건, 어쩌면 절친한 친구인 너를 통해,\n내가 특정한 시기에 성전을 가져가게 하기 위해서였을 지도 모른다.",
  ui_story_5084_50841302_93_dialog_content = "......",
  ui_story_5084_50841302_94_dialog_content = "클라비스, 지금 그 침묵은 무슨 의미지?",
  ui_story_5084_50841302_95_dialog_content = "...빌헬름, 검은 상자 파리아로 무덤의 문을 열 수 있다곤 해도...\n가주들을 증인으로 세우지 않고 성전을 취하는 것은 가주들과의 계약을 저버리는 일이다.",
  ui_story_5084_50841302_96_dialog_content = "알고 있다.",
  ui_story_5084_50841302_97_dialog_content = "그런데도 내게 계약을 어기겠단 결심을 알려 주는 것은...\n대체 무슨 생각인 거냐, 빌헬름...",
  ui_story_5084_50841302_98_dialog_content = "...빅토리아가 올해 몇 살이지?",
  ui_story_5084_50841302_99_dialog_content = "그건 왜 묻는 거냐.",
  ui_story_5084_50841302_100_dialog_content = "자기밖에 모르고, 야심으로 가득하던 네가 벌써 몇 해 동안이나 빅토리아를 돌보고...",
  ui_story_5084_50841302_101_dialog_content = "이제는 남을 걱정할 줄 아는 어른이 되었다.",
  ui_story_5084_50841302_102_dialog_content = "하하... 우리가 평소에 어떻게 지내는지 안다면 그런 소리는 못 할 거다.",
  ui_story_5084_50841302_103_dialog_content = "빌헬름, 내가 어째서 옛 마을로 거처를 옮겼는지 그 이유를 알고 있나?",
  ui_story_5084_50841302_104_dialog_content = "의심할 여지 없이 카론을 위해서겠지.",
  ui_story_5084_50841302_105_dialog_content = "그래, 빌헬름. 나와 아내는 이제 더는 진리의 결사의 일에 관여하고 싶지 않다.\n카론을 진리의 결사의 일원으로 만들 생각은 더더욱 없다.",
  ui_story_5084_50841302_106_dialog_content = "위축됐군.",
  ui_story_5084_50841302_107_dialog_content = "아니, 빌헬름. 난 오히려 카론을 위해 힘든 걸음을 한 발짝 내디딘 거다.",
  ui_story_5084_50841302_108_dialog_content = "만약 아내와 카론의 미래가 어둠으로 뒤덮이지 않게 하려면,\n반드시 내게 검은 상자 파리아를 건네야 한다면 어쩔 셈이지?",
  ui_story_5084_50841302_109_dialog_content = "......",
  ui_story_5084_50841302_110_dialog_content = "오직 왈라키아가 성전을 손에 넣을 때, 진리의 결사는 활로를 얻는다.\n내가 이어받은 여러 기억 속에서도, 오직 성전을 든 왈라키아만이 변혁을 가져올 수 있었다!",
  ui_story_5084_50841302_111_dialog_content = "왠지 다시 그때의 야심만만한 모습으로 돌아간 것 같군...",
  ui_story_5084_50841302_112_dialog_content = "설마 그때 널 잠식하려던 광기 어린 속삭임들이 네게 불러온 처벌로는 부족했던 거냐?",
  ui_story_5084_50841302_113_dialog_content = "그래, 내겐 야심이 있다! 하지만 그게 뭐가 어쨌다는 거냐!",
  ui_story_5084_50841302_114_dialog_content = "재능 있고, 강한 형에게 패했다고 계속 어둠 속에서 자기연민에 빠져 살라는 거냐?\n아니! 절대 그럴 순 없다!",
  ui_story_5084_50841302_115_dialog_content = "......",
  ui_story_5084_50841302_116_dialog_content = "...미안하다, 클라비스. 내가 실언을 했군.",
  ui_story_5084_50841302_117_dialog_content = "내가 하려던 말은... 이번에는 내가 아니라, 빅토리아를 위해서라는 거다.",
  ui_story_5084_50841302_118_dialog_content = "그래도 그건 안 된다, 빌헬름...",
  ui_story_5084_50841302_119_dialog_content = "대체 뭘 두려워하고 있는 거냐, 클라비스. 상황이 점점 잘못되고 있다는 걸 모르겠나?",
  ui_story_5084_50841302_120_dialog_content = "포르피리오와 그 가주들은 왈라키아 혈족에서 분가한 뒤로 더는 계율을 지키지 않게 되었다...",
  ui_story_5084_50841302_121_dialog_content = "규율을 준수하는 게 너 하나뿐이라면, 그게 대체 무슨 의미가 있지?",
  ui_story_5084_50841302_122_dialog_content = "혈족의 계율은 언제나 감옥에 불과했다!\n지금 진리의 결사는 너와 나, 그리고 마을 사람들에겐 재앙이나 다름없다.",
  ui_story_5084_50841302_123_dialog_content = "피를 갈망하는 건 피의 일족의 본성... 너나 나나 마찬가지지.\n다만 우린 운이 좋았을 뿐이야.",
  ui_story_5084_50841302_124_dialog_content = "...언제부터 너까지 운명에 굴복한 거냐?",
  ui_story_5084_50841302_125_dialog_content = "그런 식으로 말하지 마라, 빌헬름. 난 그저 사실을 부정하고 싶지 않을 뿐이니까...",
  ui_story_5084_50841302_126_dialog_content = "그 열쇠는 널 해치게 될 거다.",
  ui_story_5084_50841302_127_dialog_content = "...충고는 하면서도, 도울 생각은 없다는 거군. 그런가?",
  ui_story_5084_50841302_128_dialog_content = "......",
  ui_story_5084_50841302_129_dialog_content = "괜찮다, 클라비스. 방법은 내가 알아서 찾겠다.",
  ui_story_5084_50841302_130_dialog_content = "난 빌헬름에게 파리아를 건네지 않았다... 그때, 난 빌헬름을 해칠 생각은 전혀 없었다...",
  ui_story_5084_50841302_131_dialog_content = "그저 성명제 밤에, 빌헬름이 가주들의 손에 살해당하는 모습을 지켜보기만 하면...\n그러면 될 거라고 생각했으니까...",
  ui_story_5084_50841302_132_dialog_content = "......",
  ui_story_5084_50841302_133_dialog_content = "<size=45>악──!</size>",
  ui_story_5084_50841302_134_dialog_content = "하하하... 하하하하하...",
  ui_story_5084_50841302_135_dialog_content = "클라...비스...",
  ui_story_5084_50841302_136_dialog_content = "미안하다... 빌헬름...",
  ui_story_5084_50841302_137_dialog_content = "난 카론에게 깨끗한 미래를 주어야만 한다....",
  ui_story_5084_50841302_138_dialog_content = "빅토리아를 돌본 적 있는 너라면 날 이해할 수 있겠지.",
  ui_story_5084_50841302_139_dialog_content = "빅토...리아...",
  ui_story_5084_50841302_140_dialog_content = "훗...",
  ui_story_5084_50841302_141_dialog_content = "미안하다...!",
  ui_story_5084_50841302_142_dialog_content = "하하하하하하... 클라비스, 의외로 정신을 차렸군.",
  ui_story_5084_50841302_143_dialog_content = "빌헬름... 빌헬름이여... 스스로 대단하다 생각하는 그런 장난질로\n빅토리아를 숨기면 뭐라도 바뀔 거라고 생각한 건가...",
  ui_story_5084_50841302_144_dialog_content = "오오, 가련한 빌헬름, 인정받지 못한 빌헬름이여, 이렇게 자기 고향에서 죽음을 맞이하다니.",
  ui_story_5084_50841302_145_dialog_content = "......",
  ui_story_5084_50841302_146_dialog_content = "훗, 왈라키아의 반지는 후대에 계속 전해진들 아무 의미도 없겠지.",
  ui_story_5084_50841302_147_dialog_content = "<color=#e8d9bb>데이비드 포르피리오가 자신의 뒤편에 있던 피의 병을 흔들더니,\n손가락 사이로 그의 생에 있어 가장 강력한 힘을 불어넣었다.</color>",
  ui_story_5084_50841302_148_dialog_content = "<color=#e8d9bb>데이비드 포르피리오는 왈라키아의 반지를 산산이 부쉈고,\n은빛과 붉은빛 가루가 빌헬름의 몸 위에 뿌려졌다.</color>",
  ui_story_5084_50841302_149_dialog_content = "이게 무슨 짓이냐! 반지를 부수면 앞으론...",
  ui_story_5084_50841302_150_dialog_content = "반지는 우리에겐 아무 쓸모도 없다. 이 가루라도 빌헬름의 시체와 함께 영면하게 해 주자고.",
  ui_story_5084_50841302_151_dialog_content = "앞으로는 우리 모두 다시는 마음 졸일 필요가 없겠군.",
  ui_story_5084_50841302_152_dialog_content = "왈라키아 대가주라는 족쇄도 이로써 과거가 된 것이다!",
  ui_story_5084_50841302_153_dialog_content = "하하하하... 데이비드, 성명제의 만찬이 참으로 풍성하군!",
  ui_story_5084_50841302_154_dialog_content = "네놈들... 빌헬름은 이미 죽었다...!",
  ui_story_5084_50841302_155_dialog_content = "그래, 전부 네 덕분이지.\n왈라키아의 신선한 피를 맛보는 것도 가주 간의 순서를 지킬 필요가 있겠군.",
  ui_story_5084_50841302_156_dialog_content = "내 다음 차례는 물론 내가 가장 친애하는 벗, 클라비스다.",
  ui_story_5084_50841302_157_dialog_content = "내 사도들이 배불리 먹고 나면, 빌헬름은 네가 알아서 해라.",
  ui_story_5084_50841302_158_dialog_content = "너와 빌헬름의 지난날의 우정을 생각해서 안장해 주는 것도 좋다.",
  ui_story_5084_50841302_159_dialog_content = "누가 뭐래도 죽은 후 관에 몸을 누이는 것 또한 우리 피의 일족의 전통이니 말이야.",
  ui_story_5084_50841302_160_dialog_content = "참, 빌헬름에게 고해성사하는 것도 잊지 말라고.\n가장 가까운 벗에게 칼을 맞은 그가 아직 듣고 있을지도 모르잖나...",
  ui_story_5084_50841302_161_dialog_content = "...이제 내 아내와 카론을 놓아줄 수 있겠나?",
  ui_story_5084_50841302_162_dialog_content = "당연히 그럴 생각이지만, 클라비스, 한 가지 이해가 안 되는 게 있다...\n사도들이 얼마 전부터 네가 거처를 옮기려 하는 모습을 봤다고 하더군...",
  ui_story_5084_50841302_163_dialog_content = "......",
  ui_story_5084_50841302_164_dialog_content = "그렇게 되어 버리면... 내가 앞으로 네게 부탁할 일이 있을 때,\n조금 불편해지지 않겠나...?",
  ui_story_5084_50841302_165_dialog_content = "데이비드, 이 자식...!",
  ui_story_5084_50841302_166_dialog_content = "하하하하!",
  ui_story_5084_50841302_167_dialog_content = "...멍청하긴.",
  ui_story_5084_50841302_168_dialog_content = "금꾼, 넌 인맥이 넓으니 네가 빅토리아를 찾아라. 화근의 싹은 철저히 없애야지.",
  ui_story_5084_50841302_169_dialog_content = "내가 무슨 짓을 한 거냐... 내가 대체...",
  ui_story_5084_50841302_170_dialog_content = "<color=#e8d9bb>클라비스는 숨을 거둔 빌헬름을 업고 왈라키아의 무덤에 도착했다.</color>",
  ui_story_5084_50841302_171_dialog_content = "<color=#e8d9bb>그러나 묘지기인 덩굴인간은 빌헬름을 이곳에 묻고 싶다는 클라비스의 요청을 받아들이지 않았다.</color>",
  ui_story_5084_50841302_172_dialog_content = "만문의 열쇠, <color=#FFB400>검은 상자 「파리아」</color>여!",
  ui_story_5084_50841302_173_dialog_content = "<color=#e8d9bb>그러자 성물이 모습을 드러내 균열을 만들어냈고,\n클라비스는 「기나긴 물결」의 틈을 통해 무덤 안으로 들어갔다.</color>",
  ui_story_5084_50841302_174_dialog_content = "여긴 왈라키아의 무덤이다, 빌헬름... 비록 이곳도 더는 안전하지 않을지 모르지만...\n난 이제 서둘러 떠나야 한다.",
  ui_story_5084_50841302_175_dialog_content = "부디 네가 이곳에서 영면에 들어, 네 선조들과 함께 진리의 주인의 품으로\n돌아갈 수 있길 바란다.",
  ui_story_5084_50841302_176_dialog_content = "이 열쇠는... 내가 지니고 있다면 재앙이 될 뿐이겠지.",
  ui_story_5084_50841302_177_dialog_content = "단 하루라도 내 손에 있다간 포르피리오에게 발각되고 말 거다.",
  ui_story_5084_50841302_178_dialog_content = "선조들께서 이 모든 걸 보셨다면, 제가 남은 생애 동안 뭇사람들에게\n버림받는 고통으로 저를 벌해 주십시오...",
  ui_story_5084_50841302_179_dialog_content = "진리의 결사... 왈라키아... 우리는 노력했지만, 결사와 혈족의 운명을 좌우할 순 없었다.",
  ui_story_5084_50841302_180_dialog_content = "빌헬름... 피의 일족... 우리는 결국 산 채로 운명의 포로가 되어 버렸단 말인가...",
  ui_story_5084_50841302_181_dialog_content = "<color=#e8d9bb>침묵하는 묘지기가 지켜보는 가운데, 클라비스는 검은 상자 「파리아」를\n빌헬름과 함께 관에 넣었다.</color>",
  ui_story_5084_50841302_182_dialog_content = "<color=#e8d9bb>그러나 아무도 눈치채지 못한 사이에, 만문의 열쇠는 멋대로 「운명」의 문을 열어 버렸다.</color>",
  ui_story_5084_50841302_183_dialog_content = "날 위해 변명하진 않겠다... 이 모든 건 내가 자초한 일이다.",
  ui_story_5084_50841302_184_dialog_content = "배신이라니... 죄가 깊은 클라비스 님, 지금 당장 진리의 주인께 참회하십시오.",
  ui_story_5084_50841302_185_dialog_content = "난 주께 용서를 구하지 않을 것이다... 이제 더는 빌헬름을 마주하고 싶지 않다.",
  ui_story_5084_50841302_186_dialog_content = "......",
  ui_story_5084_50841302_187_dialog_content = "그 장소는 당신과 나 외엔 아무도 몰라. 그리고 빌헬름은 이미 숨을 거뒀지.",
  ui_story_5084_50841302_188_dialog_content = "내가 왈라지 마을을 떠나기로 결심한 그날, 당신은 빌헬름이 아니라 날 찾아왔어.",
  ui_story_5084_50841302_189_dialog_content = "만약 네가 마을로 돌아온다면, 모든 걸 털어놓고... 만약 돌아오지 않는다면...",
  ui_story_5084_50841302_190_dialog_content = "아무 말도 하지 않을 작정이었겠지.",
  ui_story_5084_50841302_191_dialog_content = "정말, 단 하루도 고통받지 않은 날이 없었다...",
  ui_story_5084_50841302_192_dialog_content = "언제든 내 목숨을 거두고 싶을 때 그렇게 하도록 해라.\n그렇지만 마지막으로 한 가지만 끝을 맺게 해 줬으면 한다.",
  ui_story_5084_50841302_193_dialog_content = "......",
  ui_story_5084_50841302_194_dialog_content = "클라비스 님, 제대로 걸으실 수 있겠습니까...",
  ui_story_5084_50841302_195_dialog_content = "카론과 내 아내는 이 모든 일과 아무런 관련도 없다.\n난 그들에게 깨끗한 미래를 주어야만 한다...",
  ui_story_5084_50841302_196_dialog_content = "하하... 그렇지만 내가 살아있다 하더라도, 카론은 나라는 아버지를 원망하겠지...",
  ui_story_5084_50841302_197_dialog_content = "미래는 또 어떻게 될지 모르겠군... 이게 바로 내게 내려진 벌이란 말인가...",
  ui_story_5084_50841302_198_dialog_content = "그러고 보니까 카론 씨한테 들은 적 있는데... 아버지하고 사이가 엄청 안 좋다고 했었어.",
  ui_story_5084_50841302_199_dialog_content = "......",
  ui_story_5084_50841302_200_dialog_content = "어? 빅토리아 씨, 촛불이 금방 꺼질 것 같은데...?",
  ui_story_5084_50841400_1_dialog_content = "빅토리아 님... 이것이 바로... 「만문의 열쇠」입니다.",
  ui_story_5084_50841400_2_dialog_content = "그때 클라비스 가주님은 이것을 빌헬름 님과 함께 묻으셨습니다.\n하지만 빌헬름 님의 행방은 아직 찾지 못했습니다.",
  ui_story_5084_50841400_3_dialog_content = "어? 이건 파리아잖아요. 그...",
  ui_story_5084_50841400_4_dialog_content = "PlayerName...",
  ui_story_5084_50841400_5_dialog_content = "아, 미안, 여기서 말하면 안 되는 내용이겠네.",
  ui_story_5084_50841400_6_dialog_content = "떠나시려는 것은 알고 있습니다. 그러니 이제 진리의 결사의 지도자이신\n빅토리아 님께 이것을 드리고자 합니다!",
  ui_story_5084_50841400_7_dialog_content = "아니, 이게 가져올 영향은 우리 중 그 누구도 통제할 수 없어. 여기 남겨 두도록 할게.",
  ui_story_5084_50841400_8_dialog_content = "그 누구도 이걸 사용하지 못하도록 해 줘. 설령 그게 나라도 말이야.\n이 모든 건 주의 뜻을 따라야만 해.",
  ui_story_5084_50841400_9_dialog_content = "빅토리아 님... 그렇다면 부탁드리고 싶습니다. 그토록 중요한 물건이라면...\n제가 아닌 다른 이에게 맡겨주실 수는 없겠습니까.",
  ui_story_5084_50841400_10_dialog_content = "원래부터 당신이 보관하고 있던 물건인걸.\n아버지께서 그때 그걸 클라비스에게 주셨던 건, 아마... 운명의 궤적을 엿보셨기 때문일 거야.",
  ui_story_5084_50841400_11_dialog_content = "제가 이 왈라키아의 무덤을 얼마나 더 지킬 수 있을지 모르겠습니다...",
  ui_story_5084_50841400_12_dialog_content = "가능하다면 가주 자리에서 물러나 마음 편히 덩굴이 되어 무덤을 지키는 데만 전념하고 싶습니다.\n그리고 빅토리아 님께서 문을 여실 그날을 기다리겠습니다.",
  ui_story_5084_50841400_13_dialog_content = "내가 비술을 사용해서 이 무덤을 가주들의 「시야」에서 사라지게 해 줄 수 있어.\n하지만 당신 마음속엔 굳건한 진리가 있을까?",
  ui_story_5084_50841400_14_dialog_content = "진리라... 저는 처음부터 세상을 멀리하고 싶었고,\n마침 이 무덤이 제 안식처가 되어 주었을 뿐입니다.",
  ui_story_5084_50841400_15_dialog_content = "이는 누가 진리의 결사의 지도자가 되느냐와는 아무런 상관이 없습니다.\n물론...! 저는 빅토리아 님의 뜻을 조금도 의심하지 않습니다.",
  ui_story_5084_50841400_16_dialog_content = "당신은 여전히 이곳을 지키고 싶어 하는구나. 자유를 얻고 싶진 않아?",
  ui_story_5084_50841400_17_dialog_content = "제 가족은 이미 모두 죽임을 당했습니다.\n저는 이 세상의 어디에 있더라도 지금처럼 외로울 뿐입니다.",
  ui_story_5084_50841400_18_dialog_content = "그렇다면 내가 당신에게 이곳에서 평온을 찾을 권리를 줄게.",
  ui_story_5084_50841400_19_dialog_content = "당신은 왈라키아의 가장 충직한 벗이야. 그러니 포르피리오의 지위를 대신할 자격이 있어.\n내가 여행을 떠나 있는 동안, 왈라지 마을을 부탁할게.",
  ui_story_5084_50841400_20_dialog_content = "제, 제가 어찌 감히...",
  ui_story_5084_50841400_21_dialog_content = "하지만 그게 바로 당신이 가장 원하는 「안식」이야.\n다시 새로운 가족을 찾고, 미래를 이어가도 좋아.",
  ui_story_5084_50841400_22_dialog_content = "내가 기억하는 당신은 백야성과 관련된 모든 과거를 버렸어. 당신의 성까지도.",
  ui_story_5084_50841400_23_dialog_content = "자, 새로운 성을 택하도록 해. 그게 당신 일족의 새로운 시작이 될 거야.",
  ui_story_5084_50841400_24_dialog_content = "...알겠습니다, 아가씨.",
  ui_story_5084_50841400_25_dialog_content = "그렇다면 저는... 단테스라고 하겠습니다.",
  ui_story_5084_50841400_26_dialog_content = "이제부터 제 이름은... 그레이브스 단테스입니다.",
  ui_story_5084_50841400_27_dialog_content = "(단테스...?! 이 사람이 바로... 스칼렛의 선조였던 거야?)",
  ui_story_5084_50841400_28_dialog_content = "후훗, 운명을 선택했으니, 이제 받아들이도록 해.",
  ui_story_5084_50841400_29_dialog_content = "당신의 일족은 줄곧 왈라키아의 충실한 맹우였고, 앞으로도 그럴 거야.\n검은 상자 「파리아」는 단테스 일족의 숙명을 비춰줄 거야.",
  ui_story_5084_50841400_30_dialog_content = "알겠습니다... 그럼 저는 이제 방해되지 않게 먼저 나가 보겠습니다.",
  ui_story_5084_50841400_31_dialog_content = "휴우... 이제야 모든 게 끝난 거 같네요!",
  ui_story_5084_50841400_32_dialog_content = "여기서 성명제를 보내고 소용돌이 마을로 돌아가면,\n또 하나의 성명제가 우릴 기다리고 있을 거야.",
  ui_story_5084_50841400_33_dialog_content = "히잉... 그럼 성명제를 세 번이나 보내야 하는 거잖아!\n갑자기 언니가 보고 싶어졌어...",
  ui_story_5084_50841400_34_dialog_content = "앗! 촛불이... 이번엔 진짜 꺼질 것 같아요.",
  ui_story_5084_50841400_35_dialog_content = "......",
  ui_story_5084_50841400_36_dialog_content = "(빅토리아 씨가 먼 곳을 바라보고 있어... 빌헬름 씨가 나타나 주길 기다리는 걸까...)",
  ui_story_5084_50841400_37_dialog_content = "가자.",
  ui_story_5084_50841400_38_dialog_content = "빅토리아 님, 이제 성전을 두 권 손에 넣으셨습니다. 모두 가져가실 겁니까?",
  ui_story_5084_50841400_39_dialog_content = "성전들은 돌아가는 길에 자신들이 가야 할 곳으로 가게 될 거야. 다들 떠날 준비를 하자.",
  ui_story_5084_50841400_40_dialog_content = "촛불이 꺼졌어! 어라? 낡은 성전은 아직 빅토리아 씨 손에 있는데?",
  ui_story_5084_50841400_41_dialog_content = "성전이 우리를 여기로 인도해, 날 새로운 성전과 만나게 했던 거야.\n그러니 이번엔 내가 녀석을 운명에 돌려줄 때가 됐어.",
  ui_story_5084_50841400_42_dialog_content = "빅토리아 씨?",
  ui_story_5084_50841400_43_dialog_content = "<color=#e8d9bb>귀환의 어둠 속, 시간의 흐름에는 한 줄기의 「틈」이 생겼고,\n그 속에서는 기묘하게 흐르는 긴 그림자를 어렴풋이 엿볼 수 있었다.</color>",
  ui_story_5084_50841400_44_dialog_content = "<color=#e8d9bb>빅토리아가 손을 놓자, 그녀와 오랜 시간을 함께해 온 성전이 그 흐름 속으로 떨어지더니,\n자연스럽게 흘러가 버렸다...</color>",
  ui_story_5084_50841400_45_dialog_content = "성전은 어디로 가는 거야...?",
  ui_story_5084_50841400_46_dialog_content = "쉿, 흐름을 가만히 살펴보렴. 진리란 건 저 안에 있으니까.",
  ui_story_5084_50841400_47_dialog_content = "우리 모두는 이 하늘의 강 속에 있는 모래알 하나에 지나지 않아.\n결국 우린 진리의 주인의 품으로 돌아가게 될 거야.",
  ui_story_5084_50841400_48_dialog_content = "이제 가렴. 「네」가 모든 운명과 만날 수 있기를 바랄게.",
  ui_story_5084_50841400_49_dialog_content = "<color=#e8d9bb>그렇게 성전은 흐름을 따라 「미래에서 온 낯선 이들」과 작별을 고했다.</color>",
  ui_story_5084_50841400_50_dialog_content = "<color=#e8d9bb>원시의 강 위의 성전은 조용히 흐름에 몸을 맡겼고, 물결이 일렁이자,\n성전이 지나간 자리에 수많은 빛의 그림자가 떠올라, 과거와 미래를 보여 주었다.</color>",
  ui_story_5084_50841400_51_dialog_content = "<color=#e8d9bb>바람도 불지 않는데 성전이 저절로 펼쳐졌고,\n성전이 자아낸 모든 혼란이 글자 하나 없던 백지에 떠올랐다.</color>",
  ui_story_5084_50841400_52_dialog_content = "<color=#e8d9bb>바로 그렇게, 운명은 그 종이 위에 기록되었다.</color>",
  ui_story_5084_50841400_53_dialog_content = "<color=#e8d9bb>성전의 그림자가 그 이야기들에 투영되자, 사람들은 성전의 모습을 인식하기 시작했고,\n성전은 마침내 강 속의 운명에 참여하게 되었다.</color>",
  ui_story_5084_50841400_54_dialog_content = "<color=#e8d9bb>「빌헬름은 출처 모를 성전을 주워 들고 계시의 존재를 느꼈고,\n손에 쥔 성전을 깊이 잠든 빅토리아에게 가져가기로 결심했다.」</color>",
  ui_story_5084_50841400_55_dialog_content = "<color=#e8d9bb>「어린 빅토리아는 아무것도 쓰여 있지 않은 성전을 펼치고, 처음으로 진리의 예언을 들었다.」</color>",
  ui_story_5084_50841400_56_dialog_content = "<color=#e8d9bb>성전은 계속해서 강줄기를 따라 흘러 내려갔다.\n시간은 그 흐름 속에서 시작과 끝이 없는, 영원히 멈추지 않는 고리였다.</color>",
  ui_story_5084_50841400_57_dialog_content = "<color=#e8d9bb>「빅토리아가 손을 놓자, 그녀와 오랜 시간을 함께해 온 성전이 그 흐름 속으로 떨어지더니,\n자연스럽게 흘러가 버렸다...」</color>",
  ui_story_5084_50841400_58_dialog_content = "...모든 여행자들이 그들의 시간으로 돌아갔으니,\n나 또한 내 일을 마무리 지을 때가 되었군.",
  ui_story_5084_50841400_59_dialog_content = "1918년의 빅토리아, 진리를 찾아다니는 중인 너는 아직 무지하여,\n모든 것이 네겐 너무나도 심오하겠지...",
  ui_story_5084_50841400_60_dialog_content = "괜찮다. 그저 가만히 시간이 흐르길 기다리면 된다.",
  ui_story_5084_50841400_61_dialog_content = "너는 나처럼 긴 여정을 떠난 후, 계시를 받게 될 것이다.",
  ui_story_5084_50841400_62_dialog_content = "그때가 되면, 너는 그들을 데리고 이 시간으로 돌아올 테고, 우리는 다시 만나게 되겠지.",
  ui_story_5084_50841400_63_dialog_content = "<color=#e8d9bb>빌헬름은 깊이 잠든 빅토리아를 소용돌이 마을에서 이곳으로 옮겼고,\n그녀의 손에 낡은 성전을 쥐여 주었다.</color>",
  ui_story_5084_50841400_64_dialog_content = "<color=#e8d9bb>그 후 자신이 몸을 뉘었던 관으로 돌아가 과거를 회상했다.</color>",
  ui_story_5084_50841400_65_dialog_content = "나와 어린 네가 처음으로 만난 건, 형님이 세상을 떠나기 얼마 전\n너를 내게 부탁하던 때였지.",
  ui_story_5084_50841400_66_dialog_content = "나보고 지도자가 되라고?",
  ui_story_5084_50841400_67_dialog_content = "그래, 그리고 빅토리아를 부탁한다.",
  ui_story_5084_50841400_68_dialog_content = "<color=#e8d9bb>말없이 부모 곁에 서 있던 빅토리아는, 죽음을 앞둔 두 사람의 얼굴이 어째서 저렇게\n만족스러운 표정을 짓고 있는 것인지 이해할 수 없었다.</color>",
  ui_story_5084_50841400_69_dialog_content = "<color=#e8d9bb>그리고 온갖 수모를 겪어 온 빌헬름 왈라키아는, 마음에 상처를 입게 될 빅토리아를\n피의 일족의 숙명으로 이끌고 싶지 않았다.</color>",
  ui_story_5084_50841400_70_dialog_content = "더 말할 필요도 없어. 난 그럴 마음 없으니까.",
  ui_story_5084_50841400_71_dialog_content = "......",
  ui_story_5084_50841400_72_dialog_content = "<color=#e8d9bb>그러나 장례식 당일, 빌헬름은 신도의 복장을 하고,\n형과 형수의 관이 왈라지 마을을 떠나는 모습을 바라보았다.</color>",
  ui_story_5084_50841400_73_dialog_content = "<color=#e8d9bb>빌헬름은 왈라키아의 무덤 입구에 멈춰 서서 가주들이 빅토리아에게 하는 「인사」를 들었다.</color>",
  ui_story_5084_50841400_74_dialog_content = "<color=#e8d9bb>그 순간, 빌헬름의 마음속에서는 폭풍우와 번개처럼, 세상을 찢어발길 듯한 힘이 솟아올랐다.</color>",
  ui_story_5084_50841400_75_dialog_content = "<color=#e8d9bb>빌헬름은 자신을 집어삼킬 수도 있는 왈라키아의 반지를\n가주들 앞에서 착용하기 위해 무덤 중앙으로 달려갔다.</color>",
  ui_story_5084_50841400_76_dialog_content = "<color=#e8d9bb>오직 자신과 함께 영원히 진리의 길을 걸어갈 소녀를 지키겠단 마음 하나만 품은 채...</color>",
  ui_story_5084_50841400_77_dialog_content = "<color=#e8d9bb>두 사람이 함께한 시간은 그다지 순탄치만은 않았지만,\n빌헬름은 당시 진리의 결사를 거부하던 빅토리아를 억지로라도 강하게 만들어야만 했다.</color>",
  ui_story_5084_50841400_78_dialog_content = "<color=#e8d9bb>그리고 자신과 빅토리아를 보호할 방법을 마련하기 위해 곳곳을 찾아다녔다.</color>",
  ui_story_5084_50841400_79_dialog_content = "<color=#e8d9bb>그러다 자신의 죽음에 생각이 미쳤을 무렵...</color>",
  ui_story_5084_50841400_80_dialog_content = "클라...비스...",
  ui_story_5084_50841400_81_dialog_content = "빅토리아를 돌본 적 있는 너라면 날 이해할 수 있겠지.",
  ui_story_5084_50841400_82_dialog_content = "빅토...리아...",
  ui_story_5084_50841400_83_dialog_content = "훗...",
  ui_story_5084_50841400_84_dialog_content = "(혈족의 전통에 따른다면, 죽음은 일종의 축복일지도 모른다.)",
  ui_story_5084_50841400_85_dialog_content = "(지금의 나는 이제 더는 타인의 배신에 고통스러워하지 않는다...)",
  ui_story_5084_50841400_86_dialog_content = "(클라비스, 네 고충은 이해하지만... 빅토리아는 이제 어떻게 해야 좋단 말이냐.)",
  ui_story_5084_50841400_87_dialog_content = "(난 내가 알고 있는 모든 진리를 정말로 그녀에게 전해 주었나?)",
  ui_story_5084_50841400_88_dialog_content = "(그녀가 떠나던 그날, 어쩌면 그녀는 내게 자신은 이미 진리를 추구하는 길을\n확고히 걷고 있다고 알려 주려던 것은 아닐까.)",
  ui_story_5084_50841400_89_dialog_content = "(......)",
  ui_story_5084_50841400_90_dialog_content = "<color=#e8d9bb>진리를 향한 빌헬름의 질문은 멈출 줄을 몰랐고, 그의 생각은 투명한 강물로 흘러 들어갔다.</color>",
  ui_story_5084_50841400_91_dialog_content = "...어떻게 된 일이지? 난 분명히 그 교회에서... 이미 죽었어야 하는데...",
  ui_story_5084_50841400_92_dialog_content = "여긴 대체...",
  ui_story_5084_50841400_93_dialog_content = "죽은 자의 나라인가...? 아니면 진리의 주인의 전당인가?",
  ui_story_5084_50841400_94_dialog_content = "게다가 이 강물은 또 뭐냐...",
  ui_story_5084_50841400_95_dialog_content = "<color=#e8d9bb>표류하고, 또 끝없이 떠돌았다. 표류하는 빌헬름은 움직이지 않았지만,\n세상의 모든 정보가 모조리 그의 머릿속으로 흘러 들어왔다.</color>",
  ui_story_5084_50841400_96_dialog_content = "<color=#e8d9bb>10년? 100년? 대체 시간이 얼마나 흐른 것이냐...</color>",
  ui_story_5084_50841400_97_dialog_content = "<color=#e8d9bb>아이올리아가 어두워졌다 밝아졌다. 그러나 오로리안과 암귀의 싸움은 여전히 끝나지 않았다.</color>",
  ui_story_5084_50841400_98_dialog_content = "<color=#e8d9bb>그리고 오직 그만이 쉼 없이 표류하고 있었다.</color>",
  ui_story_5084_50841400_99_dialog_content = "저건... 나인가?",
  ui_story_5084_50841400_100_dialog_content = "이건 빅토리아의 자신의 뜻이 아니라 그녀의 운명이다.\n나 대신 이 새로운 성전을 관에 넣어주어라. 그녀는 분명히 쓰게 될 것이다.",
  ui_story_5084_50841400_101_dialog_content = "예, 빌헬름 님.",
  ui_story_5084_50841400_102_dialog_content = "그리고 그때...",
  ui_story_5084_50841400_103_dialog_content = "너도 가족을 꾸리면 되지, 뭘 그렇게 풀이 죽어 있는 거냐?",
  ui_story_5084_50841400_104_dialog_content = "가족을 꾸리고, 아이를 키우라고? 흥미 없다.",
  ui_story_5084_50841400_105_dialog_content = "<color=#e8d9bb>수많은 빌헬름이 여러 곳에 흩어져 있다가, 서로 교차하며 하나로 합쳐졌다.\n모든 것이 혼란한 가운데, 빌헬름은 자신 이외의 존재를 발견하고 나서야 혼돈에서 빠져나왔다.</color>",
  ui_story_5084_50841400_106_dialog_content = "진리의 주인께서 굽어살펴 주신 거지, 내 덕분이 아니야.",
  ui_story_5084_50841400_107_dialog_content = "여긴 뭐 하는 곳이죠?",
  ui_story_5084_50841400_108_dialog_content = "<color=#FFB400>원시의 강</color>은 시간과 공간의 제약을 받지 않아.\n이곳과 바깥 세계의 유일한 차이점은 흐르고 있다는 거야.",
  ui_story_5084_50841400_109_dialog_content = "계속 이대로 가면 우리 목숨도 우리 뜻대로 할 수 없게 되는 건가?\n왜 우릴 이곳으로 데려왔지?",
  ui_story_5084_50841400_110_dialog_content = "빅토리아?!",
  ui_story_5084_50841400_111_dialog_content = "하하하... 하하하하하하!",
  ui_story_5084_50841400_112_dialog_content = "역시 빅토리아 왈라키아답군. 해내다니... 하하하하하...",
  ui_story_5084_50841400_113_dialog_content = "게다가 카론까지...",
  ui_story_5084_50841400_114_dialog_content = "...클라비스... 우린 어른으로서 할 일을... 전부 해낸 거다...",
  ui_story_5084_50841400_115_dialog_content = "<color=#e8d9bb>회상을 마친 빌헬름은 다시 몸을 일으켰지만, 이번에는 자신의 관 속이 아니었다.\n빌헬름은 끝없이 펼쳐진 원시의 강을 바라보며, 그 안으로 걸어 들어갔다.</color>",
  ui_story_5084_50841400_116_dialog_content = "<color=#e8d9bb>빌헬름이 어지럽혔던 인과는 그를 휘감았고... 그를 「진리의 고정점」으로 이끌었다.</color>",
  ui_story_5084_50841400_117_dialog_content = "<color=#e8d9bb>그 후──</color>",
  ui_story_5084_50841400_118_dialog_content = "<color=#e8d9bb>빅토리아가 던진 성전은 「장애물」에 부딪혀 표류를 멈추었다.\n쓰러져 강을 타고 흐르던 「죽은 자」와 닿은 것이었다.</color>",
  ui_story_5084_50841400_119_dialog_content = "<color=#e8d9bb>배신당한 빌헬름이라는 이름의 죽은 자이자, 운명의 문에 이끌려 들어온 자인 그는...\n기묘한 흐름 속에서 눈을 떴다.</color>",
  ui_story_5084_50841400_120_dialog_content = "......?!",
  ui_story_5084_50841400_121_dialog_content = "<color=#e8d9bb>...그 순간, 당혹스러워하던 빌헬름은 자신의 발치 쪽 강물 속에\n멈춰서 떠 있는 핏빛 성전을 발견했다.</color>",
  ui_story_5084_50841400_122_dialog_content = "<color=#e8d9bb>소리 없는 부름처럼, 빌헬름은 글자 하나 없는 성전을 펼쳤다. 그리고 그는 보았다...</color>",
  ui_story_5084_50841400_123_dialog_content = "<color=#e8d9bb>「강을 따라 흘러 내려온 성전이 숨을 거둔 빌헬름의 발치에 닿았고,\n그 젊은 혈족은 반지가 머금은 한 방울의 피로 인해 되살아났다.」</color>",
  ui_story_5084_50841400_124_dialog_content = "<color=#e8d9bb>「...그 순간, 당혹스러워하던 빌헬름은 자신의 발치 쪽 강물 속에\n멈춰서 떠 있는 핏빛 성전을 발견했다.」</color>",
  ui_story_5084_50841400_125_dialog_content = "?!",
  ui_story_5084_50841400_126_dialog_content = "<color=#e8d9bb>「겁에 질린 빌헬름은 강물에 빠져버렸고, 그가 어지럽힌 강물이 그를 적시자,\n모든 인과가 그에게 배어들었다.」</color>",
  ui_story_5084_50841400_127_dialog_content = "<color=#e8d9bb>「강물 속에 앉아 있던 빌헬름은 자신의 손 옆에 무언가가 더 있다는 사실을 발견했다.\n떨리는 손으로 그것을 집어 들었을 때, 그의 눈에 들어온 것은...」</color>",
  ui_story_5084_50841400_128_dialog_content = "반지... 우리 왈라키아 가문의 반지가 아닌가...",
  ui_story_5084_50841400_129_dialog_content = "이게 대체...",
  ui_story_5084_50841400_130_dialog_content = "<color=#e8d9bb>「부름을 받은 빌헬름은 반드시 진리의 안내자로서 방랑의 길에 오를 것이다.」</color>",
  ui_story_5084_50841400_131_dialog_content = "<color=#e8d9bb>「때가 무르익으면, 빅토리아를 위해 왈라키아의 무덤 문이 열리고,\n진리의 종 빌헬름은 반드시 빅토리아의 안내자가 될 것이다.」</color>",
  ui_story_5084_50841400_132_dialog_content = "<color=#e8d9bb>「...그 후 빌헬름은 자신이 몸을 뉘었던 관으로 돌아가 과거를 회상했다.」</color>",
  ui_story_5084_50841400_133_dialog_content = "<color=#e8d9bb>「...그는 자신이 사명을 완수했고, 빅토리아가 이미 충분히 성장했음을 깨달았을 때,\n과연 안식을 얻을 수 있을까.」</color>",
  ui_story_5084_50841400_134_dialog_content = "<color=#e8d9bb>「그가 반지에 손을 대자, 반지가 머금었던 왈라키아의 피 한 방울이 온몸으로 퍼져나갔다...\n익숙한 감각이 돌아오며, 그는 깊은 잠에 빠져들었다.」</color>",
  ui_story_5084_50841400_135_dialog_content = "<color=#e8d9bb>「──그가 다시 눈을 뜰 때, 그는 운명의 교차점으로 인도받을 것이다.」</color>",
  ui_story_5084_50841400_136_dialog_content = "(여긴...)",
  ui_story_5084_50841400_137_dialog_content = "빅토리아 님께서는 신앙이 저를 이끌어 줄 것이라고 하셨습니다만...",
  ui_story_5084_50841400_138_dialog_content = "저는 희생을 택하고자 합니다...",
  ui_story_5084_50841400_139_dialog_content = "저는...",
  ui_story_5084_50841400_140_dialog_content = "......",
  ui_story_5084_50841400_141_dialog_content = "...주님이십니까?",
  ui_story_5084_50841400_142_dialog_content = "위대하신 진리의 주인이시여!",
  ui_story_5084_50841400_143_dialog_content = "방금... 「빅토리아 님」이라고 했나?",
  ui_story_5084_50841400_144_dialog_content = "<color=#e8d9bb>「시간은 그 흐름 속에서 시작과 끝이 없는, 영원히 멈추지 않는 고리였다.」</color>",
  ui_story_5084_50841400_145_dialog_content = "<color=#e8d9bb>「빅토리아가 손을 놓자, 그녀와 오랜 시간을 함께해 온 성전이 그 흐름 속으로 떨어지더니,\n자연스럽게 흘러가 버렸다...」</color>",
  ui_story_5084_50841400_146_dialog_content = "모두 돌아오셨군요.",
  ui_story_5084_50841400_147_dialog_content = "어? 초가 없어졌잖아?",
  ui_story_5084_50841400_148_dialog_content = "그건 「파리아」의 힘이니까.",
  ui_story_5084_50841400_149_dialog_content = "파리아, 종료.",
  ui_story_5084_50841400_150_dialog_content = "(그랬구나... 밤하늘 무덤이 당시 왈라키아의 무덤이었던 거야.)",
  ui_story_5084_50841400_151_dialog_content = "「만문의 열쇠」, 또 만났구나.",
  ui_story_5084_50841400_152_dialog_content = "빅토리아 님?",
  ui_story_5084_50841400_153_dialog_content = "후훗, 혼잣말이야. 신경 쓰지 마.",
  ui_story_5084_50841400_154_dialog_content = "...네.",
  ui_story_5084_50841400_155_dialog_content = "메이?",
  ui_story_5084_50841400_156_dialog_content = "언니? 언니가 왜 여기 있어?",
  ui_story_5084_50841400_157_dialog_content = "빵을 다 구웠는데 메이가 보이지 않았어요. 전 스칼렛 씨를 찾으러 왔을 거라고 생각했어요.\n그런데 빅토리아 님과 다른 분들도 모두 여기 계실 줄은 몰랐어요.",
  ui_story_5084_50841400_158_dialog_content = "잠깐만, 먹을 게 있다고...?",
  ui_story_5084_50841400_159_dialog_content = "맛있는 냄새가 나는 빵이랑 향이 좋은 포도주...\n이 성명제 음식들은 다 언니가 준비한 거야!",
  ui_story_5084_50841400_160_dialog_content = "그 얘길 들으니까 확실히 배고파졌어.",
  ui_story_5084_50841400_161_dialog_content = "스칼렛, 너도 함께 축제에 참여할 거지?",
  ui_story_5084_50841400_162_dialog_content = "네, 빅토리아 님의 초대라면 반드시 참여해야죠.",
  ui_story_5084_50841400_163_dialog_content = "시간이 됐습니다, 빅토리아 님. 진리의 결사의 일원들은 지금쯤 마을에 모였을 것입니다.",
  ui_story_5084_50841400_164_dialog_content = "진리의 결사의 모든 멤버가 참여하는 거야?",
  ui_story_5084_50841400_165_dialog_content = "전에 초대했을 때는 망설이더니, 이번엔 기대되는 모양이지?",
  ui_story_5084_50841400_166_dialog_content = "진리의 결사 친구들이랑은 자주 못 만나지만,\n익숙한 동료들한테 둘러싸여 있는 느낌은 정말 좋거든.",
  ui_story_5084_50841400_167_dialog_content = "3년에 한 번 거행되는 진리의 결사의 성대한 축제에 참여한 여러분을 환영합니다.",
  ui_story_5084_50841400_168_dialog_content = "3년이 지났고, 우리는 아이올리아 탐색에 또 한 걸음 가까워졌으며,\n진리의 주인께도 한 걸음 더 다가가게 되었습니다.",
  ui_story_5084_50841400_169_dialog_content = "영원하신 진리의 주인 외에는, 우리 그 누구도 서로의 신분을 따지지 않고,\n불변의 계율을 인정하지 않습니다.",
  ui_story_5084_50841400_170_dialog_content = "타고난 특이성을 고수하든, 끊임없이 과거의 족쇄에서 벗어나든,\n아니면 어떤 사명을 수행하든...",
  ui_story_5084_50841400_171_dialog_content = "지속적으로 변화하고 깨달으며, 우리는 진리로 다가서는 길에서 찬란히 빛나고 있습니다.",
  ui_story_5084_50841400_172_dialog_content = "지금 진리의 결사는 진리의 축복을 받은 길을 걷고 있습니다.",
  ui_story_5084_50841400_173_dialog_content = "나는 진리의 결사와 깊은 관계에 있는 피의 일족이 아스트라 대륙 바깥에서도\n준비를 마쳤음을 확인했습니다.",
  ui_story_5084_50841400_174_dialog_content = "그리고 나는 여러분을 이끌고 진리의 주인의 강림을 목도하기 위해 나아갈 것입니다.",
  ui_story_5084_50841400_175_dialog_content = "어둠의 위기가 닥쳤을 때, 성전은 거대한 변혁이 다가오고 있음을 계시했습니다.",
  ui_story_5084_50841400_176_dialog_content = "그때의 내가 선택했던 변혁자는 이제 점차 성숙해지고 있습니다.",
  ui_story_5084_50841400_177_dialog_content = "자물쇠는 어둠의 밑바닥에 나타날 것이며, 열쇠는 내가 목적지까지 가져갈 것입니다.\n그리고 진리의 주인과 함께 신의 나라를 재건하겠습니다.",
  ui_story_5084_50841400_178_dialog_content = "이번 여정은 어둠의 밑바닥을 밤낮으로 횡단하게 될 것이며,\n진리의 결사는 동맹의 신분으로 다시 한번 오로리안을 인도하여 위기를 극복할 것입니다.",
  ui_story_5084_50841400_179_dialog_content = "이제 모두 마음껏 축제 음식을 즐기도록 하세요.",
  ui_story_5084_50841400_180_dialog_content = "진리의 주인께서 제게 영광을 내리시어, 여러분 모두에게\n진리가 충만한 술과 음식을 하사하셨습니다.",
  ui_story_5084_50841400_181_dialog_content = "이와 함께 여러분의 새로운 깨달음을 마음껏 나누도록 하세요.",
  ui_story_5084_50841400_182_dialog_content = "진리의 축복 있으라.",
  ui_story_5084_50841400_183_dialog_content = "진리의 축복 있으라.",
  ui_story_5084_50841400_184_dialog_content = "파솔로, 한참 동안 파우스트를 보고 있던데, 뭐 이상한 거라도 있어?",
  ui_story_5084_50841400_185_dialog_content = "저기... 파우스트 씨... 스칼렛 언니한테 들었는데요... 돌아가신 제 부모님의 「영혼」에 대한\n질문에 파우스트 씨가 새로운 답을 해 주실 수 있을 거라고 했어요...",
  ui_story_5084_50841400_186_dialog_content = "「새로운 답」을 원한다면 나일즈에게 가서 묻는 것도 좋을 거야.\n최근 가장 많은 수확을 얻은 사람이거든.",
  ui_story_5084_50841400_187_dialog_content = "<color=#e8d9bb>꼬르르륵──</color>",
  ui_story_5084_50841400_188_dialog_content = "PlayerName, 빨리 바퀴 좀 막아 봐!",
  ui_story_5084_50841400_189_dialog_content = "으앗! 구르는 속도가 너무 빨라... 벌써 나일즈 쪽까지 굴러갔어!",
  ui_story_5084_50841400_190_dialog_content = "<color=#e8d9bb>쿠웅──</color>",
  ui_story_5084_50841400_191_dialog_content = "미안, 나일즈! 헌터스톤에 부딪히진 않았어?",
  ui_story_5084_50841400_192_dialog_content = "아닙니다, 펙트. 혹시 제게 고통을 주고 싶은 거라면, 가시로 여길 세게 찌르면 됩니다.",
  ui_story_5084_50841400_193_dialog_content = "나일즈! 너 전에 나한테 오늘 밤은 절대 자길 상처입히지 않겠다고 했잖아!\n호, 혹시 새 옷을 입어서 그런 거야?!",
  ui_story_5084_50841400_194_dialog_content = "나일즈 씨... 나일즈 씨라면 「영혼」에 대한 질문에 새로운 깨달음을 줄 수 있을 거라고\n파우스트 씨가 그랬어요.",
  ui_story_5084_50841400_195_dialog_content = "으음, 깨달음이라... 멘토님께서 제게 몇 가지 가르침을 주시긴 했습니다...",
  ui_story_5084_50841400_196_dialog_content = "저는 「영혼」이란 정신의 결정체라고 생각합니다.\n정신만 존재한다면, 사람은 영원히 사라지지 않을지도 모릅니다.",
  ui_story_5084_50841400_197_dialog_content = "그런가요... 그럼 저도 이미 세상을 떠난 사람들을 다시 만날 수도 있겠네요?",
  ui_story_5084_50841400_198_dialog_content = "그 질문에 대해선... 빅토리아 님께서 답을 해 주실 수 있을 겁니다.",
  ui_story_5084_50841400_199_dialog_content = "호오, 오래 못 본 사이에 신성한 기운이 세차게 느껴지게 됐잖아...?",
  ui_story_5084_50841400_200_dialog_content = "오랜만이군요, 트라몬 씨.",
  ui_story_5084_50841400_201_dialog_content = "빅토리아 님과 함께 뭔가 겪은 모양이지?",
  ui_story_5084_50841400_202_dialog_content = "제 영광이었습니다. 그리고 이번 여정에서 전 매우 중요한 멘토님을 한 분 만났습니다.\n그분께선 제가 진리의 주인의 축성을 받게 인도해 주셨습니다...",
  ui_story_5084_50841400_203_dialog_content = "고행자의 눈이 뜨이는 날이 오게 될 줄은 몰랐군. 그래서 그 멘토님은 오늘 참석했나?",
  ui_story_5084_50841400_204_dialog_content = "멘토님께선... 부끄럽지만 저도 잘 모르겠습니다...",
  ui_story_5084_50841400_205_dialog_content = "빅토리아 님... 나일즈 씨가 「정신만 존재한다면,\n사람은 영원히 사라지지 않는다」고 했는데요...",
  ui_story_5084_50841400_206_dialog_content = "그럼 돌아가신 부모님도 쭉 제 곁에 계신 거죠?",
  ui_story_5084_50841400_207_dialog_content = "오로리안은 신앙의 빛이 모여 탄생했단다.\n그리고 오로리안의 정신적인 힘은 아주 높은 차원의 강에서 비롯된 거야.",
  ui_story_5084_50841400_208_dialog_content = "만약 네 부모님이 돌아가시고 난 다음에, 두 분의 정신 중 일부가 그곳으로 되돌아갔다면,\n넌 두 분을 축복해 드려야 해.",
  ui_story_5084_50841400_209_dialog_content = "두 분을 축복해 드려야 하는 건가요...",
  ui_story_5084_50841400_210_dialog_content = "해답을 주셔서 감사해요, 빅토리아 님. 조금 더 생각해 볼게요...",
  ui_story_5084_50841400_211_dialog_content = "<color=#e8d9bb>빅토리아는 날로 성장하는 진리의 결사를 보며 깊은 감회에 잠겼다.</color>",
  ui_story_5084_50841400_212_dialog_content = "<color=#e8d9bb>결사가 오늘의 모습을 갖추게 된 것은 그때의 빌헬름과 지금의 자신이 함께\n과거의 빅토리아 앞에 놓인 장애물을 치워 주었기 때문이었다.</color>",
  ui_story_5084_50841400_213_dialog_content = "<color=#e8d9bb>두 사람이 어렴풋이 받은 인도는, 과거 또는 미래의 누군가가 시공간의 흐름 속에서\n전력을 다해 전했던 진심일 지도 모른다.</color>",
  ui_story_5084_50841400_214_dialog_content = "<color=#e8d9bb>빅토리아는 그 운명의 강에서 수많은 동행자의 모습을 보았고,\n그 모습들은 조금씩 그녀가 계속해서 진리를 찾아 나설 수 있게 해 주는 용기가 되었다.</color>",
  ui_story_5084_50841400_215_dialog_content = "<color=#e8d9bb>그리고 기나긴 시간의 강을 표류하는 사람은, 이 모든 것을 지켜보고 있을 것이다.</color>",
  ui_story_5084_50841400_216_dialog_content = "<color=#e8d9bb>강의 흐름이 바뀌고, 성전에는 기록이 남았다.\n그러나 지금 이 순간의 빅토리아는 도저히 선뜻 페이지를 뒤로 넘길 수 없었다.</color>",
  ui_story_5084_50841400_217_dialog_content = "...그럼 나처럼 은둔 수행을 신봉하는 분이란 말인가?",
  ui_story_5084_50841400_218_dialog_content = "뭐, 진리의 결사의 연회에 참여하지 않는 건 충분히 이해가 되는군.\n은둔자들은 그러기 마련이거든.",
  ui_story_5084_50841400_219_dialog_content = "설마 은둔자도 조직 같은 게 있어?",
  ui_story_5084_50841400_220_dialog_content = "조직까진 아니다만... 일설에 따르면 이 계파는 1915년, 왈라지 마을의\n어느 신비로운 남신도가 세운 것이라고 하더군.",
  ui_story_5084_50841400_221_dialog_content = "빅토리아 님이 말씀해 주신 적 없는 거냐?",
  ui_story_5084_50841400_222_dialog_content = "너희가 오로리안들이 모이는 마을에서 활동하는 데 비하면,\n나를 비롯해 은둔자를 자칭하는 멤버들은 어쩌다 한 번 바깥에서 마주치는 게 전부다.",
  ui_story_5084_50841400_223_dialog_content = "당신들은... 보통 뭘 합니까?",
  ui_story_5084_50841400_224_dialog_content = "탁 트인 곳을 찾아다니거나, 숨겨진 구석을 탐색하기도 하지...",
  ui_story_5084_50841400_225_dialog_content = "그다음엔?",
  ui_story_5084_50841400_226_dialog_content = "그곳에 머물며, 아무 생각도 하지 않는다.",
  ui_story_5084_50841400_227_dialog_content = "그 은둔 수행이란 거 말인데... 그냥 책 보고 공부하기 싫은 거 아냐...?",
  ui_story_5084_50841400_228_dialog_content = "이는 어쩌면 그 은둔 수행의 대가가 이 세상에 있는 모든 책을\n이미 다 읽었기 때문일지도 모른다.",
  ui_story_5084_50841400_229_dialog_content = "근데 그 대가란 사람은 그냥 더 볼 책이 없으니까 그런 데 있는 거고,\n너흰 책이 있어도 안 보는 것 같은데...",
  ui_story_5084_50841400_230_dialog_content = "정말 대단한 분이시군요! 그분의 존함은 무엇입니까?",
  ui_story_5084_50841400_231_dialog_content = "아무도 그 사람의 이름을 모른다. 하지만 난 몇 번 만난 적이 있었지.",
  ui_story_5084_50841400_232_dialog_content = "마르고 큰 키에, 가끔씩 옛 귀족의 기품이 느껴지는 사람이었다...",
  ui_story_5084_50841400_233_dialog_content = "검은 모자와 붉은 망토를 애용하고, 검은 말을 타고 다녀서 그런 거겠지.",
  ui_story_5084_50841400_234_dialog_content = "......?",
  ui_story_5084_50841400_235_dialog_content = "행적은 비밀스럽지만, 늘 여행을 다녔는데, 일설에는 그 사람이\n먼 과거의 인연과 만날 날을 기다리고 있다고도 하더군.",
  ui_story_5084_50841400_236_dialog_content = "...정말 멘토님이셨단 말입니까?!",
  ui_story_5084_50841400_237_dialog_content = "누구라고?",
  ui_story_5084_50841400_238_dialog_content = "그럼 그 사람이 만나러 간다는 과거의 인연이라는 건...",
  ui_story_5084_50841400_239_dialog_content = "<color=#e8d9bb>「모든 것이 끝나면, 그때 이곳에서 만나도록 하자」, 당시의 그는 이렇게 말했다.</color>",
  ui_story_5084_50841400_240_dialog_content = "<color=#e8d9bb>빅토리아는 여전히 창가에 서 있었고, 그녀의 눈은 시간의 흐름을 관통하여\n진리를 추구하는 이들의 모습을 응시했다.</color>",
  ui_story_5084_50841400_241_dialog_content = "<color=#e8d9bb>그들은 마치 밤하늘의 별처럼, 누군가는 반짝이고, 누군가는 잠시 빛이 사그라지기도 했지만,\n각자 자신만의 방식으로 진리의 의미를 풀어내고 있었다.</color>",
  ui_story_5084_50841400_242_dialog_content = "<color=#e8d9bb>진리를 탐구하는 자는 마치 머나먼 별빛을 쫓는 것과 같으며,\n영혼의 눈이 있어야만 통찰할 수 있다는 사실을 그녀는 잘 알고 있었다.</color>",
  ui_story_5084_50841400_243_dialog_content = "<color=#e8d9bb>반면에 「그」는 이 여정의 안내자로서, 뒤따라오는 사람들을 앞으로 인도할 뿐이었다.</color>",
  ui_story_5084_50841400_244_dialog_content = "<color=#e8d9bb>창밖의 그는 가볍게 한숨을 내쉬었다.\n오늘날 진리의 결사의 모든 구성원은 모두 그의 자녀나 다름없었다.</color>",
  ui_story_5084_50841400_245_dialog_content = "<color=#e8d9bb>설령 저들의 앞에 아무리 굴곡진 길이 펼쳐진다 하더라도,\n가장 어두운 순간에 빅토리아가 저들을 위해 등불을 밝혀 주리란 사실을 그는 알고 있었다.</color>",
  ui_story_5084_50841400_246_dialog_content = "<color=#e8d9bb>또한 창가의 그녀 역시 고독한 탐구자라는 사실은 오직 그만이 알고 있었다.</color>",
  ui_story_5084_50841400_247_dialog_content = "<color=#e8d9bb>빅토리아는 마음의 소리가 밤하늘에 울려 퍼지도록 두 눈을 감았다.</color>",
  ui_story_5084_50841400_248_dialog_content = "<color=#e8d9bb>그녀는 홀로 수행하는 이의 적막함도, 뜻을 이루기 위해 모인 이들이 자아내는 소란스러움도,\n서로 다르지만 모두 진리로 통하는 길이라는 것을 알고 있었다.</color>",
  ui_story_5084_50841400_249_dialog_content = "<color=#e8d9bb>「진리란 영원히 끝나지 않는 탐색이다」, 그는 나지막이 말했다.</color>",
  ui_story_5084_50841400_250_dialog_content = "<color=#e8d9bb>「그리고 나는 진리를 찾는 너희의 여정 가운데에서, 꿋꿋이 너희를 지켜보며 인도할 것이다.」</color>"
}
return config
